 status text not null default 'DRAFT' check (status in ('DRAFT','IN_REVIEW','APPROVED','ARCHIVED')),
 organization_name text not null default '', cost_center text not null default 'ALL',
 opening_cash numeric not null default 0, minimum_cash_target numeric not null default 0 check (minimum_cash_target >= 0),
 assumptions jsonb not null default '{}'::jsonb, notes text not null default '',
 created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(user_id,fiscal_year,scenario,organization_name,cost_center)
)
;
create table if not exists public.budget_lines (
 id uuid primary key default gen_random_uuid(), plan_id uuid not null references public.budget_plans(id) on delete cascade,
 user_id uuid not null references public.profiles(id) on delete cascade,
 category text not null check (category in ('REVENUE','COGS','OPEX','CAPEX','FINANCING','ZAKAT')),
 name text not null, line_type text not null check (line_type in ('REVENUE','EXPENSE','CASH')), sort_order integer not null default 0,
 monthly_budget numeric[] not null default array_fill(0::numeric,array[12]), monthly_actual numeric[] not null default array_fill(0::numeric,array[12]),
 monthly_forecast numeric[] not null default array_fill(0::numeric,array[12]), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check (array_length(monthly_budget,1)=12), check (array_length(monthly_actual,1)=12), check (array_length(monthly_forecast,1)=12)
)
;
create table if not exists public.budget_approval_events (
