\echo MIGRATION 20260922204907 fix_organization_members_bootstrap_rls
-- Avoid recursive organization_members policies and allow the owner to
-- bootstrap the first membership row when creating a new organization.
create or replace function public.is_organization_admin(p_organization_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.organization_members m
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
      and m.role in ('OWNER', 'ADMIN')
  );
$$
;
revoke all on function public.is_organization_admin(uuid) from public
;
grant execute on function public.is_organization_admin(uuid) to authenticated
;
drop policy if exists org_member_read on public.organization_members
;
create policy org_member_read on public.organization_members
  for select to public
  using (
    user_id = auth.uid()
    or public.is_organization_admin(organization_id)
  )
;
drop policy if exists org_member_manage on public.organization_members
;
create policy org_member_manage on public.organization_members
  for all to public
  using (
    public.is_organization_admin(organization_id)
    or (
      user_id = auth.uid()
      and role = 'OWNER'
      and exists (
        select 1
        from public.organizations o
        where o.id = organization_members.organization_id
          and o.owner_user_id = auth.uid()
      )
    )
  )
  with check (
    public.is_organization_admin(organization_id)
    or (
      user_id = auth.uid()
      and role = 'OWNER'
      and exists (
        select 1
        from public.organizations o
        where o.id = organization_members.organization_id
          and o.owner_user_id = auth.uid()
      )
    )
  )
;

\echo MIGRATION 20260922205139 backfill_legacy_budget_organizations
-- Create organization references for legacy budget plans that previously
-- stored the organization only as free text. Existing budget data is kept.
with legacy as (
  select
    user_id,
    max(nullif(trim(organization_name), '')) as organization_name
  from public.budget_plans
  where nullif(trim(organization_name), '') is not null
  group by user_id
), inserted as (
  insert into public.organizations (owner_user_id, name, entity_type, base_currency)
  select l.user_id, l.organization_name, 'FAMILY', 'SAR'
  from legacy l
  where not exists (
    select 1
    from public.organizations o
    where o.owner_user_id = l.user_id
      and lower(trim(o.name)) = lower(trim(l.organization_name))
  )
  returning id, owner_user_id
)
insert into public.organization_members (organization_id, user_id, role, status)
select id, owner_user_id, 'OWNER', 'ACTIVE'
from inserted
on conflict (organization_id, user_id) do nothing
;
insert into public.organization_members (organization_id, user_id, role, status)
select o.id, o.owner_user_id, 'OWNER', 'ACTIVE'
from public.organizations o
join (
  select
    user_id,
    max(nullif(trim(organization_name), '')) as organization_name
  from public.budget_plans
  where nullif(trim(organization_name), '') is not null
  group by user_id
) l
  on l.user_id = o.owner_user_id
 and lower(trim(o.name)) = lower(trim(l.organization_name))
on conflict (organization_id, user_id) do nothing
;

