\echo MIGRATION 20260923032558 20260923190000_organization_hierarchy
-- Establish a safe holding-company hierarchy for budget organizations.
alter table public.organizations
  add column if not exists parent_organization_id uuid,
  add column if not exists organization_kind text not null default 'SUBSIDIARY',
  add column if not exists sort_order integer not null default 100
;
do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'organizations_parent_organization_id_fkey'
  ) then
    alter table public.organizations
      add constraint organizations_parent_organization_id_fkey
      foreign key (parent_organization_id)
      references public.organizations(id)
      on delete restrict;
  end if;

  if not exists (
    select 1 from pg_constraint
    where conname = 'organizations_organization_kind_check'
  ) then
    alter table public.organizations
      add constraint organizations_organization_kind_check
      check (organization_kind in ('HOLDING', 'SUBSIDIARY'));
  end if;
end $$
;
create index if not exists idx_organizations_parent_sort
  on public.organizations(parent_organization_id, sort_order, name)
;
with holding as (
  select id
  from public.organizations
  where lower(trim(name)) in (
    lower('شركة ليفانت القابضة - الادارة'),
    lower('شركة ليفانت القابضة - الإدارة'),
    lower('شركة ليفانت القابضة')
  )
  order by created_at
  limit 1
)
update public.organizations o
set organization_kind = 'HOLDING',
    parent_organization_id = null,
    sort_order = 10,
    updated_at = now()
from holding h
where o.id = h.id
;
with holding as (
  select id
  from public.organizations
  where organization_kind = 'HOLDING'
  order by sort_order, created_at
  limit 1
)
update public.organizations o
set organization_kind = 'SUBSIDIARY',
    parent_organization_id = h.id,
    sort_order = 20,
    updated_at = now()
from holding h
where o.id <> h.id
  and lower(trim(o.name)) in (
    lower('شركة دعم الاعمال'),
    lower('شركة دعم الأعمال')
  )
;

\echo MIGRATION 20260923035344 20260923200000_cost_center_types
-- Add a required classification for organization cost centers.
alter table public.organization_cost_centers
  add column if not exists center_type text
;
update public.organization_cost_centers c
set center_type = case
  when upper(c.code) = 'HQ' then 'ADMIN'
  when upper(c.code) = 'OPERATIONS' then 'OPERATING'
  when lower(trim(c.name)) in (
    lower('مشروع تطوير نظام مالي'),
    lower('مشروع تطوير مالي')
  ) then 'INVESTMENT'
  when lower(trim(c.name)) in (
    lower('الإدارة العامة'),
    lower('الادارة')
  ) then 'ADMIN'
  else 'OPERATING'
end
where c.center_type is null
;
alter table public.organization_cost_centers
  alter column center_type set not null
;
do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'organization_cost_centers_center_type_check'
  ) then
    alter table public.organization_cost_centers
      add constraint organization_cost_centers_center_type_check
      check (center_type in ('ADMIN','OPERATING','INVESTMENT','TREASURY','FINANCING'));
  end if;
end $$
;
create index if not exists idx_org_cost_centers_org_type
  on public.organization_cost_centers(organization_id, center_type, active, name)
;
grant select, insert, update on public.organization_cost_centers to authenticated
;

