grant execute on function public.prepare_vat_financial_event(text,uuid,uuid,date,uuid,uuid),public.post_vat_financial_event(uuid) to authenticated
;

\echo MIGRATION 20261006143410 controlled_cash_settlement_prod_v1
create or replace function private.cash_post_financial_settlement_atomic(p_financial_event_id uuid,p_account_id uuid,p_direction text,p_settlement_date date,p_amount numeric,p_currency text,p_exchange_rate numeric,p_base_amount numeric,p_allocations jsonb default '[]') returns jsonb language plpgsql security definer set search_path='pg_catalog','public','private','extensions' as $$
declare e public.financial_events%rowtype;a public.liquidity_accounts%rowtype;sid uuid;x record;o public.financial_event_obligations%rowtype;f public.liquidity_flows%rowtype;allocated numeric:=0;finger text;
begin
if auth.uid() is null then raise exception 'UNAUTHORIZED';end if;select * into e from public.financial_events where id=p_financial_event_id for update;if e.id is null then raise exception 'FINANCIAL_EVENT_NOT_FOUND';end if;
if e.event_type<>'SETTLEMENT' or e.status<>'COMMITTED' then raise exception 'SETTLEMENT_EVENT_MUST_BE_COMMITTED';end if;
if not public.financial_core_can(e.organization_id,'financial_core.post') or not public.effective_organization_permission(e.organization_id,'liquidity.settle',p_base_amount,e.base_currency) then raise exception 'CASH_SETTLEMENT_POST_DENIED';end if;
if not public.financial_event_has_valid_approval(e.id) then raise exception 'VALID_APPROVAL_REQUIRED';end if;
if upper(p_direction) not in('INFLOW','OUTFLOW') or p_amount<=0 or p_exchange_rate<=0 or round(p_amount*p_exchange_rate,4)<>round(p_base_amount,4) then raise exception 'SETTLEMENT_AMOUNT_DIRECTION_OR_FX_INVALID';end if;
select * into a from public.liquidity_accounts where id=p_account_id and organization_id=e.organization_id and active for update;if a.id is null then raise exception 'CASH_ACCOUNT_NOT_FOUND_OR_INACTIVE';end if;if a.currency<>upper(p_currency) then raise exception 'CASH_ACCOUNT_CURRENCY_MISMATCH';end if;
finger:=encode(extensions.digest(convert_to(private.canonical_financial_json(jsonb_build_object('event',e.id,'account',p_account_id,'direction',upper(p_direction),'date',p_settlement_date,'amount',p_amount,'currency',upper(p_currency),'rate',p_exchange_rate,'base',p_base_amount,'allocations',coalesce(p_allocations,'[]')))::text,'UTF8'),'sha256'),'hex');
select id into sid from public.liquidity_settlements where organization_id=e.organization_id and financial_event_id=e.id;if sid is not null then return jsonb_build_object('financial_event_id',e.id,'liquidity_settlement_id',sid,'status','POSTED','idempotent_replay',true);end if;
for x in select * from jsonb_to_recordset(coalesce(p_allocations,'[]')) as q(obligation_id uuid,flow_id uuid,amount numeric,base_amount numeric,flow_amount numeric,flow_currency text,flow_exchange_rate numeric) loop
select * into o from public.financial_event_obligations where id=x.obligation_id and organization_id=e.organization_id;if o.id is null or o.adjusts_obligation_id is not null then raise exception 'SETTLEMENT_OBLIGATION_INVALID';end if;
if (upper(p_direction)='OUTFLOW' and o.obligation_type<>'PAYABLE')or(upper(p_direction)='INFLOW' and o.obligation_type<>'RECEIVABLE') then raise exception 'SETTLEMENT_DIRECTION_OBLIGATION_TYPE_MISMATCH';end if;
if x.base_amount>coalesce((select outstanding_base_amount from public.financial_event_obligation_balances where obligation_id=o.id),o.settleable_base_amount) then raise exception 'FINANCIAL_CORE_OVER_SETTLEMENT';end if;
allocated:=allocated+x.base_amount;
end loop;
if allocated>p_base_amount then raise exception 'SETTLEMENT_ALLOCATIONS_EXCEED_MOVEMENT';end if;
insert into public.liquidity_settlements(organization_id,entity_id,account_id,direction,settlement_date,amount,currency,exchange_rate,base_currency,base_amount,source_module,source_event_key,financial_event_id,payload_fingerprint,created_by,posted_by)
values(e.organization_id,e.entity_id,p_account_id,upper(p_direction),p_settlement_date,p_amount,upper(p_currency),p_exchange_rate,e.base_currency,p_base_amount,e.source_module,e.source_event_key,e.id,finger,auth.uid(),auth.uid()) returning id into sid;
for x in select * from jsonb_to_recordset(coalesce(p_allocations,'[]')) as q(obligation_id uuid,flow_id uuid,amount numeric,base_amount numeric,flow_amount numeric,flow_currency text,flow_exchange_rate numeric) loop
insert into public.financial_event_obligation_allocations(organization_id,application_event_id,obligation_id,allocation_type,amount,currency,exchange_rate,base_currency,base_amount) values(e.organization_id,e.id,x.obligation_id,'PAYMENT',x.amount,upper(p_currency),p_exchange_rate,e.base_currency,x.base_amount);
if x.flow_id is not null then update public.liquidity_flows set settled_amount=least(amount,settled_amount+coalesce(x.flow_amount,x.amount)),settlement_status=case when settled_amount+coalesce(x.flow_amount,x.amount)>=amount then 'SETTLED' else 'PARTIAL' end,account_id=coalesce(account_id,p_account_id),updated_at=now() where id=x.flow_id and organization_id=e.organization_id;
insert into public.liquidity_flow_settlement_allocations(organization_id,settlement_id,flow_id,financial_event_id,allocation_type,amount,currency,exchange_rate,base_currency,base_amount,created_by) values(e.organization_id,sid,x.flow_id,e.id,'PAYMENT',coalesce(x.flow_amount,x.amount),coalesce(upper(x.flow_currency),upper(p_currency)),coalesce(x.flow_exchange_rate,p_exchange_rate),e.base_currency,x.base_amount,auth.uid());end if;end loop;
update public.liquidity_accounts set current_balance=current_balance+case when upper(p_direction)='INFLOW' then p_amount else -p_amount end,current_balance_base=current_balance_base+case when upper(p_direction)='INFLOW' then p_base_amount else -p_base_amount end,updated_at=now() where id=p_account_id;
insert into public.liquidity_settlement_status_history(organization_id,settlement_id,from_status,to_status,actor_id,reason) values(e.organization_id,sid,null,'POSTED',auth.uid(),'Financial Core settlement');
perform public.transition_financial_event(e.id,'ACTUAL','Atomic cash settlement post');
return jsonb_build_object('financial_event_id',e.id,'liquidity_settlement_id',sid,'status','POSTED','idempotent_replay',false);end$$
;
create or replace function public.post_financial_settlement(p_financial_event_id uuid,p_account_id uuid,p_direction text,p_settlement_date date,p_amount numeric,p_currency text,p_exchange_rate numeric,p_base_amount numeric,p_allocations jsonb default '[]') returns jsonb language sql security definer set search_path='pg_catalog','public','private' as $$select private.cash_post_financial_settlement_atomic($1,$2,$3,$4,$5,$6,$7,$8,$9);$$
;
grant execute on function public.post_financial_settlement(uuid,uuid,text,date,numeric,text,numeric,numeric,jsonb) to authenticated
;

\echo MIGRATION 20261006143440 financial_budget_configuration_and_consolidation_v1
create or replace function public.configure_financial_budget(p_key text,p_payload jsonb) returns uuid language plpgsql security definer set search_path='pg_catalog','public','private','extensions' as $$
declare org uuid;act text;rid uuid;plan uuid;entity uuid;center uuid;begin if auth.uid() is null then raise exception 'UNAUTHORIZED';end if;org:=(p_payload->>'organization_id')::uuid;act:=upper(p_payload->>'action');entity:=nullif(p_payload->>'entity_id','')::uuid;center:=nullif(p_payload->>'cost_center_id','')::uuid;if not public.financial_budget_can(org,entity,center,true) then raise exception 'BUDGET_CONFIG_DENIED';end if;
if act='MAP' then insert into public.financial_budget_mappings(organization_id,plan_id,budget_line_id,classification_id,entity_id,cost_center_id,metric_policy,effective_from,effective_to,created_by) values(org,(p_payload->>'plan_id')::uuid,(p_payload->>'budget_line_id')::uuid,(p_payload->>'classification_id')::uuid,entity,center,p_payload->>'metric_policy',(p_payload->>'effective_from')::date,(p_payload->>'effective_to')::date,auth.uid()) returning id into rid;
elsif act='RETIRE_MAPPING' then insert into public.financial_budget_retirements(organization_id,mapping_id,reason,created_by) values(org,(p_payload->>'mapping_id')::uuid,p_payload->>'reason',auth.uid()) returning id into rid;
elsif act='BIND_PLAN' then plan:=(p_payload->>'plan_id')::uuid;insert into public.financial_budget_plan_ownership(plan_id,organization_id,entity_id,cost_center_id,fiscal_start,adopted_by,legacy_snapshot) select bp.id,org,entity,center,(p_payload->>'fiscal_start')::date,auth.uid(),jsonb_build_object('user_id',bp.user_id,'fiscal_year',bp.fiscal_year,'currency',bp.currency,'scenario',bp.scenario) from public.budget_plans bp where bp.id=plan and bp.user_id=auth.uid() returning plan_id into rid;
else raise exception 'BUDGET_COMMAND_ACTION_INVALID';end if;return rid;end$$
;
create or replace function public.financial_budget_consolidated(p_holding uuid,p_year integer,p_scenario text default 'BASE') returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public' as $$declare outj jsonb;begin
with recursive tree as(select id,name from public.organizations where id=p_holding union all select o.id,o.name from public.organizations o join tree t on o.parent_organization_id=t.id),plans as(select bp.id,t.id organization_id,t.name from tree t join public.financial_budget_plan_ownership po on po.organization_id=t.id join public.budget_plans bp on bp.id=po.plan_id where bp.fiscal_year=p_year and bp.scenario=p_scenario)
select coalesce(jsonb_agg(jsonb_build_object('organization_id',organization_id,'organization_name',name,'plan_id',id,'report',public.financial_budget_report(id))),'[]'::jsonb) into outj from plans;
return jsonb_build_object('holding_id',p_holding,'fiscal_year',p_year,'scenario',p_scenario,'organizations',outj);end$$
;
grant execute on function public.configure_financial_budget(text,jsonb),public.financial_budget_consolidated(uuid,integer,text) to authenticated
;

\echo MIGRATION 20261006173905 phase2b_reconciliation_views
-- Phase 2B recovery: read-only settlement reconciliation views.
-- Additive only: no table, policy, role, permission, or write-path changes.

create or replace view public.liquidity_flow_settlement_reconciliation as
select f.id as flow_id,f.organization_id,f.entity_id,f.account_id,f.direction,
 f.amount as expected_amount,f.currency,f.settled_amount,
 greatest(f.amount-f.settled_amount,0::numeric)::numeric(24,4) as expected_outstanding,
 f.settlement_status,
 coalesce(sum(case when a.allocation_type='PAYMENT' then a.amount when a.allocation_type='REVERSAL' and original.allocation_type='PAYMENT' then -a.amount else 0 end),0)::numeric(24,4) as net_actual_cash_allocated,
 coalesce(sum(case when a.allocation_type='ADVANCE_APPLICATION' then a.amount when a.allocation_type='REVERSAL' and original.allocation_type='ADVANCE_APPLICATION' then -a.amount else 0 end),0)::numeric(24,4) as net_advance_applied
from public.liquidity_flows f
left join public.liquidity_flow_settlement_allocations a on a.flow_id=f.id and a.organization_id=f.organization_id
left join public.liquidity_flow_settlement_allocations original on original.id=a.reversal_of_allocation_id and original.organization_id=a.organization_id
group by f.id,f.organization_id,f.entity_id,f.account_id,f.direction,f.amount,f.currency,f.settled_amount,f.settlement_status
;
create or replace view public.liquidity_account_settlement_ledger_summary as
select a.id as account_id,a.organization_id,a.entity_id,a.currency,a.current_balance,a.current_balance_base,
 coalesce(sum(s.amount) filter(where s.direction='INFLOW'),0)::numeric(24,4) as settlement_inflows,
 coalesce(sum(s.amount) filter(where s.direction='OUTFLOW'),0)::numeric(24,4) as settlement_outflows,
 coalesce(sum(case when s.direction='INFLOW' then s.base_amount else -s.base_amount end),0)::numeric(24,4) as net_settlement_base_amount
from public.liquidity_accounts a
left join public.liquidity_settlements s on s.account_id=a.id and s.organization_id=a.organization_id
group by a.id,a.organization_id,a.entity_id,a.currency,a.current_balance,a.current_balance_base
;

\echo MIGRATION 20261006174613 phase2b_cash_reconciliation_views
-- Phase 2B recovery: read-only Financial Core ↔ Cash reconciliation views.
-- Additive only. No write-path, RLS, governance, role, or balance changes.

create or replace view public.financial_core_cash_event_flow_links as
with explicit_links as (
 select distinct f.organization_id,f.id as liquidity_flow_id,e.id as financial_event_id,'EXPLICIT_CASH_FLOW_LINK'::text as mapping_method
 from public.liquidity_flows f
 join public.financial_event_links l on l.organization_id=f.organization_id and l.link_type='CASH_FLOW' and l.target_module=any(array['liquidity_flows'::text,'liquidity_flow'::text]) and l.target_record_id=f.id and l.related_event_id is null
 join public.financial_events e on e.id=l.event_id and e.organization_id=l.organization_id
), source_key_links as (
 select distinct f.organization_id,f.id as liquidity_flow_id,e.id as financial_event_id,'SHARED_IDEMPOTENCY_KEY'::text as mapping_method
 from public.liquidity_flows f
 join public.financial_events e on e.organization_id=f.organization_id and e.source_module=f.source_module and e.source_event_key=f.source_event_key
 where f.source_event_key is not null and f.source_module is not null
 and not exists(select 1 from explicit_links x where x.organization_id=f.organization_id and x.liquidity_flow_id=f.id and x.financial_event_id=e.id)
)
select * from explicit_links union all select * from source_key_links
;
create or replace view public.financial_core_cash_reconciliation as
with pair_rows as (
 select m.organization_id,m.liquidity_flow_id,m.financial_event_id,m.mapping_method,e.event_type,e.status financial_event_status,
 e.source_module financial_source_module,e.source_record_id financial_source_record_id,e.source_event_key financial_source_event_key,e.entity_id financial_entity_id,e.id event_id,
 (select l.related_event_id from public.financial_event_links l where l.organization_id=e.organization_id and l.event_id=e.id and l.link_type='SETTLEMENT_OF' order by l.created_at,l.id limit 1) original_event_id
 from public.financial_core_cash_event_flow_links m join public.financial_events e on e.id=m.financial_event_id and e.organization_id=m.organization_id
), flow_rows as (
 select f.organization_id,f.entity_id,f.id liquidity_flow_id,f.account_id,a.name liquidity_account_name,a.account_type liquidity_account_type,a.currency liquidity_account_currency,
 f.direction,f.flow_type,f.amount flow_amount,f.currency flow_currency,f.base_amount flow_base_amount,f.status liquidity_flow_status,f.settled_amount cash_settled_amount,
 f.settlement_status cash_settlement_status,f.source_module cash_source_module,f.source_record_id cash_source_record_id,f.source_event_key cash_source_event_key,
 f.transfer_id,f.intercompany_transfer_id,f.budget_line_id,
 case when f.intercompany_transfer_id is not null then 'INTERCOMPANY_TRANSFER' when f.transfer_id is not null then 'BANK_TO_BANK_TRANSFER' else 'OPERATING_CASH_FLOW' end cash_movement_kind,
 t.source_account_id transfer_source_account_id,t.destination_account_id transfer_destination_account_id,t.source_amount transfer_source_amount,t.source_currency transfer_source_currency,
 t.destination_amount transfer_destination_amount,t.destination_currency transfer_destination_currency,it.holding_organization_id,it.source_organization_id transfer_source_organization_id,
 it.destination_organization_id transfer_destination_organization_id,it.transaction_type intercompany_transaction_type,it.source_account_id intercompany_source_account_id,
 it.destination_account_id intercompany_destination_account_id,it.source_base_amount intercompany_source_base_amount,it.destination_base_amount intercompany_destination_base_amount
 from public.liquidity_flows f
 left join public.liquidity_accounts a on a.id=f.account_id and a.organization_id=f.organization_id
 left join public.liquidity_transfers t on t.id=f.transfer_id and t.organization_id=f.organization_id
 left join public.liquidity_intercompany_transfers it on it.id=f.intercompany_transfer_id and (f.organization_id=it.source_organization_id or f.organization_id=it.destination_organization_id)
)
select f.*,p.financial_event_id,p.event_id,p.original_event_id,p.mapping_method,p.event_type,p.financial_event_status,p.financial_source_module,p.financial_source_record_id,p.financial_source_event_key,p.financial_entity_id,
 case when p.financial_event_id is null then 'UNMATCHED_CASH_FLOW' when p.event_type='SETTLEMENT' then 'SETTLEMENT_CASH_FLOW' else 'SOURCE_EVENT_CASH_FLOW' end reconciliation_relation,
 case when p.event_type='SETTLEMENT' then (select case when count(distinct l.cash_direction)=1 then min(l.cash_direction) else 'MIXED' end from public.financial_event_lines l where l.event_id=p.financial_event_id and l.organization_id=p.organization_id)
      when p.event_type=any(array['REVENUE','RECEIVABLE']) then 'INFLOW' when p.event_type=any(array['EXPENSE','PAYABLE','ASSET_PURCHASE']) then 'OUTFLOW' else 'NON_CASH_OR_TRANSFER' end expected_direction,
 case when p.financial_event_id is null then 'UNMATCHED'
      when p.event_type=any(array['TRANSFER','REVERSAL']) then 'REVIEW_EVENT_TYPE'
      when p.event_type='SETTLEMENT' and exists(select 1 from public.financial_event_lines l where l.event_id=p.financial_event_id and l.organization_id=p.organization_id and l.cash_direction=any(array['INFLOW','OUTFLOW']) and l.cash_direction<>f.direction) then 'DIRECTION_MISMATCH'
      when p.event_type<>all(array['SETTLEMENT','TRANSFER','REVERSAL']) and p.event_type=any(array['REVENUE','RECEIVABLE']) and f.direction<>'INFLOW' then 'DIRECTION_MISMATCH'
      when p.event_type<>all(array['SETTLEMENT','TRANSFER','REVERSAL']) and p.event_type=any(array['EXPENSE','PAYABLE','ASSET_PURCHASE']) and f.direction<>'OUTFLOW' then 'DIRECTION_MISMATCH'
      else 'MATCHED' end reconciliation_status
from flow_rows f left join pair_rows p on p.organization_id=f.organization_id and p.liquidity_flow_id=f.liquidity_flow_id
;
create or replace view public.financial_core_event_cash_position as
select e.id event_id,e.organization_id,e.entity_id,e.source_module,e.source_record_id,e.source_event_key,e.event_type,e.status,
 case when e.event_type='SETTLEMENT' then coalesce((select case when count(distinct l.cash_direction)=1 then min(l.cash_direction) else 'MIXED' end from public.financial_event_lines l where l.event_id=e.id and l.organization_id=e.organization_id),'NON_CASH')
      when e.event_type=any(array['REVENUE','RECEIVABLE']) then 'INFLOW' when e.event_type=any(array['EXPENSE','PAYABLE','ASSET_PURCHASE']) then 'OUTFLOW' else 'NON_CASH_OR_TRANSFER' end expected_cash_direction,
 s.settlement_status,s.settled_base_amount,s.due_base_amount,greatest(s.due_base_amount-s.settled_base_amount,0)::numeric(24,4) outstanding_base_amount,
 coalesce(x.linked_flow_count,0) linked_flow_count,coalesce(x.mismatched_flow_count,0) mismatched_flow_count,
 case when e.status=any(array['CANCELLED','REVERSED']) then 'NO_FUTURE_CASH_EXPECTED' when e.event_type='TRANSFER' then 'TRANSFER_SEMANTICS_REQUIRED'
      when e.event_type=any(array['REVENUE','RECEIVABLE','EXPENSE','PAYABLE','ASSET_PURCHASE']) and s.settlement_status='PAID' then 'SETTLED'
      when e.event_type=any(array['REVENUE','RECEIVABLE','EXPENSE','PAYABLE','ASSET_PURCHASE']) and s.settled_base_amount>0 then 'PARTIALLY_SETTLED'
      when e.event_type=any(array['REVENUE','RECEIVABLE','EXPENSE','PAYABLE','ASSET_PURCHASE']) then 'EXPECTED_FUTURE_CASH' else 'NON_CASH_OR_SPECIAL_EVENT' end cash_position
from public.financial_events e
left join public.financial_event_settlement_status s on s.event_id=e.id and s.organization_id=e.organization_id
left join lateral (
 select count(distinct r.liquidity_flow_id)::integer linked_flow_count,
 count(distinct r.liquidity_flow_id) filter(where r.reconciliation_status='DIRECTION_MISMATCH')::integer mismatched_flow_count
 from public.financial_core_cash_reconciliation r where r.organization_id=e.organization_id and (r.financial_event_id=e.id or r.original_event_id=e.id)
) x on true
;

