\echo MIGRATION 20261007211501 delete_unissued_zatca_draft_bundle_v1
create or replace function public.delete_unissued_zatca_draft_bundle(p_einvoice_id uuid)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  v_org uuid; v_status text; v_doc uuid; v_notes text; v_event uuid; v_flow uuid;
begin
  select organization_id,status,accounting_document_id into v_org,v_status,v_doc
  from public.vat_einvoices where id=p_einvoice_id for update;
  if v_org is null then raise exception 'EINVOICE_NOT_FOUND'; end if;
  if not public.is_organization_admin(v_org,auth.uid()) then raise exception 'ORGANIZATION_ADMIN_REQUIRED'; end if;
  if v_status <> 'DRAFT' then raise exception 'EINVOICE_DELETE_ISSUED_FORBIDDEN'; end if;

  if v_doc is not null then
    select notes into v_notes from public.vat_documents where id=v_doc and organization_id=v_org;
    if coalesce(v_notes,'') <> 'Created from ZATCA invoice workspace' then
      -- Existing accounting invoices remain the financial source of truth; only remove the ZATCA draft.
      delete from public.vat_einvoice_lines where invoice_id=p_einvoice_id;
      delete from public.vat_einvoices where id=p_einvoice_id;
      return jsonb_build_object('deleted',true,'accounting_document_deleted',false);
    end if;

    select event_id into v_event from public.financial_event_links
      where organization_id=v_org and target_module='vat_documents' and target_record_id=v_doc and link_type='SOURCE'
      limit 1;
    if v_event is not null and exists (
      select 1 from public.financial_event_obligation_allocations a
      join public.financial_event_obligations o on o.id=a.obligation_id
      where o.event_id=v_event
    ) then raise exception 'EINVOICE_DELETE_SETTLED_FORBIDDEN'; end if;

    select id into v_flow from public.liquidity_flows
      where organization_id=v_org and source_module='VAT_INTEGRATION' and source_record_id=v_doc limit 1;
    if v_flow is not null and exists(select 1 from public.liquidity_settlements where flow_id=v_flow) then
      raise exception 'EINVOICE_DELETE_SETTLED_FORBIDDEN';
    end if;

    delete from public.vat_einvoice_lines where invoice_id=p_einvoice_id;
    delete from public.vat_einvoices where id=p_einvoice_id;
    if v_flow is not null then
      delete from public.financial_event_links where target_module='liquidity_flows' and target_record_id=v_flow;
      delete from public.liquidity_flows where id=v_flow;
    end if;
    if v_event is not null then
      delete from public.financial_vat_source_bindings where event_id=v_event;
      delete from public.financial_event_status_history where event_id=v_event;
      delete from public.financial_event_links where event_id=v_event;
      delete from public.financial_event_obligations where event_id=v_event;
      delete from public.financial_event_lines where event_id=v_event;
      delete from public.financial_events where id=v_event;
    end if;
    delete from public.vat_documents where id=v_doc;
    return jsonb_build_object('deleted',true,'accounting_document_deleted',true);
  end if;

  delete from public.vat_einvoice_lines where invoice_id=p_einvoice_id;
  delete from public.vat_einvoices where id=p_einvoice_id;
  return jsonb_build_object('deleted',true,'accounting_document_deleted',false);
end $$
;
revoke all on function public.delete_unissued_zatca_draft_bundle(uuid) from public
;
grant execute on function public.delete_unissued_zatca_draft_bundle(uuid) to authenticated
;

\echo MIGRATION 20261008031940 atomic_zatca_draft_amendment
-- One transaction replaces the draft header and lines and synchronizes its unposted sales source.
-- Invoker security preserves the organization RLS and existing write permissions.
create or replace function public.amend_zatca_draft_atomic(p_invoice_id uuid, p_header jsonb, p_lines jsonb)
returns jsonb language plpgsql security invoker set search_path = '' as $fn$
declare
  e public.vat_einvoices%rowtype;
  h public.vat_einvoices%rowtype;
  d public.vat_documents%rowtype;
  v_event uuid; v_status text; v_counterparty uuid; v_tax_class uuid; v_base text;
  v_net numeric; v_tax numeric; v_gross numeric; v_source_net numeric; v_source_tax numeric;
  v_line_items jsonb; v_changed boolean;
begin
  if auth.uid() is null then raise exception 'UNAUTHORIZED'; end if;
  select * into e from public.vat_einvoices where id=p_invoice_id for update;
  if e.id is null then raise exception 'EINVOICE_DRAFT_NOT_FOUND'; end if;
  if not public.is_organization_admin(e.organization_id) then raise exception 'ORGANIZATION_ADMIN_REQUIRED'; end if;
  if e.status <> 'DRAFT' then raise exception 'EINVOICE_DRAFT_LOCKED'; end if;
  if (p_header->>'organization_id')::uuid is distinct from e.organization_id then raise exception 'EINVOICE_ACCOUNTING_SOURCE_MISMATCH'; end if;
  -- Only editable columns are copied below; IDs, lifecycle, QR and audit fields remain server-owned.
  h := jsonb_populate_record(e,p_header);
  if e.accounting_document_id is not null and h.accounting_document_id is distinct from e.accounting_document_id then
    raise exception 'EINVOICE_ACCOUNTING_SOURCE_MISMATCH';
  end if;
  if e.accounting_document_id is null then e.accounting_document_id := h.accounting_document_id; end if;
  if h.document_type is distinct from e.document_type then raise exception 'EINVOICE_ACCOUNTING_SOURCE_MISMATCH'; end if;
  if h.due_date is null then h.due_date := h.issue_date; end if;
  if h.due_date < h.issue_date then raise exception 'DUE_DATE_BEFORE_ISSUE_DATE'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) not between 1 and 500 then raise exception 'INVALID_EINVOICE_DRAFT'; end if;
  if exists(select 1 from jsonb_to_recordset(p_lines) as l(quantity numeric,unit_price numeric,discount_amount numeric,line_extension_amount numeric)
      where l.quantity<=0 or l.unit_price<0 or l.discount_amount<0 or l.line_extension_amount is distinct from round(l.quantity*l.unit_price-l.discount_amount,2)) then
    raise exception 'INVALID_EINVOICE_DRAFT';
  end if;
  select sum((l->>'line_extension_amount')::numeric) into v_source_net from jsonb_array_elements(p_lines) l;
  select sum(round(t.taxable*t.rate/100,2)) into v_source_tax from (
    select sum((l->>'line_extension_amount')::numeric) taxable,(l->>'tax_rate')::numeric rate
    from jsonb_array_elements(p_lines) l group by l->>'tax_category',l->>'tax_rate'
  ) t;
  if h.tax_exclusive_amount is distinct from v_source_net or h.tax_total_amount is distinct from v_source_tax
    or h.line_extension_amount is distinct from v_source_net or h.tax_inclusive_amount is distinct from v_source_net+v_source_tax
    or h.allowance_total_amount <> 0 or h.tax_total_amount_sar is distinct from round(v_source_tax*h.exchange_rate,2)
    or h.payable_amount is distinct from v_source_net+v_source_tax then raise exception 'EINVOICE_ACCOUNTING_SOURCE_MISMATCH'; end if;
  if exists(select 1 from public.vat_documents where organization_id=e.organization_id and document_type='SALES'
    and document_kind=h.document_type and document_number=h.invoice_number and id is distinct from e.accounting_document_id) then
    raise exception 'ACCOUNTING_INVOICE_NUMBER_EXISTS';
  end if;

  if e.accounting_document_id is not null then
    select * into d from public.vat_documents where id=e.accounting_document_id and organization_id=e.organization_id for update;
    if d.id is null or d.document_type<>'SALES' or d.document_kind<>h.document_type then raise exception 'EINVOICE_ACCOUNTING_SOURCE_MISMATCH'; end if;
    select base_currency into v_base from public.organizations where id=e.organization_id;
    -- ZATCA exchange_rate is explicitly quoted to SAR. A different reporting base needs a separate rate.
    if v_base <> 'SAR' then raise exception 'EINVOICE_ACCOUNTING_BASE_CURRENCY_UNSUPPORTED'; end if;
    v_net := round(v_source_net*h.exchange_rate,2);
    v_tax := round(v_source_tax*h.exchange_rate,2);
    v_gross := v_net+v_tax;
    v_changed := d.document_number is distinct from h.invoice_number or d.transaction_date is distinct from h.issue_date
      or d.due_date is distinct from h.due_date or d.counterparty_contact_id is distinct from h.buyer_contact_id
      or d.net_amount is distinct from v_net or d.tax_amount is distinct from v_tax
      or d.source_currency is distinct from h.currency or d.exchange_rate is distinct from h.exchange_rate
      or exists (
        (select item_name,description,quantity,unit_code,unit_price,discount_amount,tax_category,tax_rate
          from jsonb_populate_recordset(null::public.vat_einvoice_lines,p_lines)
         except
         select item_name,description,quantity,unit_code,unit_price,discount_amount,tax_category,tax_rate
          from public.vat_einvoice_lines where invoice_id=e.id)
        union all
        (select item_name,description,quantity,unit_code,unit_price,discount_amount,tax_category,tax_rate
          from public.vat_einvoice_lines where invoice_id=e.id
         except
         select item_name,description,quantity,unit_code,unit_price,discount_amount,tax_category,tax_rate
          from jsonb_populate_recordset(null::public.vat_einvoice_lines,p_lines))
      );
    if v_changed then
      if h.document_type <> 'INVOICE' then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
      select event_id into v_event from public.financial_event_links where organization_id=e.organization_id
        and link_type='SOURCE' and target_module='vat_documents' and target_record_id=d.id limit 1;
      select status into v_status from public.financial_events where id=v_event for update;
      if exists(select 1 from public.financial_event_approvals where event_id=v_event and decision='APPROVED') then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
      if v_status is null or v_status not in ('DRAFT','PLANNED','COMMITTED') then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
      perform 1 from public.liquidity_flows where organization_id=e.organization_id and source_module='VAT_INTEGRATION' and source_record_id=d.id for update;
      if exists(select 1 from public.financial_event_obligation_allocations a join public.financial_event_obligations o on o.id=a.obligation_id where o.event_id=v_event)
        or exists(select 1 from public.liquidity_flows where organization_id=e.organization_id and source_module='VAT_INTEGRATION' and source_record_id=d.id and settled_amount>0)
        or exists(select 1 from public.financial_event_links l join public.financial_events se on se.id=l.event_id
          where l.organization_id=e.organization_id and l.target_module='liquidity_flows' and l.metadata->>'purpose'='SETTLEMENT_INSTRUCTION'
            and se.status not in ('CANCELLED','REVERSED') and l.target_record_id in (
              select id from public.liquidity_flows where organization_id=e.organization_id and source_module='VAT_INTEGRATION' and source_record_id=d.id)) then
        raise exception 'VAT_DOCUMENT_SETTLED_LOCKED';
      end if;
      -- Serialize projection creation for a newly selected customer and keep it in this transaction.
      perform 1 from public.vat_contacts where id=h.buyer_contact_id and organization_id=e.organization_id
        and contact_type in ('CUSTOMER','BOTH') for update;
      if not found then raise exception 'VAT_CONTACT_TYPE_MISMATCH'; end if;
      select counterparty_id into v_counterparty from public.financial_vat_counterparty_map where organization_id=e.organization_id and vat_contact_id=h.buyer_contact_id;
      if v_counterparty is null then
        select id into v_counterparty from public.liquidity_counterparties where organization_id=e.organization_id
          and notes='VAT identity projection: '||h.buyer_contact_id and active limit 1;
        if v_counterparty is null then
          insert into public.liquidity_counterparties(organization_id,name,party_type,contact_name,phone,email,notes)
            select e.organization_id,name,'CUSTOMER','','','','VAT identity projection: '||id
            from public.vat_contacts where id=h.buyer_contact_id returning id into v_counterparty;
        end if;
        insert into public.financial_vat_counterparty_map(organization_id,vat_contact_id,counterparty_id,created_by)
          values(e.organization_id,h.buyer_contact_id,v_counterparty,auth.uid());
      end if;
      select jsonb_agg(jsonb_build_object('description',l->>'item_name','unit',l->>'unit_code','quantity',l->>'quantity',
        'unit_price',round((l->>'unit_price')::numeric*h.exchange_rate,2)::text,'source_unit_price',l->>'unit_price',
        'discount_amount',round((l->>'discount_amount')::numeric*h.exchange_rate,2)::text,'source_discount_amount',l->>'discount_amount',
        'supply_type',case l->>'tax_category' when 'S' then 'STANDARD' when 'Z' then 'ZERO_RATED' when 'E' then 'EXEMPT' else 'OUT_OF_SCOPE' end,
        'net_amount',round((l->>'line_extension_amount')::numeric*h.exchange_rate,2)::text,'source_net_amount',l->>'line_extension_amount',
        'tax_rate',l->>'tax_rate','tax_amount',round((l->>'tax_amount')::numeric*h.exchange_rate,2)::text,'source_tax_amount',l->>'tax_amount',
        'gross_amount',(round((l->>'line_extension_amount')::numeric*h.exchange_rate,2)+round((l->>'tax_amount')::numeric*h.exchange_rate,2))::text,
        'source_gross_amount',l->>'gross_amount') order by (l->>'line_number')::integer) into v_line_items from jsonb_array_elements(p_lines) l;
      update public.vat_documents set document_number=h.invoice_number,transaction_date=h.issue_date,due_date=h.due_date,
        counterparty_contact_id=h.buyer_contact_id,counterparty_name=h.buyer_name,counterparty_tax_number=h.buyer_vat_number,
        net_amount=v_net,tax_amount=v_tax,gross_amount=v_gross,source_currency=h.currency,exchange_rate=h.exchange_rate,
        source_net_amount=v_source_net,source_tax_amount=v_source_tax,source_gross_amount=v_source_net+v_source_tax,
        line_items=v_line_items,tax_rate=case when v_source_net=0 then 0 else round(v_source_tax/v_source_net*100,2) end
        where id=d.id;
      update public.financial_events set counterparty_id=v_counterparty,event_date=h.issue_date,due_date=h.due_date,
        description='Sales invoice '||h.invoice_number,updated_at=now() where id=v_event;
      update public.financial_event_lines l set amount=v_net,base_amount=v_net where l.event_id=v_event
        and l.classification_id in(select id from public.financial_classifications where organization_id=e.organization_id and classification_type='REVENUE');
      if not found then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
      select id into v_tax_class from public.financial_classifications where organization_id=e.organization_id and classification_type='TAX' and active limit 1;
      if v_tax_class is null then raise exception 'VAT_FINANCIAL_CLASSIFICATIONS_REQUIRED'; end if;
      update public.financial_event_lines set amount=v_tax,base_amount=v_tax where event_id=v_event and classification_id=v_tax_class;
      if not found and v_tax>0 then
        insert into public.financial_event_lines(event_id,organization_id,line_number,description,classification_id,amount,currency,exchange_rate,base_amount,cash_direction,vat_treatment,vat_rate,vat_amount)
        values(v_event,e.organization_id,2,'Output VAT recognition',v_tax_class,v_tax,'SAR',1,v_tax,'NON_CASH','OUT_OF_SCOPE',0,0);
      end if;
      if v_tax=0 then delete from public.financial_event_lines where event_id=v_event and classification_id=v_tax_class; end if;
      update public.financial_event_obligations set settleable_amount=v_gross,settleable_base_amount=v_gross where event_id=v_event and obligation_type='RECEIVABLE';
      if not found then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
      update public.liquidity_flows set amount=v_gross,base_amount=v_gross,due_date=h.due_date,counterparty=h.buyer_name,
        counterparty_id=v_counterparty,reference=h.invoice_number,title='Invoice receivable · '||h.invoice_number,updated_at=now()
        where organization_id=e.organization_id and source_module='VAT_INTEGRATION' and source_record_id=d.id;
    end if;
  end if;
  update public.vat_einvoices set
    accounting_document_id=e.accounting_document_id,
    invoice_number=h.invoice_number,
    document_type=h.document_type,
    invoice_category=h.invoice_category,
    issue_date=h.issue_date,
    issue_time=h.issue_time,
    due_date=h.due_date,
    currency=h.currency,
    exchange_rate=h.exchange_rate,
    buyer_contact_id=h.buyer_contact_id,
    seller_name=h.seller_name,
    seller_vat_number=h.seller_vat_number,
    seller_address=h.seller_address,
    seller_building_number=h.seller_building_number,
    seller_district=h.seller_district,
    seller_additional_number=h.seller_additional_number,
    seller_city=h.seller_city,
    seller_postal_code=h.seller_postal_code,
    seller_country_code=h.seller_country_code,
    buyer_name=h.buyer_name,
    buyer_vat_number=h.buyer_vat_number,
    buyer_address=h.buyer_address,
    buyer_building_number=h.buyer_building_number,
    buyer_district=h.buyer_district,
    buyer_additional_number=h.buyer_additional_number,
    buyer_city=h.buyer_city,
    buyer_postal_code=h.buyer_postal_code,
    buyer_country_code=h.buyer_country_code,
    payment_means_code=h.payment_means_code,
    billing_reference=h.billing_reference,
    preceding_invoice_id=h.preceding_invoice_id,
    note_reason=h.note_reason,
    line_extension_amount=h.line_extension_amount,
    allowance_total_amount=h.allowance_total_amount,
    tax_exclusive_amount=h.tax_exclusive_amount,
    tax_total_amount=h.tax_total_amount,
    tax_inclusive_amount=h.tax_inclusive_amount,
    payable_amount=h.payable_amount,
    tax_total_amount_sar=h.tax_total_amount_sar, updated_at=now()
    where id=e.id returning * into e;
  delete from public.vat_einvoice_lines where invoice_id=e.id;
  insert into public.vat_einvoice_lines(invoice_id,line_number,item_name,description,quantity,unit_code,unit_price,discount_amount,tax_category,tax_rate,tax_exemption_reason_code,tax_exemption_reason,line_extension_amount,tax_amount,gross_amount)
    select e.id,l.line_number,l.item_name,l.description,l.quantity,l.unit_code,l.unit_price,l.discount_amount,l.tax_category,l.tax_rate,l.tax_exemption_reason_code,l.tax_exemption_reason,l.line_extension_amount,l.tax_amount,l.gross_amount
    from jsonb_populate_recordset(null::public.vat_einvoice_lines,p_lines) l;
  return to_jsonb(e)||jsonb_build_object('lines',(select jsonb_agg(to_jsonb(l) order by line_number) from public.vat_einvoice_lines l where invoice_id=e.id));
end $fn$
;
revoke all on function public.amend_zatca_draft_atomic(uuid,jsonb,jsonb) from public,anon
;
grant execute on function public.amend_zatca_draft_atomic(uuid,jsonb,jsonb) to authenticated
;

\echo MIGRATION 20261008031944 amend_pending_invoice_receipt
-- A receipt may be corrected before approval/posting. Posted cash is immutable and requires reversal.
create or replace function public.amend_pending_invoice_receipt(p_event_id uuid,p_account_id uuid,p_date date,p_amount numeric)
returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare
 e public.financial_events%rowtype; f public.liquidity_flows%rowtype; a public.liquidity_accounts%rowtype;
 l public.financial_event_links%rowtype; m jsonb; v_base numeric; v_rate numeric;
begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED'; end if;
 select * into e from public.financial_events where id=p_event_id for update;
 if e.id is null then raise exception 'RECEIPT_NOT_FOUND'; end if;
 if not public.is_organization_admin(e.organization_id) or not public.has_organization_permission(e.organization_id,'liquidity.settle') then raise exception 'ORGANIZATION_ADMIN_REQUIRED'; end if;
 if e.event_type<>'SETTLEMENT' or e.status not in ('DRAFT','PLANNED','COMMITTED')
    or exists(select 1 from public.liquidity_settlements where financial_event_id=e.id)
    or exists(select 1 from public.financial_event_approvals where event_id=e.id and decision='APPROVED') then raise exception 'RECEIPT_EDIT_LOCKED'; end if;
 select * into l from public.financial_event_links where event_id=e.id and organization_id=e.organization_id
   and link_type='OTHER' and target_module='liquidity_flows' and metadata->>'purpose'='SETTLEMENT_INSTRUCTION' for update;
 if l.id is null then raise exception 'SETTLEMENT_INSTRUCTION_REQUIRED'; end if;
 select * into f from public.liquidity_flows where id=l.target_record_id and organization_id=e.organization_id for update;
 if f.id is null or f.source_module<>'VAT_INTEGRATION' or f.direction<>'INFLOW' then raise exception 'RECEIPT_NOT_FOUND'; end if;
 select * into a from public.liquidity_accounts where id=p_account_id and organization_id=e.organization_id and active;
 if a.id is null or a.currency<>f.currency then raise exception 'SETTLEMENT_ACCOUNT_CURRENCY_MISMATCH'; end if;
 if f.account_id is not null and f.account_id<>p_account_id then raise exception 'SETTLEMENT_FLOW_ACCOUNT_MISMATCH'; end if;
 if p_date is null or p_amount is null or p_amount<=0 then raise exception 'SETTLEMENT_AMOUNT_INVALID'; end if;
 if p_amount>f.amount-coalesce(f.settled_amount,0) then raise exception 'SETTLEMENT_EXCEEDS_FLOW_OUTSTANDING'; end if;
 m:=l.metadata; v_rate:=(m->>'exchange_rate')::numeric; v_base:=round(p_amount*v_rate,4);
 if v_rate is null or v_rate<=0 then raise exception 'SETTLEMENT_AMOUNT_INVALID'; end if;
 if (select count(*) from public.financial_event_lines where event_id=e.id)<>1 then raise exception 'RECEIPT_EDIT_LOCKED'; end if;
 update public.financial_event_lines set amount=p_amount,base_amount=v_base where event_id=e.id;
 update public.financial_events set event_date=p_date,updated_at=now() where id=e.id;
 update public.financial_event_links set metadata=m||jsonb_build_object('account_id',p_account_id,'settlement_date',p_date,
   'amount',p_amount,'base_amount',v_base,'flow_amount',p_amount,'amended_by',auth.uid(),'amended_at',now()) where id=l.id;
 insert into public.audit_logs(user_id,entity_type,entity_id,action,old_data,new_data)
 values(auth.uid(),'invoice_receipt',e.id,'AMEND_BEFORE_POSTING',m,jsonb_build_object('account_id',p_account_id,'settlement_date',p_date,'amount',p_amount,'base_amount',v_base));
 return jsonb_build_object('event_id',e.id,'saved',true,'posted',false);
end $fn$
;
revoke all on function public.amend_pending_invoice_receipt(uuid,uuid,date,numeric) from public,anon
;
grant execute on function public.amend_pending_invoice_receipt(uuid,uuid,date,numeric) to authenticated
;

\echo MIGRATION 20261008081740 fix_unissued_invoice_delete_authorization
-- Only the unpublished electronic draft is disposable. Approved recognition,
-- receipt instructions and posted cash must never be erased with its source.
create or replace function public.delete_unissued_zatca_draft_bundle(p_einvoice_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare
 v_org uuid; v_status text; v_doc uuid; v_notes text; v_event uuid; v_flow uuid;
 v_event_status text;
begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED'; end if;
 select organization_id,status,accounting_document_id into v_org,v_status,v_doc
 from public.vat_einvoices where id=p_einvoice_id for update;
 if v_org is null then raise exception 'EINVOICE_NOT_FOUND'; end if;
 -- The deployed helper takes one argument and obtains the actor from auth.uid().
 if not public.is_organization_admin(v_org) then raise exception 'ORGANIZATION_ADMIN_REQUIRED'; end if;
 if v_status<>'DRAFT' then raise exception 'EINVOICE_DELETE_ISSUED_FORBIDDEN'; end if;
 if exists(select 1 from public.vat_einvoices where preceding_invoice_id=p_einvoice_id) then
  raise exception 'EINVOICE_DELETE_REFERENCED_FORBIDDEN';
 end if;
 if v_doc is not null then
  select notes into v_notes from public.vat_documents where id=v_doc and organization_id=v_org for update;
  select event_id into v_event from public.financial_event_links
   where organization_id=v_org and target_module='vat_documents' and target_record_id=v_doc and link_type='SOURCE' limit 1;
  if v_event is not null then
   select status into v_event_status from public.financial_events where id=v_event and organization_id=v_org for update;
  end if;
  select id into v_flow from public.liquidity_flows
   where organization_id=v_org and source_module='VAT_INTEGRATION' and source_record_id=v_doc limit 1 for update;
  if exists(select 1 from public.financial_event_obligation_allocations a
    join public.financial_event_obligations o on o.id=a.obligation_id where o.event_id=v_event)
   or exists(select 1 from public.liquidity_flow_settlement_allocations where flow_id=v_flow)
   or exists(select 1 from public.liquidity_flows where id=v_flow and settled_amount>0)
   or exists(select 1 from public.financial_event_links l join public.financial_events e on e.id=l.event_id
    where l.organization_id=v_org and l.target_module='liquidity_flows' and l.target_record_id=v_flow
     and l.metadata->>'purpose'='SETTLEMENT_INSTRUCTION' and e.status not in ('CANCELLED','REVERSED')) then
   raise exception 'EINVOICE_DELETE_SETTLED_FORBIDDEN';
  end if;
  if coalesce(v_notes,'')='Created from ZATCA invoice workspace' then
   if (v_event is not null and v_event_status not in ('DRAFT','PLANNED','COMMITTED'))
    or exists(select 1 from public.financial_event_approvals where event_id=v_event)
    or exists(select 1 from public.financial_budget_event_routes where event_id=v_event) then
    raise exception 'EINVOICE_DELETE_FINANCIAL_LOCKED';
   end if;
   if exists(select 1 from public.vat_einvoices where accounting_document_id=v_doc and id<>p_einvoice_id)
    or exists(select 1 from public.vat_documents where preceding_document_id=v_doc) then
    raise exception 'EINVOICE_DELETE_REFERENCED_FORBIDDEN';
   end if;
   delete from public.vat_einvoice_lines where invoice_id=p_einvoice_id;
   delete from public.vat_einvoices where id=p_einvoice_id;
   if v_flow is not null then
    delete from public.financial_event_links where organization_id=v_org and target_module='liquidity_flows' and target_record_id=v_flow;
    delete from public.liquidity_flows where id=v_flow and organization_id=v_org;
   end if;
   if v_event is not null then
    delete from public.financial_vat_source_bindings where event_id=v_event and organization_id=v_org;
    delete from public.financial_event_status_history where event_id=v_event and organization_id=v_org;
    delete from public.financial_event_links where event_id=v_event and organization_id=v_org;
    delete from public.financial_event_obligations where event_id=v_event and organization_id=v_org;
    delete from public.financial_event_lines where event_id=v_event and organization_id=v_org;
    delete from public.financial_events where id=v_event and organization_id=v_org;
   end if;
   delete from public.vat_documents where id=v_doc and organization_id=v_org;
   return jsonb_build_object('deleted',true,'accounting_document_deleted',true);
  end if;
 end if;
 -- Imported accounting documents are retained when removing their electronic draft.
 delete from public.vat_einvoice_lines where invoice_id=p_einvoice_id;
 delete from public.vat_einvoices where id=p_einvoice_id;
 return jsonb_build_object('deleted',true,'accounting_document_deleted',false);
end $fn$
;
revoke all on function public.delete_unissued_zatca_draft_bundle(uuid) from public,anon
;
grant execute on function public.delete_unissued_zatca_draft_bundle(uuid) to authenticated
;

\echo MIGRATION 20261008083753 amend_vat_contact_master
-- Master data only: historical invoice snapshots and amounts are untouched.
create or replace function public.amend_vat_contact_master(p_contact_id uuid,p_values jsonb,p_expected_updated_at timestamptz)
returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare c public.vat_contacts%rowtype; h public.vat_contacts%rowtype;
begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED'; end if;
 select * into c from public.vat_contacts where id=p_contact_id for update;
 if c.id is null then raise exception 'VAT_CONTACT_NOT_FOUND'; end if;
 if not public.is_organization_admin(c.organization_id) then raise exception 'ORGANIZATION_ADMIN_REQUIRED'; end if;
 if p_expected_updated_at is null or c.updated_at is distinct from p_expected_updated_at then raise exception 'VAT_CONTACT_EDIT_CONFLICT'; end if;
 h:=jsonb_populate_record(c,p_values);
 if h.organization_id is distinct from c.organization_id or h.contact_type is distinct from c.contact_type then raise exception 'VAT_CONTACT_SCOPE_MISMATCH'; end if;
 if h.name is null or length(trim(h.name)) not between 1 and 200 then raise exception 'INVALID_VAT_CONTACT'; end if;
 update public.vat_contacts set name=trim(h.name),vat_number=nullif(trim(h.vat_number),''),
  email=nullif(trim(h.email),''),phone=nullif(trim(h.phone),''),street=nullif(trim(h.street),''),
  building_number=nullif(trim(h.building_number),''),district=nullif(trim(h.district),''),
  additional_number=nullif(trim(h.additional_number),''),city=nullif(trim(h.city),''),
  postal_code=nullif(trim(h.postal_code),''),country_code=h.country_code,updated_at=clock_timestamp()
 where id=c.id returning * into h;
 -- Keep the existing financial party identity; update its master name/contact only.
 update public.liquidity_counterparties cp set name=h.name,email=coalesce(h.email,''),phone=coalesce(h.phone,'')
 from public.financial_vat_counterparty_map m where m.vat_contact_id=c.id and m.organization_id=c.organization_id
  and cp.id=m.counterparty_id and cp.organization_id=c.organization_id;
 insert into public.audit_logs(user_id,entity_type,entity_id,action,old_data,new_data)
 values(auth.uid(),'vat_contact',c.id,'UPDATE',to_jsonb(c),to_jsonb(h));
 return to_jsonb(h);
end $fn$
;
revoke all on function public.amend_vat_contact_master(uuid,jsonb,timestamptz) from public,anon
;
grant execute on function public.amend_vat_contact_master(uuid,jsonb,timestamptz) to authenticated
;

\echo MIGRATION 20261008111020 vat_note_financial_workflow
-- Notes are separate recognition adjustments; cash refunds remain separate settlements.
create or replace function public.prepare_vat_note_financial_event(p_document_id uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare d public.vat_documents%rowtype; original public.vat_documents%rowtype;
 root public.financial_events%rowtype; ob public.financial_event_obligations%rowtype;
 eid uuid; cls uuid; taxcls uuid; existing uuid; payload jsonb; obligations jsonb;
begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED'; end if;
 select * into d from public.vat_documents where id=p_document_id for update;
 if d.id is null then raise exception 'VAT_SOURCE_NOT_FOUND'; end if;
 if not public.is_organization_admin(d.organization_id) or not public.financial_core_can(d.organization_id,'financial_core.create') then raise exception 'VAT_FINANCIAL_PREPARE_DENIED'; end if;
 if d.document_kind not in ('CREDIT_NOTE','DEBIT_NOTE') or d.preceding_document_id is null or nullif(trim(d.notes),'') is null then raise exception 'VAT_NOTE_REFERENCE_AND_REASON_REQUIRED'; end if;
 select * into original from public.vat_documents where id=d.preceding_document_id and organization_id=d.organization_id for update;
 if original.id is null or original.document_kind<>'INVOICE' or original.document_type<>d.document_type or original.counterparty_contact_id is distinct from d.counterparty_contact_id
  or original.currency<>d.currency or coalesce(original.source_currency,original.currency)<>coalesce(d.source_currency,d.currency) or original.exchange_rate<>d.exchange_rate then raise exception 'VAT_NOTE_ORIGINAL_IDENTITY_OR_CURRENCY_MISMATCH'; end if;
 if d.transaction_date<original.transaction_date then raise exception 'VAT_NOTE_DATE_BEFORE_ORIGINAL'; end if;
 select e.* into root from public.financial_event_links l join public.financial_events e on e.id=l.event_id and e.organization_id=l.organization_id
 where l.organization_id=d.organization_id and l.link_type='SOURCE' and l.target_module='vat_documents' and l.target_record_id=original.id;
 if root.id is null or root.status in ('CANCELLED','REVERSED') then raise exception 'VAT_ORIGINAL_FINANCIAL_EVENT_REQUIRED'; end if;
 select event_id into existing from public.financial_vat_source_bindings where organization_id=d.organization_id and source_table='vat_documents' and source_record_id=d.id;
 if existing is not null then return existing; end if;
 select * into ob from public.financial_event_obligations where organization_id=d.organization_id and event_id=root.id and adjusts_obligation_id is null and obligation_type=case when d.document_type='SALES' then 'RECEIVABLE' else 'PAYABLE' end for update;
 if ob.id is null then raise exception 'VAT_ORIGINAL_OBLIGATION_REQUIRED'; end if;
 select l.classification_id into cls from public.financial_event_lines l join public.financial_classifications c on c.id=l.classification_id
 where l.event_id=root.id and c.classification_type<>'TAX' order by l.line_number limit 1;
 select l.classification_id into taxcls from public.financial_event_lines l join public.financial_classifications c on c.id=l.classification_id
 where l.event_id=root.id and c.classification_type='TAX' order by l.line_number limit 1;
 if taxcls is null then select id into taxcls from public.financial_classifications where organization_id=d.organization_id and classification_type='TAX' and active order by is_system desc limit 1; end if;
 if cls is null or (d.tax_amount>0 and taxcls is null) then raise exception 'VAT_FINANCIAL_CLASSIFICATIONS_REQUIRED'; end if;
 obligations:=case when d.document_kind='CREDIT_NOTE' then jsonb_build_array(jsonb_build_object('obligation_key','note-adjustment','obligation_type',ob.obligation_type,'adjusts_obligation_id',ob.id,'adjustment_effect','DECREASE','settleable_amount',d.gross_amount,'currency',d.currency,'exchange_rate',1,'base_currency',d.currency,'settleable_base_amount',d.gross_amount))
 else jsonb_build_array(jsonb_build_object('obligation_key','note-gross','obligation_type',ob.obligation_type,'settleable_amount',d.gross_amount,'currency',d.currency,'exchange_rate',1,'base_currency',d.currency,'settleable_base_amount',d.gross_amount)) end;
 payload:=jsonb_build_object('organization_id',d.organization_id,'entity_id',root.entity_id,'counterparty_id',root.counterparty_id,'event_type','ADJUSTMENT','source_module','VAT_INTEGRATION','source_record_id',d.id,'source_event_key','vat_documents:'||d.id,'event_date',d.transaction_date,'due_date',coalesce(d.due_date,d.transaction_date),'base_currency',d.currency,'description',d.document_kind||' '||d.document_number||' / '||original.document_number,
 'lines',jsonb_build_array(jsonb_build_object('line_number',1,'classification_id',cls,'amount',d.net_amount,'currency',d.currency,'exchange_rate',1,'base_amount',d.net_amount,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0,'metadata',jsonb_build_object('source_role','NET_RECOGNITION','recognition_sign',case when d.document_kind='CREDIT_NOTE' then -1 else 1 end))) ||
 case when d.tax_amount>0 then jsonb_build_array(jsonb_build_object('line_number',2,'classification_id',taxcls,'amount',d.tax_amount,'currency',d.currency,'exchange_rate',1,'base_amount',d.tax_amount,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0,'metadata',jsonb_build_object('source_role',case when d.document_type='SALES' then 'OUTPUT_VAT' else 'INPUT_VAT' end,'recognition_sign',case when d.document_kind='CREDIT_NOTE' then -1 else 1 end,'recoverable_percent',d.recoverable_percent))) else '[]'::jsonb end,
 'obligations',obligations,'links',jsonb_build_array(jsonb_build_object('link_type','SOURCE','target_module','vat_documents','target_record_id',d.id),jsonb_build_object('link_type','CORRECTS','related_event_id',root.id,'metadata',jsonb_build_object('original_document_id',original.id,'reason',d.notes))));
 eid:=private.phase2c_create_financial_event_internal(payload);
 perform public.transition_financial_event(eid,'PLANNED','VAT note prepared');
 perform public.transition_financial_event(eid,'COMMITTED','VAT note pending financial approval');
 insert into public.financial_vat_source_bindings(organization_id,source_table,source_record_id,event_id,canonical_payload,payload_fingerprint,document_kind,side,contact_id,entity_id,due_date,original_event_id,is_alias,created_by)
 values(d.organization_id,'vat_documents',d.id,eid,private.canonical_financial_json(to_jsonb(d)),encode(extensions.digest(convert_to(d.id::text||'|'||eid::text,'UTF8'),'sha256'),'hex'),d.document_kind,d.document_type,d.counterparty_contact_id,root.entity_id,coalesce(d.due_date,d.transaction_date),root.id,false,auth.uid());
 return eid;
end $$
;
revoke all on function public.prepare_vat_note_financial_event(uuid) from public,anon
;
grant execute on function public.prepare_vat_note_financial_event(uuid) to authenticated
;
-- Only zero-value, fully closed invoice projections may remain after a credit note.
alter table public.liquidity_flows drop constraint if exists liquidity_flows_amount_check
;
alter table public.liquidity_flows add constraint liquidity_flows_amount_check check(amount>0 or (amount=0 and source_module='VAT_INTEGRATION' and settlement_status='SETTLED'))
;
alter table public.liquidity_flows drop constraint if exists liquidity_flows_base_amount_check
;
alter table public.liquidity_flows add constraint liquidity_flows_base_amount_check check(base_amount>0 or (base_amount=0 and source_module='VAT_INTEGRATION' and settlement_status='SETTLED'))
;
-- Production's recovered balance view lacked obligation adjustments. Preserve the
-- richer QA view where already present; add the same adjustment/advance model only where absent.
do $upgrade$ begin
 if position('adjustment_effect' in pg_get_viewdef('public.financial_event_obligation_balances'::regclass))=0 then
 execute $view$ create or replace view public.financial_event_obligation_balances with(security_invoker=true) as
 with roots as(select o.*,coalesce((select sum(case a.adjustment_effect when 'DECREASE' then -a.settleable_base_amount else a.settleable_base_amount end) from public.financial_event_obligations a join public.financial_events e on e.id=a.event_id and e.organization_id=a.organization_id where a.adjusts_obligation_id=o.id and a.organization_id=o.organization_id and e.status='ACTUAL'),0) adjustment from public.financial_event_obligations o join public.financial_events e on e.id=o.event_id and e.organization_id=o.organization_id where e.status='ACTUAL' and o.adjusts_obligation_id is null),
 sums as(select a.organization_id,a.obligation_id,sum(a.base_amount) amount from public.financial_event_obligation_allocations a join public.financial_events e on e.id=a.application_event_id and e.organization_id=a.organization_id where e.status='ACTUAL' group by a.organization_id,a.obligation_id),
 advances as(select a.organization_id,a.source_advance_obligation_id id,sum(a.base_amount) amount from public.financial_event_obligation_allocations a join public.financial_events e on e.id=a.application_event_id and e.organization_id=a.organization_id where e.status='ACTUAL' and a.source_advance_obligation_id is not null group by a.organization_id,a.source_advance_obligation_id)
 select r.id obligation_id,r.organization_id,r.event_id,r.obligation_key,r.obligation_type,r.settleable_amount,r.currency,r.exchange_rate,r.base_currency,(r.settleable_base_amount+r.adjustment)::numeric(24,4) adjusted_settleable_base_amount,coalesce(s.amount,0)::numeric(24,4) applied_base_amount,coalesce(a.amount,0)::numeric(24,4) consumed_advance_base_amount,greatest(r.settleable_base_amount+r.adjustment-case when r.obligation_type in('RECEIVABLE','PAYABLE') then coalesce(s.amount,0) else coalesce(a.amount,0) end,0)::numeric(24,4) outstanding_base_amount from roots r left join sums s on s.organization_id=r.organization_id and s.obligation_id=r.id left join advances a on a.organization_id=r.organization_id and a.id=r.id $view$;
 end if;
end $upgrade$
;
create or replace function private.apply_vat_note_effects()
returns trigger language plpgsql security definer set search_path='' as $$
declare d public.vat_documents%rowtype; original public.vat_documents%rowtype; root uuid; ob public.financial_event_obligations%rowtype; remaining numeric; previous_due numeric; credit_total numeric; refund numeric; f public.liquidity_flows%rowtype; amount_due numeric; direction text;
begin
 if old.status='ACTUAL' and new.status='REVERSED' and exists(select 1 from public.financial_vat_source_bindings where event_id=new.id and document_kind in('CREDIT_NOTE','DEBIT_NOTE')) then raise exception 'VAT_NOTE_REVERSAL_REQUIRES_LINKED_CORRECTION'; end if;
 if new.status<>'ACTUAL' or old.status='ACTUAL' then return new; end if;
 select * into d from public.vat_documents where id=new.source_record_id and organization_id=new.organization_id and document_kind in('CREDIT_NOTE','DEBIT_NOTE');
 if d.id is null or not exists(select 1 from public.financial_vat_source_bindings where event_id=new.id and source_record_id=d.id) then return new; end if;
 if d.document_type='SALES' and d.zatca_status not in('ISSUED','CLEARED','REPORTED','SUBMITTED') then raise exception 'VAT_NOTE_MUST_BE_ISSUED'; end if;
 select * into original from public.vat_documents where id=d.preceding_document_id and organization_id=d.organization_id for update;
 select event_id into root from public.financial_vat_source_bindings where source_table='vat_documents' and source_record_id=original.id and organization_id=d.organization_id;
 if root is null then select event_id into root from public.financial_event_links where target_module='vat_documents' and target_record_id=original.id and link_type='SOURCE' and organization_id=d.organization_id; end if;
 perform 1 from public.financial_events where id=root and organization_id=d.organization_id and status='ACTUAL' for update;
 if not found then raise exception 'VAT_ORIGINAL_RECOGNITION_REQUIRED'; end if;
 select * into ob from public.financial_event_obligations where event_id=root and organization_id=d.organization_id and adjusts_obligation_id is null and obligation_type in('RECEIVABLE','PAYABLE') for update;
 if d.document_kind='CREDIT_NOTE' then
  select coalesce(sum(a.settleable_base_amount),0) into credit_total from public.financial_event_obligations a join public.financial_events ae on ae.id=a.event_id and ae.organization_id=a.organization_id where a.adjusts_obligation_id=ob.id and a.adjustment_effect='DECREASE' and ae.status='ACTUAL';
  if credit_total>original.gross_amount or exists(select 1 from public.vat_documents n join public.financial_vat_source_bindings b on b.source_record_id=n.id and b.organization_id=n.organization_id join public.financial_events e on e.id=b.event_id where n.preceding_document_id=original.id and e.status='ACTUAL' and n.document_kind='CREDIT_NOTE' group by n.preceding_document_id having sum(n.net_amount)>original.net_amount or sum(n.tax_amount)>original.tax_amount) then raise exception 'VAT_CREDIT_EXCEEDS_ORIGINAL'; end if;
  select outstanding_base_amount,adjusted_settleable_base_amount into remaining,amount_due from public.financial_event_obligation_balances where obligation_id=ob.id;
  select coalesce(sum(a.base_amount),0) into previous_due from public.financial_event_obligation_allocations a join public.financial_events e on e.id=a.application_event_id and e.organization_id=a.organization_id where a.obligation_id=ob.id and e.status='ACTUAL';
  refund:=greatest(previous_due-amount_due,0);
  -- Only the incremental excess for this note is refunded.
  refund:=least(d.gross_amount,greatest(0,refund-coalesce((select sum(o.settleable_base_amount) from public.financial_event_obligations o join public.financial_events e on e.id=o.event_id and e.organization_id=o.organization_id join public.vat_documents n on n.id=e.source_record_id where n.preceding_document_id=original.id and o.obligation_key='note-refund' and e.status='ACTUAL' and e.id<>new.id),0)));
  select * into f from public.liquidity_flows where organization_id=d.organization_id and source_module='VAT_INTEGRATION' and source_record_id=original.id for update;
  if f.id is not null then update public.liquidity_flows set amount=settled_amount+coalesce(remaining,0),base_amount=settled_amount+coalesce(remaining,0),settlement_status=case when coalesce(remaining,0)=0 then 'SETTLED' when settled_amount>0 then 'PARTIAL' else 'UNSETTLED' end,updated_at=now() where id=f.id; end if;
  if refund>0 then
   insert into public.financial_event_obligations(organization_id,event_id,obligation_key,obligation_type,settleable_amount,currency,exchange_rate,base_currency,settleable_base_amount,created_by)
   values(d.organization_id,new.id,'note-refund',case when d.document_type='SALES' then 'PAYABLE' else 'RECEIVABLE' end,refund,d.currency,1,d.currency,refund,auth.uid());
  end if;
  amount_due:=refund; direction:=case when d.document_type='SALES' then 'OUTFLOW' else 'INFLOW' end;
 else amount_due:=d.gross_amount; direction:=case when d.document_type='SALES' then 'INFLOW' else 'OUTFLOW' end;
 end if;
 if amount_due>0 then
  insert into public.liquidity_flows(organization_id,direction,flow_type,title,counterparty,counterparty_id,due_date,amount,currency,base_amount,status,source,reference,notes,source_module,source_record_id,source_event_key)
  values(d.organization_id,direction,'OPERATING',d.document_kind||' · '||d.document_number,d.counterparty_name,new.counterparty_id,coalesce(d.due_date,d.transaction_date),amount_due,d.currency,amount_due,'EXPECTED','INVOICE',d.document_number,'Note recognition only; bank changes require a separate approved settlement.','VAT_INTEGRATION',d.id,'vat_documents:'||d.id||':cash-forecast') returning * into f;
  insert into public.financial_event_links(organization_id,event_id,link_type,target_module,target_record_id,metadata,created_by) values(d.organization_id,new.id,'CASH_FLOW','liquidity_flows',f.id,jsonb_build_object('purpose','VAT_NOTE_SETTLEMENT'),auth.uid());
 end if;
 insert into public.audit_logs(user_id,entity_type,entity_id,action,new_data) values(auth.uid(),'vat_document',d.id,'NOTE_EFFECT_POSTED',jsonb_build_object('original_id',original.id,'kind',d.document_kind,'gross',d.gross_amount,'refund_due',case when d.document_kind='CREDIT_NOTE' then amount_due else 0 end,'bank_effect','NONE'));
 return new;
end $$
;
revoke all on function private.apply_vat_note_effects() from public,anon,authenticated
;
create trigger apply_vat_note_effects after update of status on public.financial_events for each row execute function private.apply_vat_note_effects()
;
create or replace function public.create_vat_note_document(p_values jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare d public.vat_documents%rowtype; eid uuid;
begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED'; end if;
 d:=jsonb_populate_record(null::public.vat_documents,p_values);
 if d.document_kind not in('CREDIT_NOTE','DEBIT_NOTE') or not public.is_organization_admin(d.organization_id) then raise exception 'INVALID_VAT_NOTE'; end if;
 insert into public.vat_documents(organization_id,user_id,created_by,document_type,document_kind,document_number,transaction_date,due_date,counterparty_contact_id,counterparty_name,counterparty_tax_number,supply_type,net_amount,tax_rate,tax_amount,recoverable_percent,gross_amount,line_items,currency,source_currency,exchange_rate,source_net_amount,source_tax_amount,source_gross_amount,notes,preceding_document_id,zatca_status)
 values(d.organization_id,auth.uid(),auth.uid(),d.document_type,d.document_kind,d.document_number,d.transaction_date,d.due_date,d.counterparty_contact_id,d.counterparty_name,d.counterparty_tax_number,d.supply_type,d.net_amount,d.tax_rate,d.tax_amount,d.recoverable_percent,d.gross_amount,d.line_items,d.currency,d.source_currency,d.exchange_rate,d.source_net_amount,d.source_tax_amount,d.source_gross_amount,d.notes,d.preceding_document_id,case when d.document_type='SALES' then 'DRAFT' else 'NOT_ISSUED' end) returning * into d;
 if d.net_amount<=0 or d.gross_amount<=0 then raise exception 'VAT_NOTE_AMOUNT_INVALID'; end if;
 eid:=public.prepare_vat_note_financial_event(d.id);
 return to_jsonb(d)||jsonb_build_object('financial_core',jsonb_build_object('event_id',eid,'status','COMMITTED','recognition','PENDING_APPROVAL'));
end $$
;
revoke all on function public.create_vat_note_document(jsonb) from public,anon
;
grant execute on function public.create_vat_note_document(jsonb) to authenticated
;
create or replace function public.issue_vat_einvoice(p_invoice_id uuid)
returns public.vat_einvoices language plpgsql security definer set search_path='' as $$
declare i public.vat_einvoices%rowtype; original public.vat_einvoices%rowtype; d public.vat_documents%rowtype;
 payload bytea:=''::bytea; fields text[]; bytes bytea; n int; credit_net numeric; credit_tax numeric; credit_gross numeric;
begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED'; end if;
 select * into i from public.vat_einvoices where id=p_invoice_id for update;
 if i.id is null then raise exception 'EINVOICE_NOT_FOUND'; end if;
 if not public.has_organization_permission(i.organization_id,'vat.issue') then raise exception 'VAT_ISSUE_FORBIDDEN'; end if;
 if i.status<>'DRAFT' then raise exception 'EINVOICE_NOT_DRAFT'; end if;
 if i.document_type<>'INVOICE' then
  select * into original from public.vat_einvoices where id=i.preceding_invoice_id and organization_id=i.organization_id for update;
  if original.id is null or original.document_type<>'INVOICE' or original.status not in('ISSUED','CLEARED','REPORTED','SUBMITTED') then raise exception 'PRECEDING_INVOICE_NOT_ISSUED'; end if;
  if original.invoice_category<>i.invoice_category or original.buyer_contact_id is distinct from i.buyer_contact_id or original.currency<>i.currency or original.exchange_rate<>i.exchange_rate then raise exception 'VAT_NOTE_ORIGINAL_IDENTITY_OR_CURRENCY_MISMATCH'; end if;
  if nullif(trim(i.note_reason),'') is null or i.billing_reference is distinct from original.invoice_number or i.issue_date<original.issue_date then raise exception 'VAT_NOTE_REFERENCE_AND_REASON_REQUIRED'; end if;
  select * into d from public.vat_documents where id=i.accounting_document_id and organization_id=i.organization_id for update;
  if d.id is null or d.document_kind<>i.document_type or d.preceding_document_id is distinct from original.accounting_document_id or not exists(select 1 from public.financial_vat_source_bindings where organization_id=i.organization_id and source_record_id=d.id and document_kind=i.document_type) then raise exception 'VAT_NOTE_FINANCIAL_SOURCE_REQUIRED'; end if;
  if i.document_type='CREDIT_NOTE' then
   select coalesce(sum(tax_exclusive_amount),0)+i.tax_exclusive_amount,coalesce(sum(tax_total_amount),0)+i.tax_total_amount,coalesce(sum(payable_amount),0)+i.payable_amount into credit_net,credit_tax,credit_gross from public.vat_einvoices where organization_id=i.organization_id and preceding_invoice_id=original.id and document_type='CREDIT_NOTE' and status in('ISSUED','CLEARED','REPORTED','SUBMITTED');
   if credit_net>original.tax_exclusive_amount or credit_tax>original.tax_total_amount or credit_gross>original.payable_amount then raise exception 'VAT_CREDIT_EXCEEDS_ORIGINAL'; end if;
  end if;
 end if;
 fields:=array[i.seller_name,i.seller_vat_number,to_char(i.issue_date,'YYYY-MM-DD')||'T'||to_char(i.issue_time,'HH24:MI:SS')||'+03:00',to_char(i.tax_inclusive_amount,'FM99999999999999999990.00'),to_char(i.tax_total_amount,'FM99999999999999999990.00')];
 for n in 1..array_length(fields,1) loop bytes:=convert_to(fields[n],'UTF8'); if octet_length(bytes)>255 then raise exception 'QR_FIELD_TOO_LONG'; end if; payload:=payload||decode(lpad(to_hex(n),2,'0'),'hex')||decode(lpad(to_hex(octet_length(bytes)),2,'0'),'hex')||bytes; end loop;
 if length(translate(encode(payload,'base64'),E'\n\r',''))>700 then raise exception 'QR_PAYLOAD_TOO_LONG'; end if;
 update public.vat_einvoices set status='ISSUED',qr_code=translate(encode(payload,'base64'),E'\n\r',''),issued_at=now(),updated_at=now() where id=i.id returning * into i;
 update public.vat_documents set zatca_status='ISSUED' where id=i.accounting_document_id and organization_id=i.organization_id;
 return i;
end $$
;
revoke all on function public.issue_vat_einvoice(uuid) from public,anon
;
grant execute on function public.issue_vat_einvoice(uuid) to authenticated
;
-- Preserve the existing reporting view and teach recovered Production to read signed note lines.
do $signed$ declare definition text; begin
 definition:=pg_get_viewdef('public.financial_budget_operational_facts'::regclass,true);
 if position('1 AS sign' in definition)>0 then
  definition:=replace(definition,'1 AS sign', 'CASE WHEN l.metadata->>''recognition_sign''=''-1'' THEN -1 ELSE 1 END AS sign');
  definition:=replace(definition,'l.base_amount AS budget_base_amount','(l.base_amount * CASE WHEN l.metadata->>''recognition_sign''=''-1'' THEN -1 ELSE 1 END)::numeric(24,4) AS budget_base_amount');
  definition:=replace(definition,'THEN l.base_amount','THEN l.base_amount * CASE WHEN l.metadata->>''recognition_sign''=''-1'' THEN -1 ELSE 1 END');
  execute 'create or replace view public.financial_budget_operational_facts with(security_invoker=true) as '||definition;
 end if;
end $signed$
;

\echo MIGRATION 20261008111022 vat_note_workflow_guards
-- Keep bound source financial evidence immutable while allowing an issued note's
-- lifecycle status to mirror its linked electronic invoice.
do $guards$ declare definition text; begin
 if to_regprocedure('private.phase2c_source_immutable()') is not null then
  definition:=pg_get_functiondef('private.phase2c_source_immutable()'::regprocedure);
  definition:=replace(definition,'if bound then', $branch$if bound and tg_table_name='vat_documents' and tg_op='UPDATE' then
   if (to_jsonb(new)-array['zatca_status']) is not distinct from (to_jsonb(old)-array['zatca_status'])
    and new.zatca_status in('ISSUED','CLEARED','REPORTED','SUBMITTED')
    and exists(select 1 from public.vat_einvoices i where i.accounting_document_id=new.id and i.organization_id=new.organization_id and i.status=new.zatca_status) then return new; end if;
  end if;
  if bound then$branch$);
  execute definition;
 end if;
 if to_regprocedure('private.phase2c_evidence_immutable()') is not null then
  definition:=pg_get_functiondef('private.phase2c_evidence_immutable()'::regprocedure);
  definition:=replace(definition,'eid:=case when', $branch$if tg_table_name='financial_event_obligations' and tg_op='INSERT' and pg_trigger_depth()>1 then
   if new.obligation_key='note-refund' and new.adjusts_obligation_id is null
    and exists(select 1 from public.financial_vat_source_bindings b join public.financial_events e on e.id=b.event_id and e.organization_id=b.organization_id join public.vat_documents d on d.id=b.source_record_id and d.organization_id=b.organization_id
     where e.id=new.event_id and e.organization_id=new.organization_id and e.status='ACTUAL' and e.source_module='VAT_INTEGRATION' and b.document_kind='CREDIT_NOTE'
     and new.obligation_type=case when d.document_type='SALES' then 'PAYABLE' else 'RECEIVABLE' end) then return new; end if;
  end if;
  eid:=case when$branch$);
  execute definition;
 end if;
end $guards$
;
-- Validate monetary identity at the RPC boundary and prevent edits to submitted periods.
create or replace function private.validate_vat_note_document()
returns trigger language plpgsql security definer set search_path='' as $$
declare original public.vat_documents%rowtype;
begin
 if new.document_kind not in('CREDIT_NOTE','DEBIT_NOTE') then return new; end if;
 if new.net_amount<=0 or new.tax_amount<0 or new.gross_amount<>new.net_amount+new.tax_amount
  or new.source_gross_amount<>new.source_net_amount+new.source_tax_amount
  or new.net_amount<>round(new.source_net_amount*new.exchange_rate,2)
  or new.tax_amount<>round(new.source_tax_amount*new.exchange_rate,2)
  or new.source_net_amount is null or new.source_tax_amount is null or new.exchange_rate<=0 then raise exception 'VAT_NOTE_AMOUNT_INVALID'; end if;
 select * into original from public.vat_documents where id=new.preceding_document_id and organization_id=new.organization_id;
 if original.id is null then raise exception 'VAT_NOTE_REFERENCE_AND_REASON_REQUIRED'; end if;
 if new.document_type='PURCHASE' and new.recoverable_percent is distinct from original.recoverable_percent then raise exception 'VAT_NOTE_RECOVERY_MUST_MATCH_ORIGINAL'; end if;
 if exists(select 1 from public.vat_period_summaries where organization_id=new.organization_id and filing_status='FILED' and new.transaction_date between period_start and period_end) then raise exception 'VAT_NOTE_FILED_PERIOD_LOCKED'; end if;
 return new;
end $$
;
revoke all on function private.validate_vat_note_document() from public,anon,authenticated
;
create trigger validate_vat_note_document before insert on public.vat_documents for each row execute function private.validate_vat_note_document()
;

\echo MIGRATION 20261008111024 vat_note_source_fingerprint
-- Notes are separate recognition adjustments; cash refunds remain separate settlements.
create or replace function public.prepare_vat_note_financial_event(p_document_id uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare d public.vat_documents%rowtype; original public.vat_documents%rowtype;
 root public.financial_events%rowtype; ob public.financial_event_obligations%rowtype;
 eid uuid; cls uuid; taxcls uuid; existing uuid; payload jsonb; obligations jsonb; canonical jsonb;
begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED'; end if;
 select * into d from public.vat_documents where id=p_document_id for update;
 if d.id is null then raise exception 'VAT_SOURCE_NOT_FOUND'; end if;
 if not public.is_organization_admin(d.organization_id) or not public.financial_core_can(d.organization_id,'financial_core.create') then raise exception 'VAT_FINANCIAL_PREPARE_DENIED'; end if;
 if d.document_kind not in ('CREDIT_NOTE','DEBIT_NOTE') or d.preceding_document_id is null or nullif(trim(d.notes),'') is null then raise exception 'VAT_NOTE_REFERENCE_AND_REASON_REQUIRED'; end if;
 select * into original from public.vat_documents where id=d.preceding_document_id and organization_id=d.organization_id for update;
 if original.id is null or original.document_kind<>'INVOICE' or original.document_type<>d.document_type or original.counterparty_contact_id is distinct from d.counterparty_contact_id
  or original.currency<>d.currency or coalesce(original.source_currency,original.currency)<>coalesce(d.source_currency,d.currency) or original.exchange_rate<>d.exchange_rate then raise exception 'VAT_NOTE_ORIGINAL_IDENTITY_OR_CURRENCY_MISMATCH'; end if;
 if d.transaction_date<original.transaction_date then raise exception 'VAT_NOTE_DATE_BEFORE_ORIGINAL'; end if;
 select e.* into root from public.financial_event_links l join public.financial_events e on e.id=l.event_id and e.organization_id=l.organization_id
 where l.organization_id=d.organization_id and l.link_type='SOURCE' and l.target_module='vat_documents' and l.target_record_id=original.id;
 if root.id is null or root.status in ('CANCELLED','REVERSED') then raise exception 'VAT_ORIGINAL_FINANCIAL_EVENT_REQUIRED'; end if;
 select event_id into existing from public.financial_vat_source_bindings where organization_id=d.organization_id and source_table='vat_documents' and source_record_id=d.id;
 if existing is not null then return existing; end if;
 select * into ob from public.financial_event_obligations where organization_id=d.organization_id and event_id=root.id and adjusts_obligation_id is null and obligation_type=case when d.document_type='SALES' then 'RECEIVABLE' else 'PAYABLE' end for update;
 if ob.id is null then raise exception 'VAT_ORIGINAL_OBLIGATION_REQUIRED'; end if;
 select l.classification_id into cls from public.financial_event_lines l join public.financial_classifications c on c.id=l.classification_id
 where l.event_id=root.id and c.classification_type<>'TAX' order by l.line_number limit 1;
 select l.classification_id into taxcls from public.financial_event_lines l join public.financial_classifications c on c.id=l.classification_id
 where l.event_id=root.id and c.classification_type='TAX' order by l.line_number limit 1;
 if taxcls is null then select id into taxcls from public.financial_classifications where organization_id=d.organization_id and classification_type='TAX' and active order by is_system desc limit 1; end if;
 if cls is null or (d.tax_amount>0 and taxcls is null) then raise exception 'VAT_FINANCIAL_CLASSIFICATIONS_REQUIRED'; end if;
 obligations:=case when d.document_kind='CREDIT_NOTE' then jsonb_build_array(jsonb_build_object('obligation_key','note-adjustment','obligation_type',ob.obligation_type,'adjusts_obligation_id',ob.id,'adjustment_effect','DECREASE','settleable_amount',d.gross_amount,'currency',d.currency,'exchange_rate',1,'base_currency',d.currency,'settleable_base_amount',d.gross_amount))
 else jsonb_build_array(jsonb_build_object('obligation_key','note-gross','obligation_type',ob.obligation_type,'settleable_amount',d.gross_amount,'currency',d.currency,'exchange_rate',1,'base_currency',d.currency,'settleable_base_amount',d.gross_amount)) end;
 payload:=jsonb_build_object('organization_id',d.organization_id,'entity_id',root.entity_id,'counterparty_id',root.counterparty_id,'event_type','ADJUSTMENT','source_module','VAT_INTEGRATION','source_record_id',d.id,'source_event_key','vat_documents:'||d.id,'event_date',d.transaction_date,'due_date',coalesce(d.due_date,d.transaction_date),'base_currency',d.currency,'description',d.document_kind||' '||d.document_number||' / '||original.document_number,
 'lines',jsonb_build_array(jsonb_build_object('line_number',1,'classification_id',cls,'amount',d.net_amount,'currency',d.currency,'exchange_rate',1,'base_amount',d.net_amount,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0,'metadata',jsonb_build_object('source_role','NET_RECOGNITION','recognition_sign',case when d.document_kind='CREDIT_NOTE' then -1 else 1 end))) ||
 case when d.tax_amount>0 then jsonb_build_array(jsonb_build_object('line_number',2,'classification_id',taxcls,'amount',d.tax_amount,'currency',d.currency,'exchange_rate',1,'base_amount',d.tax_amount,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0,'metadata',jsonb_build_object('source_role',case when d.document_type='SALES' then 'OUTPUT_VAT' else 'INPUT_VAT' end,'recognition_sign',case when d.document_kind='CREDIT_NOTE' then -1 else 1 end,'recoverable_percent',d.recoverable_percent))) else '[]'::jsonb end,
 'obligations',obligations,'links',jsonb_build_array(jsonb_build_object('link_type','SOURCE','target_module','vat_documents','target_record_id',d.id),jsonb_build_object('link_type','CORRECTS','related_event_id',root.id,'metadata',jsonb_build_object('original_document_id',original.id,'reason',d.notes))));
 eid:=private.phase2c_create_financial_event_internal(payload);
 perform public.transition_financial_event(eid,'PLANNED','VAT note prepared');
 perform public.transition_financial_event(eid,'COMMITTED','VAT note pending financial approval');
 canonical:=private.canonical_financial_json(jsonb_build_object('adapter','LINKED_NOTE_V1','document',to_jsonb(d)-'zatca_status'));
 insert into public.financial_vat_source_bindings(organization_id,source_table,source_record_id,event_id,canonical_payload,payload_fingerprint,document_kind,side,contact_id,entity_id,due_date,original_event_id,is_alias,created_by)
 values(d.organization_id,'vat_documents',d.id,eid,canonical,encode(extensions.digest(convert_to(canonical::text,'UTF8'),'sha256'),'hex'),d.document_kind,d.document_type,d.counterparty_contact_id,root.entity_id,coalesce(d.due_date,d.transaction_date),root.id,false,auth.uid());
 return eid;
end $$
;
revoke all on function public.prepare_vat_note_financial_event(uuid) from public,anon
;
grant execute on function public.prepare_vat_note_financial_event(uuid) to authenticated
;
create or replace function private.apply_vat_note_effects()
returns trigger language plpgsql security definer set search_path='' as $$
declare d public.vat_documents%rowtype; original public.vat_documents%rowtype; root uuid; ob public.financial_event_obligations%rowtype; remaining numeric; previous_due numeric; credit_total numeric; refund numeric; f public.liquidity_flows%rowtype; amount_due numeric; direction text;
begin
 if old.status='ACTUAL' and new.status='REVERSED' and exists(select 1 from public.financial_vat_source_bindings where event_id=new.id and document_kind in('CREDIT_NOTE','DEBIT_NOTE')) then raise exception 'VAT_NOTE_REVERSAL_REQUIRES_LINKED_CORRECTION'; end if;
 if new.status<>'ACTUAL' or old.status='ACTUAL' then return new; end if;
 select * into d from public.vat_documents where id=new.source_record_id and organization_id=new.organization_id and document_kind in('CREDIT_NOTE','DEBIT_NOTE');
 if d.id is null or not exists(select 1 from public.financial_vat_source_bindings where event_id=new.id and source_record_id=d.id) then return new; end if;
 if not exists(select 1 from public.financial_vat_source_bindings b where b.event_id=new.id and b.payload_fingerprint=encode(extensions.digest(convert_to(private.canonical_financial_json(jsonb_build_object('adapter','LINKED_NOTE_V1','document',to_jsonb(d)-'zatca_status'))::text,'UTF8'),'sha256'),'hex')) then raise exception 'VAT_NOTE_FINANCIAL_SOURCE_CHANGED'; end if;
 if d.document_type='SALES' and d.zatca_status not in('ISSUED','CLEARED','REPORTED','SUBMITTED') then raise exception 'VAT_NOTE_MUST_BE_ISSUED'; end if;
 select * into original from public.vat_documents where id=d.preceding_document_id and organization_id=d.organization_id for update;
 select event_id into root from public.financial_vat_source_bindings where source_table='vat_documents' and source_record_id=original.id and organization_id=d.organization_id;
 if root is null then select event_id into root from public.financial_event_links where target_module='vat_documents' and target_record_id=original.id and link_type='SOURCE' and organization_id=d.organization_id; end if;
 perform 1 from public.financial_events where id=root and organization_id=d.organization_id and status='ACTUAL' for update;
 if not found then raise exception 'VAT_ORIGINAL_RECOGNITION_REQUIRED'; end if;
 select * into ob from public.financial_event_obligations where event_id=root and organization_id=d.organization_id and adjusts_obligation_id is null and obligation_type in('RECEIVABLE','PAYABLE') for update;
 if d.document_kind='CREDIT_NOTE' then
  select coalesce(sum(a.settleable_base_amount),0) into credit_total from public.financial_event_obligations a join public.financial_events ae on ae.id=a.event_id and ae.organization_id=a.organization_id where a.adjusts_obligation_id=ob.id and a.adjustment_effect='DECREASE' and ae.status='ACTUAL';
  if credit_total>original.gross_amount or exists(select 1 from public.vat_documents n join public.financial_vat_source_bindings b on b.source_record_id=n.id and b.organization_id=n.organization_id join public.financial_events e on e.id=b.event_id where n.preceding_document_id=original.id and e.status='ACTUAL' and n.document_kind='CREDIT_NOTE' group by n.preceding_document_id having sum(n.net_amount)>original.net_amount or sum(n.tax_amount)>original.tax_amount) then raise exception 'VAT_CREDIT_EXCEEDS_ORIGINAL'; end if;
  select outstanding_base_amount,adjusted_settleable_base_amount into remaining,amount_due from public.financial_event_obligation_balances where obligation_id=ob.id;
  select coalesce(sum(a.base_amount),0) into previous_due from public.financial_event_obligation_allocations a join public.financial_events e on e.id=a.application_event_id and e.organization_id=a.organization_id where a.obligation_id=ob.id and e.status='ACTUAL';
  refund:=greatest(previous_due-amount_due,0);
  -- Only the incremental excess for this note is refunded.
  refund:=least(d.gross_amount,greatest(0,refund-coalesce((select sum(o.settleable_base_amount) from public.financial_event_obligations o join public.financial_events e on e.id=o.event_id and e.organization_id=o.organization_id join public.vat_documents n on n.id=e.source_record_id where n.preceding_document_id=original.id and o.obligation_key='note-refund' and e.status='ACTUAL' and e.id<>new.id),0)));
  select * into f from public.liquidity_flows where organization_id=d.organization_id and source_module='VAT_INTEGRATION' and source_record_id=original.id for update;
  if f.id is not null then update public.liquidity_flows set amount=settled_amount+coalesce(remaining,0),base_amount=settled_amount+coalesce(remaining,0),settlement_status=case when coalesce(remaining,0)=0 then 'SETTLED' when settled_amount>0 then 'PARTIAL' else 'UNSETTLED' end,updated_at=now() where id=f.id; end if;
  if refund>0 then
   insert into public.financial_event_obligations(organization_id,event_id,obligation_key,obligation_type,settleable_amount,currency,exchange_rate,base_currency,settleable_base_amount,created_by)
   values(d.organization_id,new.id,'note-refund',case when d.document_type='SALES' then 'PAYABLE' else 'RECEIVABLE' end,refund,d.currency,1,d.currency,refund,auth.uid());
  end if;
  amount_due:=refund; direction:=case when d.document_type='SALES' then 'OUTFLOW' else 'INFLOW' end;
 else amount_due:=d.gross_amount; direction:=case when d.document_type='SALES' then 'INFLOW' else 'OUTFLOW' end;
 end if;
 if amount_due>0 then
  insert into public.liquidity_flows(organization_id,direction,flow_type,title,counterparty,counterparty_id,due_date,amount,currency,base_amount,status,source,reference,notes,source_module,source_record_id,source_event_key)
  values(d.organization_id,direction,'OPERATING',d.document_kind||' · '||d.document_number,d.counterparty_name,new.counterparty_id,coalesce(d.due_date,d.transaction_date),amount_due,d.currency,amount_due,'EXPECTED','INVOICE',d.document_number,'Note recognition only; bank changes require a separate approved settlement.','VAT_INTEGRATION',d.id,'vat_documents:'||d.id||':cash-forecast') returning * into f;
  insert into public.financial_event_links(organization_id,event_id,link_type,target_module,target_record_id,metadata,created_by) values(d.organization_id,new.id,'CASH_FLOW','liquidity_flows',f.id,jsonb_build_object('purpose','VAT_NOTE_SETTLEMENT'),auth.uid());
 end if;
 insert into public.audit_logs(user_id,entity_type,entity_id,action,new_data) values(auth.uid(),'vat_document',d.id,'NOTE_EFFECT_POSTED',jsonb_build_object('original_id',original.id,'kind',d.document_kind,'gross',d.gross_amount,'refund_due',case when d.document_kind='CREDIT_NOTE' then amount_due else 0 end,'bank_effect','NONE'));
 return new;
end $$
;
revoke all on function private.apply_vat_note_effects() from public,anon,authenticated
;
-- QA's legacy VAT adapter validates its own fingerprint shape. Notes use the
-- dedicated signed-line adapter, whose AFTER trigger verifies its own fingerprint.
do $guard$ declare definition text; begin
 if to_regprocedure('private.phase2c_post_guard()') is not null then
  definition:=pg_get_functiondef('private.phase2c_post_guard()'::regprocedure);
  definition:=replace(definition,'for b in select *', $branch$if b.canonical_payload->>'adapter'='LINKED_NOTE_V1' then
   if exists(select 1 from public.financial_event_lines l where l.event_id=new.id and l.cash_direction<>'NON_CASH') then raise exception 'VAT_RECOGNITION_CANNOT_MOVE_CASH'; end if;
   return new;
  end if;
  for b in select *$branch$);
  execute definition;
 end if;
end $guard$
;

\echo MIGRATION 20261008111027 vat_note_forecast_integrity
-- Validate adjusted invoice forecasts against live obligations, not original gross.
create or replace function private.vat_note_forecast_valid(p_flow public.liquidity_flows)
returns boolean language plpgsql security definer set search_path='' as $$
declare d public.vat_documents%rowtype; eid uuid; outstanding numeric; expected_direction text;
begin
 select * into d from public.vat_documents where id=p_flow.source_record_id and organization_id=p_flow.organization_id;
 if d.id is null or p_flow.source_module<>'VAT_INTEGRATION' or p_flow.source_event_key is distinct from 'vat_documents:'||d.id||':cash-forecast' or p_flow.currency<>d.currency or p_flow.base_amount<>p_flow.amount or p_flow.settled_amount<0 or p_flow.settled_amount>p_flow.amount then return false; end if;
 select event_id into eid from public.financial_event_links where organization_id=d.organization_id and link_type='SOURCE' and target_module='vat_documents' and target_record_id=d.id;
 if eid is null then return false; end if;
 select coalesce(sum(b.outstanding_base_amount),0) into outstanding from public.financial_event_obligation_balances b where b.event_id=eid and b.organization_id=d.organization_id and b.obligation_type in('RECEIVABLE','PAYABLE');
 if d.document_kind='CREDIT_NOTE' then expected_direction:=case when d.document_type='SALES' then 'OUTFLOW' else 'INFLOW' end;
 else expected_direction:=case when d.document_type='SALES' then 'INFLOW' else 'OUTFLOW' end; end if;
 return p_flow.direction=expected_direction and p_flow.amount=p_flow.settled_amount+outstanding
  and exists(select 1 from public.financial_events e where e.id=eid and e.organization_id=d.organization_id and e.status='ACTUAL' and e.counterparty_id is not distinct from p_flow.counterparty_id);
end $$
;
revoke all on function private.vat_note_forecast_valid(public.liquidity_flows) from public,anon,authenticated
;
do $guard$ declare definition text; begin
 if to_regprocedure('private.phase2c_expected_integrity()') is not null then
  definition:=pg_get_functiondef('private.phase2c_expected_integrity()'::regprocedure);
  definition:=replace(definition,E'begin\n', $branch$begin
  if tg_op<>'DELETE' and new.source_module='VAT_INTEGRATION' and (
   exists(select 1 from public.financial_vat_source_bindings b where b.organization_id=new.organization_id and b.source_record_id=new.source_record_id and b.canonical_payload->>'adapter'='LINKED_NOTE_V1')
   or exists(select 1 from public.vat_documents n join public.financial_vat_source_bindings b on b.source_record_id=n.id and b.organization_id=n.organization_id join public.financial_events e on e.id=b.event_id where n.preceding_document_id=new.source_record_id and n.organization_id=new.organization_id and e.status='ACTUAL' and b.canonical_payload->>'adapter'='LINKED_NOTE_V1')) then
   if not private.vat_note_forecast_valid(new) then raise exception 'VAT_NOTE_FORECAST_PARITY_REQUIRED'; end if;
   return new;
  end if;
$branch$);
  execute definition;
 end if;
end $guard$
;

