CREATE OR REPLACE FUNCTION private.accounting_invoice_binding_state(p_org uuid,p_document uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='pg_catalog','public' AS $$
DECLARE linked boolean; recognized boolean;BEGIN
 IF auth.uid() IS NULL OR NOT (public.has_organization_permission(p_org,'vat.edit') OR public.has_organization_permission(p_org,'financial_core.view')) THEN RAISE EXCEPTION 'INVOICE_BINDING_SCOPE_DENIED';END IF;
 SELECT count(*)>0,coalesce(bool_or(e.status IN('ACTUAL','REVERSED')),false) INTO linked,recognized FROM public.financial_events e WHERE e.organization_id=p_org AND (EXISTS(SELECT 1 FROM public.financial_event_links l WHERE l.event_id=e.id AND l.organization_id=p_org AND l.target_module='vat_documents' AND l.target_record_id=p_document AND l.link_type='SOURCE') OR EXISTS(SELECT 1 FROM public.financial_vat_source_bindings b WHERE b.event_id=e.id AND b.organization_id=p_org AND b.source_table='vat_documents' AND b.source_record_id=p_document));
 RETURN jsonb_build_object('bound',linked,'posted',recognized);
END $$
;
REVOKE ALL ON FUNCTION private.accounting_invoice_binding_state(uuid,uuid) FROM PUBLIC,anon
;
GRANT EXECUTE ON FUNCTION private.accounting_invoice_binding_state(uuid,uuid) TO authenticated
;
CREATE OR REPLACE FUNCTION private.guard_accounting_invoice_source() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='pg_catalog','public' AS $$
DECLARE bound boolean; posted boolean;
BEGIN
 IF OLD.document_kind<>'INVOICE' THEN IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END IF;
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)-'zatca_status'-'notes') IS NOT DISTINCT FROM (to_jsonb(OLD)-'zatca_status'-'notes') THEN RETURN NEW;END IF;
 SELECT (x->>'bound')::boolean,(x->>'posted')::boolean INTO bound,posted FROM (SELECT private.accounting_invoice_binding_state(OLD.organization_id,OLD.id) x) q;
 IF bound AND (posted OR current_user NOT IN('postgres','supabase_admin')) THEN RAISE EXCEPTION 'VAT_BOUND_INVOICE_REQUIRES_CORRECTION';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $$
;
CREATE TRIGGER guard_accounting_invoice_source BEFORE UPDATE OR DELETE ON public.vat_documents FOR EACH ROW EXECUTE FUNCTION private.guard_accounting_invoice_source()
;
REVOKE ALL ON FUNCTION private.guard_accounting_invoice_source() FROM PUBLIC,anon,authenticated
;
COMMIT
;

\echo MIGRATION 20261012201707 financial_budget_cash_metrics_and_authenticated_api_access
BEGIN
;
CREATE OR REPLACE FUNCTION public.financial_budget_report(p_plan uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$declare o public.financial_budget_plan_ownership%rowtype;p public.budget_plans%rowtype;result jsonb;unmapped jsonb;begin select * into o from public.financial_budget_plan_ownership where plan_id=p_plan;if not found or not public.financial_budget_can(o.organization_id,o.entity_id,o.cost_center_id) then raise exception 'BUDGET_PLAN_READ_DENIED';end if;select * into p from public.budget_plans where id=p_plan;with facts as(select * from private.phase2d_plan_facts(p_plan)),gross as(select f.*,coalesce(g.paid,0)*abs(l.base_amount)/nullif(w.weight,0)*case when l.metadata->>'recognition_sign'='-1' then -1 else 1 end paid_share,coalesce(g.due,0)*abs(l.base_amount)/nullif(w.weight,0)*case when l.metadata->>'recognition_sign'='-1' then -1 else 1 end due_share from facts f join public.financial_event_lines l on l.id=f.financial_line_id left join lateral(select sum(abs(v.raw_base_amount)) weight from public.financial_budget_operational_facts v where v.event_id=f.event_id) w on true left join lateral(select sum(case when b.obligation_type in('RECEIVABLE','PAYABLE') then b.applied_base_amount else b.consumed_advance_base_amount end) paid,sum(b.outstanding_base_amount) due from public.financial_event_obligation_balances b where b.event_id=f.event_id and b.organization_id=f.organization_id) g on true),monthly as(select bl.id budget_line_id,bl.name,bl.category,bl.line_type,m.month fiscal_month,coalesce(bl.monthly_budget[m.month],0) budget_amount,coalesce(bl.monthly_actual[m.month],0) legacy_actual,coalesce(bl.monthly_forecast[m.month],0) forecast_amount,coalesce((select sum(f.actual_amount) from facts f where f.budget_line_id=bl.id and f.fiscal_month=m.month),0) actual_amount,coalesce((select sum(f.committed_amount) from facts f where f.budget_line_id=bl.id and f.fiscal_month=m.month),0) committed_amount,coalesce((select sum(g.paid_share) from gross g where g.budget_line_id=bl.id and g.fiscal_month=m.month),0) paid_settled_gross,coalesce((select sum(g.due_share) from gross g where g.budget_line_id=bl.id and g.fiscal_month=m.month),0) outstanding_gross from public.budget_lines bl cross join generate_series(1,12)m(month) where bl.plan_id=p_plan and bl.user_id=p.user_id and bl.active),metrics as(select *,budget_amount-committed_amount-actual_amount remaining_budget,case when line_type='REVENUE' then actual_amount-budget_amount else budget_amount-actual_amount end favorable_variance,forecast_amount-actual_amount forecast_minus_actual,actual_amount-legacy_actual reconciliation_difference from monthly)select coalesce(jsonb_agg(to_jsonb(metrics)||jsonb_build_object('variance_percent',100*favorable_variance/nullif(abs(budget_amount),0),'actual_source','FINANCIAL_CORE_DERIVED','legacy_source','LEGACY_MANUAL_MONTHLY_ACTUAL') order by budget_line_id,fiscal_month),'[]') into result from metrics;select coalesce(jsonb_agg(to_jsonb(f)),'[]') into unmapped from private.phase2d_plan_facts(p_plan)f where f.reason is not null;return jsonb_build_object('plan_id',p_plan,'organization_id',o.organization_id,'entity_id',o.entity_id,'cost_center_id',o.cost_center_id,'currency',p.currency,'scenario',p.scenario,'fiscal_start',o.fiscal_start,'rows',result,'unmapped_financial_actuals',unmapped,'unmapped_amount',(select coalesce(sum(f.unmapped_amount),0)from private.phase2d_plan_facts(p_plan)f where f.reason is not null),'unmapped_alert',jsonb_array_length(unmapped)>0,'legacy_actual_not_replaced',true,'forecast_not_changed',true);end$function$
;
-- These authenticated financial APIs are never needed by anonymous callers.
DO $access$ DECLARE f record;BEGIN
 FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('amend_unissued_sales_invoice','amend_unsettled_purchase_invoice','approve_financial_event','can_self_approve_financial_event','configure_financial_budget','create_financial_event_command','effective_organization_permission','financial_budget_can','financial_budget_consolidated','financial_budget_drilldown','financial_budget_report','financial_core_can','link_zatca_accounting_document','owner_set_member_permission_override','owner_set_organization_approval_policy','owner_update_organization_role','post_financial_settlement','post_vat_financial_event','prepare_vat_financial_event','seed_default_organization_roles','transition_financial_event') LOOP
  EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC, anon',f.signature);
  EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',f.signature);
 END LOOP;
END $access$
;
COMMIT
;

\echo MIGRATION 20261012201708 asset_purchase_draft_workspace
BEGIN
;
CREATE OR REPLACE FUNCTION public.guard_asset_acquisition_edit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare k text;
begin
 if current_user='postgres' and auth.uid() is not null and old.ownership_scope='ORGANIZATION' and new.organization_id=old.organization_id and public.has_organization_permission(old.organization_id,'assets.edit') and exists(select 1 from public.transactions t join public.financial_events e on e.id=nullif(t.metadata->>'financial_event_id','')::uuid and e.organization_id=t.organization_id where t.asset_account_id=old.id and t.transaction_type='PURCHASE' and e.source_module='ASSETS_INTEGRATION' and e.status in('DRAFT','PLANNED','COMMITTED') and not exists(select 1 from public.financial_event_approvals p where p.event_id=e.id and p.decision='APPROVED')) then return new;end if;
 if exists(select 1 from public.transactions where asset_account_id=old.id)
    or exists(select 1 from public.lots where asset_account_id=old.id) then
  if row(new.user_id,new.asset_type,new.currency,new.unit,new.ownership_scope,new.organization_id,new.entity_id,new.cost_center_id,new.asset_class_code,new.asset_type_code)
    is distinct from row(old.user_id,old.asset_type,old.currency,old.unit,old.ownership_scope,old.organization_id,old.entity_id,old.cost_center_id,old.asset_class_code,old.asset_type_code) then
   raise exception 'ASSET_FINANCIAL_FIELDS_LOCKED';
  end if;
  foreach k in array array['quantity','purchase_value','opening_value','purchase_price','karat','purity','fx_rate','vat_amount','vat_rate','recoverable_percent'] loop
   if coalesce(nullif(new.metadata->>k,'')::numeric,0) is distinct from coalesce(nullif(old.metadata->>k,'')::numeric,0) then
    raise exception 'ASSET_FINANCIAL_FIELDS_LOCKED';
   end if;
  end loop;
  foreach k in array array['vat_input_mode','purchase_date','acquisition_mode','funding_account_id','acquisition_base_currency','counterparty_id','invoice_reference','due_date'] loop
   if new.metadata->>k is distinct from old.metadata->>k then raise exception 'ASSET_FINANCIAL_FIELDS_LOCKED';end if;
  end loop;
 end if;
 return new;
end $function$
;
CREATE OR REPLACE FUNCTION private.amend_asset_purchase_draft(p_asset_id uuid,p_changes jsonb,p_expected_updated_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='pg_catalog','public','private','extensions' AS $$
DECLARE a public.asset_accounts%rowtype;t public.transactions%rowtype;e public.financial_events%rowtype;m jsonb;net numeric;vat numeric;rate numeric;recover numeric;qty numeric;fx numeric;cost numeric;dt date;due date;party uuid;ref text;cid uuid;taxid uuid;payload jsonb;norm jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED';END IF;
 SELECT * INTO a FROM public.asset_accounts WHERE id=p_asset_id;
 SELECT * INTO t FROM public.transactions WHERE asset_account_id=a.id AND transaction_type='PURCHASE' ORDER BY created_at LIMIT 1;
 SELECT * INTO e FROM public.financial_events WHERE id=nullif(t.metadata->>'financial_event_id','')::uuid AND organization_id=a.organization_id FOR UPDATE;
 SELECT * INTO a FROM public.asset_accounts WHERE id=p_asset_id FOR UPDATE;
 SELECT * INTO t FROM public.transactions WHERE id=t.id FOR UPDATE;
 IF a.id IS NULL OR a.ownership_scope<>'ORGANIZATION' OR e.id IS NULL OR e.source_module<>'ASSETS_INTEGRATION' OR e.source_record_id<>t.id THEN RAISE EXCEPTION 'ASSET_PURCHASE_DRAFT_REQUIRED';END IF;
 IF NOT public.has_organization_permission(a.organization_id,'assets.edit') OR NOT public.financial_core_can(a.organization_id,'financial_core.create') THEN RAISE EXCEPTION 'ASSET_PURCHASE_EDIT_DENIED';END IF;
 IF p_expected_updated_at IS NULL OR a.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'ASSET_EDIT_CONFLICT';END IF;
 IF e.status NOT IN('DRAFT','PLANNED','COMMITTED') OR EXISTS(SELECT 1 FROM public.financial_event_approvals WHERE event_id=e.id AND decision='APPROVED') OR EXISTS(SELECT 1 FROM public.financial_event_obligation_allocations x JOIN public.financial_event_obligations o ON o.id=x.obligation_id WHERE o.event_id=e.id) OR EXISTS(SELECT 1 FROM public.asset_lifecycle_commands WHERE asset_account_id=a.id) OR EXISTS(SELECT 1 FROM public.vat_documents WHERE asset_transaction_id=t.id) THEN RAISE EXCEPTION 'ASSET_FINANCIAL_FIELDS_LOCKED';END IF;
 IF (SELECT count(*) FROM public.transactions WHERE asset_account_id=a.id)<>1 OR EXISTS(SELECT 1 FROM public.transaction_allocations x JOIN public.lots l ON l.id=x.lot_id WHERE l.asset_account_id=a.id) THEN RAISE EXCEPTION 'ASSET_HAS_DOWNSTREAM_MOVEMENTS';END IF;
 IF jsonb_typeof(p_changes)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_changes) k WHERE k NOT IN('purchase_value','quantity','fx_rate','vat_input_mode','vat_rate','vat_amount','recoverable_percent','purchase_date','due_date','counterparty_id','invoice_reference')) THEN RAISE EXCEPTION 'ASSET_PURCHASE_CHANGE_FIELDS_INVALID';END IF;
 m:=a.metadata||p_changes;
 net:=(m->>'purchase_value')::numeric;qty:=(m->>'quantity')::numeric;fx:=(m->>'fx_rate')::numeric;recover:=(m->>'recoverable_percent')::numeric;dt:=(m->>'purchase_date')::date;due:=(m->>'due_date')::date;party:=(m->>'counterparty_id')::uuid;ref:=trim(m->>'invoice_reference');
 IF coalesce(m->>'vat_input_mode','') NOT IN('AMOUNT','PERCENT') THEN RAISE EXCEPTION 'ASSET_VAT_MODE_INVALID';END IF;
 IF m->>'vat_input_mode'='PERCENT' THEN rate:=(m->>'vat_rate')::numeric;IF rate<0 OR rate>100 THEN RAISE EXCEPTION 'ASSET_VAT_RATE_INVALID';END IF;vat:=round(net*rate/100,2);ELSE vat:=(m->>'vat_amount')::numeric;END IF;
 IF net::text IN('NaN','Infinity','-Infinity') OR qty::text IN('NaN','Infinity','-Infinity') OR fx::text IN('NaN','Infinity','-Infinity') OR vat::text IN('NaN','Infinity','-Infinity') OR recover::text IN('NaN','Infinity','-Infinity') OR net IS NULL OR net<=0 OR qty IS NULL OR qty<=0 OR fx IS NULL OR fx<=0 OR vat IS NULL OR vat<0 OR recover IS NULL OR recover<0 OR recover>100 OR dt IS NULL OR due IS NULL OR due<dt OR ref IS NULL OR ref='' THEN RAISE EXCEPTION 'ASSET_PURCHASE_VALUES_INVALID';END IF;
 IF a.currency=e.base_currency AND fx<>1 THEN RAISE EXCEPTION 'ASSET_PURCHASE_FX_INVALID';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.liquidity_counterparties WHERE id=party AND organization_id=a.organization_id AND party_type IN('SUPPLIER','BOTH') AND active) THEN RAISE EXCEPTION 'ASSET_SUPPLIER_SCOPE_MISMATCH';END IF;
 cost:=net+vat*(1-recover/100);
 SELECT l.classification_id INTO cid FROM public.financial_event_lines l JOIN public.financial_classifications c ON c.id=l.classification_id WHERE l.event_id=e.id AND c.classification_type<>'TAX' ORDER BY l.line_number LIMIT 1;
 SELECT id INTO taxid FROM public.financial_classifications WHERE organization_id=a.organization_id AND classification_type='TAX' AND active ORDER BY is_system DESC LIMIT 1;
 IF cid IS NULL OR (vat*recover>0 AND taxid IS NULL) THEN RAISE EXCEPTION 'ASSET_FINANCIAL_CLASSIFICATION_REQUIRED';END IF;
 IF (a.metadata->>'market_value')::numeric=(a.metadata->>'purchase_value')::numeric THEN m:=m||jsonb_build_object('market_value',net);END IF;
 IF (a.metadata->>'estimated_value')::numeric=(a.metadata->>'purchase_value')::numeric THEN m:=m||jsonb_build_object('estimated_value',net);END IF;
 m:=m||jsonb_build_object('vat_amount',vat,'acquisition_cost_base',cost*fx,'purchase_price',net/qty);
 UPDATE public.financial_events SET counterparty_id=party,event_date=dt,due_date=due,description='Asset purchase / '||a.name,updated_at=now() WHERE id=e.id;
 UPDATE public.financial_event_lines SET amount=cost,base_amount=cost*fx,exchange_rate=fx WHERE event_id=e.id AND classification_id=cid;
 IF vat*recover>0 THEN
  UPDATE public.financial_event_lines SET amount=vat*recover/100,base_amount=vat*recover/100*fx,exchange_rate=fx WHERE event_id=e.id AND classification_id=taxid;
  IF NOT FOUND THEN INSERT INTO public.financial_event_lines(event_id,organization_id,line_number,description,classification_id,cost_center_id,amount,currency,exchange_rate,base_amount,cash_direction,vat_treatment) VALUES(e.id,a.organization_id,2,'Recoverable VAT / '||a.name,taxid,a.cost_center_id,vat*recover/100,a.currency,fx,vat*recover/100*fx,'NON_CASH','OUT_OF_SCOPE');END IF;
 ELSE DELETE FROM public.financial_event_lines WHERE event_id=e.id AND classification_id=taxid;END IF;
 UPDATE public.financial_event_obligations SET settleable_amount=net+vat,settleable_base_amount=(net+vat)*fx,exchange_rate=fx WHERE event_id=e.id;
 UPDATE public.asset_accounts SET metadata=m,updated_at=now() WHERE id=a.id RETURNING * INTO a;
 UPDATE public.transactions SET quantity=qty,unit_price=net/qty,gross_value=net,base_value=net*fx,transaction_date=dt,reference=ref,metadata=metadata||m WHERE id=t.id;
 UPDATE public.lots SET original_quantity=qty,remaining_quantity=qty,original_value_base=cost*fx,remaining_value_base=cost*fx,acquisition_date=dt WHERE source_transaction_id=t.id;
 UPDATE public.liquidity_flows f SET amount=net+vat,base_amount=(net+vat)*fx,due_date=due,counterparty_id=party,counterparty=(SELECT name FROM public.liquidity_counterparties WHERE id=party),reference=ref,updated_at=now() FROM public.financial_event_links l WHERE l.event_id=e.id AND l.link_type='CASH_FLOW' AND l.target_module='liquidity_flows' AND l.target_record_id=f.id AND f.organization_id=a.organization_id AND f.settled_amount=0;
 SELECT canonical_payload INTO payload FROM public.financial_event_command_registry WHERE financial_event_id=e.id AND command_type='EVENT_CREATE';
 payload:=payload||jsonb_build_object('counterparty_id',party,'event_date',dt,'due_date',due);
 payload:=jsonb_set(payload,'{lines}',(SELECT jsonb_agg(to_jsonb(l)-'id'-'event_id'-'organization_id'-'created_at' ORDER BY l.line_number) FROM public.financial_event_lines l WHERE l.event_id=e.id));
 payload:=jsonb_set(payload,'{obligations}',(SELECT jsonb_agg(to_jsonb(o)-'id'-'event_id'-'organization_id'-'created_by'-'created_at') FROM public.financial_event_obligations o WHERE o.event_id=e.id));
 norm:=private.canonical_financial_json(payload);
 UPDATE public.financial_event_command_registry SET canonical_payload=norm,payload_fingerprint=encode(extensions.digest(convert_to(norm::text,'UTF8'),'sha256'),'hex') WHERE financial_event_id=e.id AND command_type='EVENT_CREATE';
 UPDATE public.transactions SET metadata=metadata||jsonb_build_object('financial_core_intent',payload) WHERE id=t.id;
 INSERT INTO public.audit_logs(user_id,entity_type,entity_id,action,new_data) VALUES(auth.uid(),'asset_account',a.id,'AMEND_PURCHASE_DRAFT',jsonb_build_object('event_id',e.id,'net',net,'vat',vat,'gross',net+vat));
 RETURN to_jsonb(a);
END $$
;
REVOKE ALL ON FUNCTION private.amend_asset_purchase_draft(uuid,jsonb,timestamptz) FROM PUBLIC,anon
;
GRANT EXECUTE ON FUNCTION private.amend_asset_purchase_draft(uuid,jsonb,timestamptz) TO authenticated
;
CREATE OR REPLACE FUNCTION public.amend_asset_purchase_draft(p_asset_id uuid,p_changes jsonb,p_expected_updated_at timestamptz) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT private.amend_asset_purchase_draft(p_asset_id,p_changes,p_expected_updated_at); $$
;
REVOKE ALL ON FUNCTION public.amend_asset_purchase_draft(uuid,jsonb,timestamptz) FROM PUBLIC,anon
;
GRANT EXECUTE ON FUNCTION public.amend_asset_purchase_draft(uuid,jsonb,timestamptz) TO authenticated
;
CREATE OR REPLACE FUNCTION private.archive_asset_purchase_draft(p_asset_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='pg_catalog','public' AS $$
DECLARE a public.asset_accounts%rowtype; eid uuid; e public.financial_events%rowtype;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED';END IF;
 SELECT * INTO a FROM public.asset_accounts WHERE id=p_asset_id;
 SELECT nullif(t.metadata->>'financial_event_id','')::uuid INTO eid FROM public.transactions t WHERE t.asset_account_id=a.id AND t.transaction_type='PURCHASE' ORDER BY t.created_at LIMIT 1;
 SELECT * INTO e FROM public.financial_events WHERE id=eid AND organization_id=a.organization_id FOR UPDATE;
 SELECT * INTO a FROM public.asset_accounts WHERE id=p_asset_id FOR UPDATE;
 IF a.id IS NULL OR e.id IS NULL OR a.ownership_scope<>'ORGANIZATION' OR e.source_module<>'ASSETS_INTEGRATION' OR NOT public.has_organization_permission(a.organization_id,'assets.edit') OR NOT public.financial_core_can(a.organization_id,'financial_core.create') THEN RAISE EXCEPTION 'ASSET_PURCHASE_DELETE_DENIED';END IF;
 IF e.status NOT IN('DRAFT','PLANNED','COMMITTED','CANCELLED') OR EXISTS(SELECT 1 FROM public.financial_event_approvals WHERE event_id=e.id AND decision='APPROVED') OR EXISTS(SELECT 1 FROM public.vat_documents WHERE asset_transaction_id=e.source_record_id) OR EXISTS(SELECT 1 FROM public.asset_lifecycle_commands WHERE asset_account_id=a.id) THEN RAISE EXCEPTION 'ASSET_PROTECTED';END IF;
 IF e.status<>'CANCELLED' THEN PERFORM public.transition_financial_event(e.id,'CANCELLED','Archive unposted asset purchase');END IF;
 UPDATE public.asset_accounts SET metadata=metadata||jsonb_build_object('archived',true,'archived_by',auth.uid(),'archived_at',now()),updated_at=now() WHERE id=a.id;
 INSERT INTO public.audit_logs(user_id,entity_type,entity_id,action,new_data) VALUES(auth.uid(),'asset_account',a.id,'ARCHIVE_PURCHASE_DRAFT',jsonb_build_object('event_id',e.id));
 RETURN jsonb_build_object('id',a.id,'archived',true,'financial_event_status','CANCELLED');
END $$
;
REVOKE ALL ON FUNCTION private.archive_asset_purchase_draft(uuid) FROM PUBLIC,anon
;
GRANT EXECUTE ON FUNCTION private.archive_asset_purchase_draft(uuid) TO authenticated
;
CREATE OR REPLACE FUNCTION public.archive_asset_purchase_draft(p_asset_id uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT private.archive_asset_purchase_draft(p_asset_id); $$
;
REVOKE ALL ON FUNCTION public.archive_asset_purchase_draft(uuid) FROM PUBLIC,anon
;
GRANT EXECUTE ON FUNCTION public.archive_asset_purchase_draft(uuid) TO authenticated
;
COMMIT
;

\echo MIGRATION 20261013050416 asset_operation_edit_and_reverse_workspace
BEGIN
;
-- Financial edit commands reuse the existing lifecycle engine and preserve the old draft.
CREATE OR REPLACE FUNCTION private.replace_asset_lifecycle_draft(p_event_id uuid,p_payload jsonb,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.financial_events%rowtype;c public.asset_lifecycle_commands%rowtype;r public.asset_lifecycle_commands%rowtype;result jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED';END IF;
 SELECT * INTO e FROM public.financial_events WHERE id=p_event_id;
 SELECT * INTO c FROM public.asset_lifecycle_commands WHERE id=e.source_record_id AND financial_event_id=e.id AND organization_id=e.organization_id;
 IF c.id IS NULL OR e.source_module<>'ASSET_LIFECYCLE' THEN RAISE EXCEPTION 'ASSET_LIFECYCLE_EVENT_REQUIRED';END IF;
 IF NOT public.has_organization_permission(e.organization_id,'assets.edit') OR NOT public.financial_core_can(e.organization_id,'financial_core.create') THEN RAISE EXCEPTION 'ASSET_DRAFT_EDIT_DENIED';END IF;
 IF jsonb_typeof(p_payload)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN('operation','date','quantity','amount','vat_amount','counterparty_id','due_date')) OR coalesce(p_payload->>'quantity','0') IN('NaN','Infinity','-Infinity') OR coalesce(p_payload->>'amount','0') IN('NaN','Infinity','-Infinity') OR coalesce(p_payload->>'vat_amount','0') IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'ASSET_OPERATION_INVALID';END IF;
 PERFORM id FROM public.financial_events WHERE id=e.id FOR UPDATE;
 SELECT * INTO r FROM public.asset_lifecycle_commands WHERE created_by=auth.uid() AND request_id=p_request_id;
 IF r.id IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.financial_event_links WHERE event_id=r.financial_event_id AND organization_id=e.organization_id AND related_event_id=e.id AND link_type='CORRECTS') THEN RAISE EXCEPTION 'ASSET_REQUEST_CONFLICT';END IF;
  RETURN public.prepare_asset_lifecycle(c.asset_account_id,p_payload,p_request_id);
 END IF;
 IF e.status NOT IN('DRAFT','PLANNED','COMMITTED') OR EXISTS(SELECT 1 FROM public.financial_event_approvals WHERE event_id=e.id AND decision='APPROVED') THEN RAISE EXCEPTION 'ASSET_APPROVED_DRAFT_LOCKED';END IF;
 PERFORM public.transition_financial_event(e.id,'CANCELLED','Replace asset operation draft');
 result:=public.prepare_asset_lifecycle(c.asset_account_id,p_payload,p_request_id);
 INSERT INTO public.financial_event_links(organization_id,event_id,link_type,related_event_id,metadata) VALUES(e.organization_id,(result->>'financial_event_id')::uuid,'CORRECTS',e.id,jsonb_build_object('reason','DRAFT_AMENDMENT','created_by',auth.uid()));
 INSERT INTO public.audit_logs(user_id,entity_type,entity_id,action,new_data) VALUES(auth.uid(),'financial_event',e.id,'REPLACE_ASSET_DRAFT',jsonb_build_object('replacement_event_id',result->>'financial_event_id'));
 RETURN result;
END $$
;
REVOKE ALL ON FUNCTION private.replace_asset_lifecycle_draft(uuid,jsonb,uuid) FROM PUBLIC,anon
;
GRANT EXECUTE ON FUNCTION private.replace_asset_lifecycle_draft(uuid,jsonb,uuid) TO authenticated
;
CREATE OR REPLACE FUNCTION public.replace_asset_lifecycle_draft(p_event_id uuid,p_payload jsonb,p_request_id uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT private.replace_asset_lifecycle_draft(p_event_id,p_payload,p_request_id); $$
;
REVOKE ALL ON FUNCTION public.replace_asset_lifecycle_draft(uuid,jsonb,uuid) FROM PUBLIC,anon
;
GRANT EXECUTE ON FUNCTION public.replace_asset_lifecycle_draft(uuid,jsonb,uuid) TO authenticated
;
CREATE OR REPLACE FUNCTION private.asset_financial_reverse_block_reason(p_event_id uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.financial_events%rowtype;asset uuid;tx uuid;c public.asset_lifecycle_commands%rowtype;amt numeric;
BEGIN
 IF auth.uid() IS NULL THEN RETURN 'UNAUTHORIZED';END IF;
 SELECT * INTO e FROM public.financial_events WHERE id=p_event_id;
 IF e.id IS NULL OR e.source_module NOT IN('ASSETS_INTEGRATION','ASSET_LIFECYCLE') THEN RETURN 'ASSET_EVENT_NOT_FOUND';END IF;
 SELECT coalesce(sum(abs(base_amount)),0) INTO amt FROM public.financial_event_lines WHERE event_id=e.id AND organization_id=e.organization_id;
 IF NOT public.has_organization_permission(e.organization_id,'assets.edit') OR NOT public.effective_organization_permission(e.organization_id,'financial_core.reverse',amt,e.base_currency) THEN RETURN 'ASSET_REVERSE_DENIED';END IF;
 IF e.status<>'ACTUAL' THEN RETURN 'ASSET_REVERSE_REQUIRES_POSTED';END IF;
 IF e.source_module='ASSETS_INTEGRATION' THEN SELECT asset_account_id,id INTO asset,tx FROM public.transactions WHERE id=e.source_record_id AND organization_id=e.organization_id;
 ELSE SELECT * INTO c FROM public.asset_lifecycle_commands WHERE id=e.source_record_id AND financial_event_id=e.id AND organization_id=e.organization_id;asset:=c.asset_account_id;tx:=c.transaction_id;END IF;
 IF asset IS NULL OR NOT EXISTS(SELECT 1 FROM public.asset_accounts WHERE id=asset AND organization_id=e.organization_id) THEN RETURN 'ASSET_EVENT_SCOPE_MISMATCH';END IF;
 IF EXISTS(SELECT 1 FROM public.financial_event_obligation_balances WHERE event_id=e.id AND organization_id=e.organization_id AND applied_base_amount<>0) THEN RETURN 'ASSET_REVERSE_HAS_SETTLEMENTS';END IF;
 IF EXISTS(SELECT 1 FROM public.financial_vat_source_bindings WHERE event_id=e.id AND organization_id=e.organization_id) THEN RETURN 'ASSET_REVERSE_HAS_VAT_DOCUMENT';END IF;
 IF EXISTS(SELECT 1 FROM public.vat_documents WHERE asset_transaction_id=tx AND organization_id=e.organization_id) THEN RETURN 'ASSET_REVERSE_HAS_VAT_DOCUMENT';END IF;
 IF e.source_module='ASSET_LIFECYCLE' AND EXISTS(SELECT 1 FROM public.asset_lifecycle_commands WHERE asset_account_id=asset AND applied_at>c.applied_at) THEN RETURN 'ASSET_REVERSAL_HAS_LATER_OPERATIONS';END IF;
 IF e.source_module='ASSETS_INTEGRATION' AND EXISTS(SELECT 1 FROM public.lots WHERE source_transaction_id=tx AND (remaining_quantity<>original_quantity OR remaining_value_base<>original_value_base)) THEN RETURN 'ASSET_PURCHASE_REVERSAL_HAS_STOCK_MOVEMENTS';END IF;
 RETURN NULL;
END $$
;
