-- Party metadata is independent of monetary records. Existing personal identity
-- keys remain unchanged; aliases do not rewrite invoices or opening balances.
create table public.personal_debt_parties (
 id uuid primary key default gen_random_uuid(),
 user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
 party_key text not null,
 name text not null check(length(trim(name)) between 1 and 120),
 party_type text not null default 'BOTH' check(party_type in ('CUSTOMER','SUPPLIER','BOTH','PERSON','OTHER')),
 contact_name text not null default '', phone text not null default '',
 email text not null default '', notes text not null default '',
 active boolean not null default true,
 updated_at timestamptz not null default now(),
 unique(user_id,party_key)
)
;
alter table public.personal_debt_parties enable row level security
;
revoke all on public.personal_debt_parties from public,anon,authenticated
;
grant select on public.personal_debt_parties to authenticated
;
create policy personal_debt_parties_owner_read on public.personal_debt_parties
 for select to authenticated using(user_id=(select auth.uid()))
;
-- Deliberately private/definer: the guarded metadata command must see all
-- financial references, including records hidden by other module permissions.
create function private.manage_personal_debt_party(p jsonb) returns jsonb
language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare uid uuid:=auth.uid(); k text:=p->>'party_key'; r public.personal_debt_parties%rowtype;
 linked boolean; n text:=trim(p->>'name'); t text:=coalesce(p->>'party_type','BOTH');
begin
 if uid is null then raise exception 'UNAUTHORIZED';end if;
 perform pg_advisory_xact_lock(hashtextextended('personal-party:'||uid::text,0));
 if p->>'id' is not null then
  select * into r from public.personal_debt_parties where id=(p->>'id')::uuid and user_id=uid for update;
  if r.id is null then raise exception 'PARTY_ACCESS_DENIED';end if;k:=r.party_key;
 end if;
 if k is null then k:='directory:'||gen_random_uuid()::text;end if;
 linked:=exists(select 1 from public.asset_accounts where user_id=uid and organization_id is null and asset_type='RECEIVABLE' and id::text=k)
  or exists(select 1 from public.personal_payables where user_id=uid and 'personal-payable:'||lower(trim(party))=k)
  or exists(select 1 from public.personal_debt_links where user_id=uid and party_key=k);
 if r.id is null and p->>'party_key' is not null and not linked then raise exception 'PARTY_ACCESS_DENIED';end if;
 if p->>'action'='DELETE' then
  if r.id is null then raise exception 'PARTY_ACCESS_DENIED';end if;
  if linked then raise exception 'PARTY_IN_USE';end if;
  delete from public.personal_debt_parties where id=r.id and user_id=uid;return jsonb_build_object('deleted',true);
 end if;
 if p->>'action' is distinct from 'SAVE' or n is null or length(n) not between 1 and 120
  or t not in ('CUSTOMER','SUPPLIER','BOTH','PERSON','OTHER')
  or length(coalesce(p->>'contact_name',''))>120 or length(coalesce(p->>'phone',''))>40
  or length(coalesce(p->>'email',''))>160 or length(coalesce(p->>'notes',''))>500 then raise exception 'VALIDATION_FAILED';end if;
 insert into public.personal_debt_parties(user_id,party_key,name,party_type,contact_name,phone,email,notes,active)
 values(uid,k,n,t,coalesce(p->>'contact_name',''),coalesce(p->>'phone',''),coalesce(p->>'email',''),coalesce(p->>'notes',''),coalesce((p->>'active')::boolean,true))
 on conflict(user_id,party_key) do update set name=excluded.name,party_type=excluded.party_type,contact_name=excluded.contact_name,phone=excluded.phone,email=excluded.email,notes=excluded.notes,active=excluded.active,updated_at=now()
 returning * into r;
 return to_jsonb(r)-'user_id';
end $$
;
revoke all on function private.manage_personal_debt_party(jsonb) from public,anon
;
grant execute on function private.manage_personal_debt_party(jsonb) to authenticated
;
create function public.manage_personal_debt_party(p_payload jsonb) returns jsonb
language sql security invoker set search_path=pg_catalog,public,private as $$select private.manage_personal_debt_party(p_payload)$$
;
revoke all on function public.manage_personal_debt_party(jsonb) from public,anon
;
grant execute on function public.manage_personal_debt_party(jsonb) to authenticated
;
-- Atomically create the ordinary monetary command and link it to a directory
-- identity. Existing engines retain date, balance, reversal and replay checks.
create function private.directory_personal_debt_command(p jsonb) returns jsonb
language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare uid uuid:=auth.uid();cmd jsonb:=p->'command';op text:=p->>'operation';
 party public.personal_debt_parties%rowtype;side_name text;result jsonb;rid uuid;prior public.personal_debt_links%rowtype;fp text:=md5(p::text);
begin
 if uid is null then raise exception 'UNAUTHORIZED';end if;
 perform pg_advisory_xact_lock(hashtextextended('personal-party:'||uid::text,0));
 select * into party from public.personal_debt_parties where id=substring(cmd->>'source_debt_id' from 7)::uuid and user_id=uid for update;
 if party.id is null then raise exception 'PARTY_ACCESS_DENIED';end if;
 if not party.active then raise exception 'PARTY_ARCHIVED';end if;
 side_name:=case op when 'RECEIVABLE' then 'RECEIVABLE' when 'PAYABLE' then 'PAYABLE' when 'FUND' then cmd->>'side' end;
 if side_name is null or side_name not in ('RECEIVABLE','PAYABLE') then raise exception 'PERSONAL_DEBT_SOURCE_INVALID';end if;
 cmd:=cmd-'source_debt_id';
 if op='RECEIVABLE' and cmd->>'scope'='PERSONAL' and cmd->>'type'='RECEIVABLE' then
  cmd:=jsonb_set(cmd,'{name}',to_jsonb(party.name));
  if cmd->>'debt_category' is not null then result:=public.open_categorized_receivable(cmd);else result:=public.open_financial_account(cmd);end if;rid:=(result->>'id')::uuid;
 elsif op='PAYABLE' and cmd->>'action'='CREATE' then
  cmd:=jsonb_set(cmd,'{party}',to_jsonb(party.name));
  if cmd->>'category' is not null then result:=public.personal_payable_categorized_command(cmd);else result:=public.personal_payable_command(cmd);end if;rid:=(result->>'id')::uuid;
 elsif op='FUND' and cmd->>'action'='FUND' and cmd->>'kind'='LOAN' then
  cmd:=jsonb_set(cmd,'{party}',to_jsonb(party.name));result:=private.personal_financing_command(cmd);
  select case when side_name='RECEIVABLE' then receivable_id else payable_id end into rid from public.personal_financings where id=(result->>'id')::uuid and user_id=uid;
 else raise exception 'PERSONAL_DEBT_SOURCE_INVALID';end if;
 if rid is null then raise exception 'PERSONAL_DEBT_LINK_INVALID';end if;
 select * into prior from public.personal_debt_links where side=side_name and record_id=rid;
 if prior.id is not null then
  if prior.user_id<>uid or prior.fingerprint<>fp then raise exception 'PERSONAL_DEBT_LINK_REQUEST_CONFLICT';end if;
 else
  insert into public.personal_debt_links(user_id,record_id,side,party_key,party_name,source_debt_id,fingerprint)
  values(uid,rid,side_name,party.party_key,party.name,rid,fp);
 end if;
 return result;
end $$
;
revoke all on function private.directory_personal_debt_command(jsonb) from public,anon
;
grant execute on function private.directory_personal_debt_command(jsonb) to authenticated
;
create function public.directory_personal_debt_command(p_payload jsonb) returns jsonb
language sql security invoker set search_path=pg_catalog,public,private as $$select private.directory_personal_debt_command(p_payload)$$
;
revoke all on function public.directory_personal_debt_command(jsonb) from public,anon
;
grant execute on function public.directory_personal_debt_command(jsonb) to authenticated
;
-- A delete never clears links or silently strands the subledger. The added
-- constraints also serialize concurrent inserts against parent deletion.
alter table public.liquidity_flows add constraint liquidity_flows_party_directory_restrict_fk
 foreign key(counterparty_id,organization_id) references public.liquidity_counterparties(id,organization_id) on delete restrict not valid
;
alter table public.financial_events add constraint financial_events_party_directory_fk
 foreign key(counterparty_id,organization_id) references public.liquidity_counterparties(id,organization_id) on delete restrict not valid
;
alter table public.financial_vat_counterparty_map add constraint financial_vat_party_directory_fk
 foreign key(counterparty_id,organization_id) references public.liquidity_counterparties(id,organization_id) on delete restrict not valid
;
create function private.guard_counterparty_delete() returns trigger
language plpgsql security definer set search_path=pg_catalog,public as $$
begin
 if exists(select 1 from public.liquidity_flows where counterparty_id=old.id)
 or exists(select 1 from public.financial_events where counterparty_id=old.id)
 or exists(select 1 from public.debt_contracts where counterparty_id=old.id)
 or exists(select 1 from public.participation_contracts where counterparty_id=old.id)
 or exists(select 1 from public.financial_vat_counterparty_map where counterparty_id=old.id) then raise exception 'PARTY_IN_USE';end if;
 return old;
end $$
;
revoke all on function private.guard_counterparty_delete() from public,anon,authenticated
;
create trigger guard_counterparty_delete before delete on public.liquidity_counterparties
 for each row execute function private.guard_counterparty_delete()
;
create function private.guard_archived_debt_party() returns trigger
language plpgsql security definer set search_path=pg_catalog,public as $$
declare enabled boolean;
begin
 if tg_table_name='personal_debt_links' then
  select active into enabled from public.personal_debt_parties where user_id=new.user_id and party_key=new.party_key for share;
  if enabled=false then raise exception 'PARTY_ARCHIVED';end if;
 elsif new.counterparty_id is not null then
  if tg_op='UPDATE' and new.counterparty_id is not distinct from old.counterparty_id and new.organization_id is not distinct from old.organization_id then return new;end if;
  select active into enabled from public.liquidity_counterparties where id=new.counterparty_id and organization_id=new.organization_id for share;
  if enabled=false then raise exception 'PARTY_ARCHIVED';end if;
 end if;
 return new;
end $$
;
revoke all on function private.guard_archived_debt_party() from public,anon,authenticated
;
create trigger guard_archived_personal_party before insert on public.personal_debt_links for each row execute function private.guard_archived_debt_party()
;
create trigger guard_archived_party before insert or update of counterparty_id,organization_id on public.financial_events for each row execute function private.guard_archived_debt_party()
;
create trigger guard_archived_party before insert or update of counterparty_id,organization_id on public.debt_contracts for each row execute function private.guard_archived_debt_party()
;
create trigger guard_archived_party before insert or update of counterparty_id,organization_id on public.participation_contracts for each row execute function private.guard_archived_debt_party()
;
create trigger guard_archived_party before insert or update of counterparty_id,organization_id on public.liquidity_flows for each row execute function private.guard_archived_debt_party()
;

\echo MIGRATION 20261027090728 replay_unified_purchase_numbering
-- One immutable internal purchase number per company/source, shared by VAT aliases.
-- Supplier references and all recognition/settlement amounts remain unchanged.
lock table public.transactions, public.vat_documents in share row exclusive mode;

create table private.purchase_invoice_counters (
  organization_id uuid not null references public.organizations(id) on delete cascade,
  invoice_year integer not null,
  last_value bigint not null check (last_value > 0),
  primary key (organization_id, invoice_year)
);
create table private.purchase_invoice_numbers (
  organization_id uuid not null references public.organizations(id) on delete cascade,
  source_type text not null check (source_type in ('ASSET','VAT')),
  source_id uuid not null,
  invoice_year integer not null,
  sequence_value bigint not null,
  number text not null,
  created_at timestamptz not null default now(),
  primary key (organization_id, source_type, source_id),
  unique (organization_id, number),
  unique (organization_id, invoice_year, sequence_value)
);
-- Keep issued allocations after a draft/source is deleted: numbers are never recycled.
alter table private.purchase_invoice_counters enable row level security;
alter table private.purchase_invoice_numbers enable row level security;
revoke all on private.purchase_invoice_counters, private.purchase_invoice_numbers from public, anon, authenticated;
alter table public.transactions add column purchase_number text;
alter table public.vat_documents add column purchase_number text;

create function private.allocate_purchase_invoice_number(p_org uuid,p_source text,p_id uuid,p_date date)
returns text language plpgsql security definer set search_path=pg_catalog,public as $$
declare result text; yr integer := extract(year from p_date); seq bigint;
begin
  if p_org is null or p_id is null or p_date is null or p_source not in ('ASSET','VAT') then
    raise exception 'PURCHASE_NUMBER_SOURCE_REQUIRED';
  end if;
  -- Serialize identity lookup as well as counter increment (including first use).
  perform pg_advisory_xact_lock(hashtextextended(p_org::text, 81427));
  select number into result from private.purchase_invoice_numbers
    where organization_id=p_org and source_type=p_source and source_id=p_id;
  if found then return result; end if;
  insert into private.purchase_invoice_counters(organization_id,invoice_year,last_value)
    values(p_org,yr,1) on conflict(organization_id,invoice_year) do update
    set last_value=private.purchase_invoice_counters.last_value+1 returning last_value into seq;
  result := 'PUR-' || yr::text || '-' || lpad(seq::text,greatest(6,length(seq::text)),'0');
  insert into private.purchase_invoice_numbers(organization_id,source_type,source_id,invoice_year,sequence_value,number)
    values(p_org,p_source,p_id,yr,seq,result);
  return result;
end $$;
revoke all on function private.allocate_purchase_invoice_number(uuid,text,uuid,date) from public,anon,authenticated;

-- Assign historical numbers in deterministic chronological order, preserving supplier numbers.
-- A posted source normally rejects any new column change. Pause only that guard
-- while holding both write locks; restore it in this same migration transaction.
alter table public.vat_documents disable trigger guard_accounting_invoice_source;
do $$
declare r record; num text;
begin
  for r in
    select organization_id, 'ASSET'::text as source_type, id as source_id, transaction_date, created_at
      from public.transactions where organization_id is not null and transaction_type='PURCHASE' and reversal_of_transaction_id is null
    union all
    select organization_id, 'VAT', id, transaction_date, created_at from public.vat_documents
      where document_type='PURCHASE' and document_kind='INVOICE' and asset_transaction_id is null
    order by transaction_date,created_at,source_type,source_id
  loop
    num := private.allocate_purchase_invoice_number(r.organization_id,r.source_type,r.source_id,r.transaction_date);
    if r.source_type='ASSET' then update public.transactions set purchase_number=num where id=r.source_id;
    else update public.vat_documents set purchase_number=num where id=r.source_id; end if;
  end loop;
  update public.vat_documents d set purchase_number=t.purchase_number from public.transactions t
    where d.asset_transaction_id=t.id and d.organization_id=t.organization_id
      and d.document_type='PURCHASE' and d.document_kind='INVOICE';
end $$;
alter table public.vat_documents enable trigger guard_accounting_invoice_source;

create function private.assign_asset_purchase_number()
returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
begin
  if tg_op='UPDATE' and old.purchase_number is not null then
    if new.purchase_number is distinct from old.purchase_number or new.id<>old.id
      or new.organization_id is distinct from old.organization_id or new.transaction_type<>old.transaction_type
      or new.reversal_of_transaction_id is distinct from old.reversal_of_transaction_id then
      raise exception 'PURCHASE_NUMBER_IMMUTABLE';
    end if;
    return new;
  end if;
  new.purchase_number := null;
  if new.organization_id is not null and new.transaction_type='PURCHASE' and new.reversal_of_transaction_id is null then
    new.purchase_number := private.allocate_purchase_invoice_number(new.organization_id,'ASSET',new.id,new.transaction_date);
  end if;
  return new;
end $$;

create function private.assign_vat_purchase_number()
returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
declare asset_number text;
begin
  if tg_op='UPDATE' and old.purchase_number is not null then
    if new.purchase_number is distinct from old.purchase_number or new.id<>old.id
      or new.organization_id is distinct from old.organization_id or new.document_type<>old.document_type
      or new.document_kind<>old.document_kind or new.asset_transaction_id is distinct from old.asset_transaction_id then
      raise exception 'PURCHASE_NUMBER_IMMUTABLE';
    end if;
    return new;
  end if;
  new.purchase_number := null;
  if new.document_type='PURCHASE' and new.document_kind='INVOICE' then
    if new.asset_transaction_id is not null then
      select purchase_number into asset_number from public.transactions
        where id=new.asset_transaction_id and organization_id=new.organization_id and transaction_type='PURCHASE';
      if asset_number is null then raise exception 'PURCHASE_NUMBER_ASSET_SCOPE_MISMATCH'; end if;
      new.purchase_number := asset_number;
    else
      new.purchase_number := private.allocate_purchase_invoice_number(new.organization_id,'VAT',new.id,new.transaction_date);
    end if;
  end if;
  return new;
end $$;
revoke all on function private.assign_asset_purchase_number(), private.assign_vat_purchase_number() from public,anon,authenticated;
create trigger assign_asset_purchase_number before insert or update on public.transactions
  for each row execute function private.assign_asset_purchase_number();
create trigger assign_vat_purchase_number before insert or update on public.vat_documents
  for each row execute function private.assign_vat_purchase_number();
comment on column public.transactions.purchase_number is 'Immutable company/year internal purchase number. reference remains the supplier invoice reference.';
comment on column public.vat_documents.purchase_number is 'Shared internal purchase number; asset aliases reuse the transaction number. document_number remains the supplier reference.';

;

\echo MIGRATION 20261027090748 replay_asset_opening_edit_archive
-- Opening edits are one atomic command: asset, source voucher and lot move together.
DO $guard$
DECLARE definition text;
BEGIN
 SELECT pg_get_functiondef('public.guard_asset_acquisition_edit()'::regprocedure) INTO definition;
 IF position('app.asset_opening_edit' IN definition)=0 THEN
  definition:=replace(definition,E'begin\n',E'begin\n if current_user=\'postgres\' and auth.uid() is not null and current_setting(\'app.asset_opening_edit\',true)=old.id::text and coalesce(old.metadata->>\'acquisition_mode\',\'OPENING_BALANCE\')=\'OPENING_BALANCE\' then return new;end if;\n');
  EXECUTE definition;
 END IF;
END $guard$;

CREATE OR REPLACE FUNCTION private.manage_asset_opening(p_asset_id uuid,p_action text,p_expected_updated_at timestamptz DEFAULT NULL,p_changes jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a public.asset_accounts%rowtype;t public.transactions%rowtype;l public.lots%rowtype;
 reason text;editable boolean;v_name text;v_date date;v_amount numeric;v_qty numeric;fx numeric;expected_fx numeric;v_purpose text;m jsonb;previous_context text;can_edit boolean;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED';END IF;
 IF p_action NOT IN('INSPECT','UPDATE','ARCHIVE') OR p_action IS NULL THEN RAISE EXCEPTION 'ASSET_OPENING_ACTION_INVALID';END IF;
 -- Use the same lock as personal snapshot creation before locking the asset/lot.
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('zakat-snapshot:'||auth.uid()::text,0));
 SELECT * INTO a FROM public.asset_accounts WHERE id=p_asset_id FOR UPDATE;
 IF a.id IS NULL THEN RAISE EXCEPTION 'ASSET_NOT_FOUND';END IF;
 IF (a.ownership_scope='PERSONAL' AND a.user_id IS DISTINCT FROM auth.uid()) OR
    (a.ownership_scope='ORGANIZATION' AND NOT public.has_organization_permission(a.organization_id,'assets.view')) THEN RAISE EXCEPTION 'ASSET_OPENING_ACCESS_DENIED';END IF;
 can_edit:=CASE WHEN a.ownership_scope='PERSONAL' THEN a.user_id=auth.uid() ELSE public.has_organization_permission(a.organization_id,'assets.edit') END;
 PERFORM 1 FROM public.transactions WHERE asset_account_id=a.id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.lots WHERE asset_account_id=a.id ORDER BY id FOR UPDATE;
 SELECT * INTO t FROM public.transactions WHERE asset_account_id=a.id ORDER BY created_at,id LIMIT 1;
 SELECT * INTO l FROM public.lots WHERE asset_account_id=a.id ORDER BY created_at,id LIMIT 1;
 reason:=CASE
  WHEN NOT can_edit THEN 'ASSET_OPENING_EDIT_DENIED'
  WHEN a.metadata->>'archived'='true' THEN 'ASSET_OPENING_ARCHIVED'
  WHEN a.asset_type IN('CASH','BANK','RECEIVABLE') OR a.metadata ?| ARRAY['investment_id','register_source','financing_contract_id'] THEN 'ASSET_OPENING_OTHER_WORKSPACE'
  WHEN coalesce(a.metadata->>'acquisition_mode','OPENING_BALANCE')<>'OPENING_BALANCE' OR t.transaction_type<>'OPENING_BALANCE' OR t.id IS NULL OR l.id IS NULL THEN 'ASSET_OPENING_REQUIRED'
  WHEN t.reversal_of_transaction_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.transactions reversed WHERE reversed.reversal_of_transaction_id=t.id) OR t.transfer_id IS NOT NULL OR t.metadata->>'asset_deleted'='true' THEN 'ASSET_OPENING_LINKED'
  WHEN (SELECT count(*) FROM public.transactions WHERE asset_account_id=a.id)<>1 OR (SELECT count(*) FROM public.lots WHERE asset_account_id=a.id)<>1 OR l.source_transaction_id IS DISTINCT FROM t.id OR l.remaining_quantity IS DISTINCT FROM l.original_quantity OR l.remaining_value_base IS DISTINCT FROM l.original_value_base THEN 'ASSET_OPENING_LINKED'
  WHEN EXISTS(SELECT 1 FROM public.financial_events e WHERE e.source_record_id IN(a.id,t.id)) OR nullif(t.metadata->>'financial_event_id','') IS NOT NULL OR EXISTS(SELECT 1 FROM public.financial_event_links WHERE target_record_id IN(a.id,t.id,l.id)) THEN 'ASSET_OPENING_FINANCIAL_LINK'
  WHEN EXISTS(SELECT 1 FROM public.transaction_allocations WHERE transaction_id=t.id OR lot_id=l.id) OR EXISTS(SELECT 1 FROM public.transfers WHERE source_asset_account_id=a.id OR destination_asset_account_id=a.id) OR EXISTS(SELECT 1 FROM public.asset_lifecycle_commands WHERE asset_account_id=a.id) OR EXISTS(SELECT 1 FROM public.vat_documents WHERE asset_transaction_id=t.id) THEN 'ASSET_OPENING_LINKED'
  WHEN EXISTS(SELECT 1 FROM public.zakat_assessment_lines WHERE lot_id=l.id) OR EXISTS(SELECT 1 FROM public.zakat_payment_allocations WHERE asset_account_id=a.id OR lot_id=l.id) THEN 'ASSET_OPENING_ZAKAT_LINK'
  ELSE NULL END;
 editable:=reason IS NULL;
 IF p_action='INSPECT' THEN RETURN jsonb_build_object('asset',to_jsonb(a),'can_edit',editable,'can_archive',editable,'block_reason',reason);END IF;
 IF NOT editable THEN RAISE EXCEPTION '%',reason;END IF;
 IF p_expected_updated_at IS NULL OR a.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'ASSET_EDIT_CONFLICT';END IF;
 previous_context:=pg_catalog.current_setting('app.asset_opening_edit',true);
 IF p_action='UPDATE' THEN
  IF jsonb_typeof(p_changes)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_changes) k WHERE k NOT IN('name','date','amount','quantity','purpose','fx_rate','fx_rate_id','fx_rate_date','fx_rate_source')) THEN RAISE EXCEPTION 'ASSET_OPENING_CHANGE_FIELDS_INVALID';END IF;
  v_name:=btrim(p_changes->>'name');v_date:=(p_changes->>'date')::date;v_amount:=(p_changes->>'amount')::numeric;v_qty:=(p_changes->>'quantity')::numeric;fx:=(p_changes->>'fx_rate')::numeric;v_purpose:=coalesce(p_changes->>'purpose','');
  IF v_name IS NULL OR length(v_name) NOT BETWEEN 1 AND 200 OR v_date IS NULL OR v_amount IS NULL OR v_amount<=0 OR v_qty IS NULL OR v_qty<=0 OR fx IS NULL OR fx<=0 OR v_amount::text IN('NaN','Infinity','-Infinity') OR v_qty::text IN('NaN','Infinity','-Infinity') OR fx::text IN('NaN','Infinity','-Infinity') OR length(v_purpose)>2000 THEN RAISE EXCEPTION 'ASSET_OPENING_VALUES_INVALID';END IF;
  IF a.currency=t.base_currency AND fx<>1 THEN RAISE EXCEPTION 'ASSET_OPENING_FX_INVALID';END IF;
  IF a.currency<>t.base_currency THEN
   SELECT CASE WHEN f.from_currency=a.currency THEN f.rate ELSE 1/f.rate END INTO expected_fx FROM public.fx_rates f
    WHERE (f.organization_id IS NULL OR f.organization_id=a.organization_id) AND f.valuation_date<=v_date AND f.rate>0
      AND ((f.from_currency=a.currency AND f.to_currency=t.base_currency) OR (f.to_currency=a.currency AND f.from_currency=t.base_currency))
    ORDER BY (f.organization_id IS NOT NULL) DESC,f.valuation_date DESC,f.id DESC LIMIT 1;
   IF expected_fx IS NULL OR abs(expected_fx-fx)>0.00000001 THEN RAISE EXCEPTION 'ASSET_SAVED_FX_RATE_MISSING';END IF;
  END IF;
  m:=a.metadata||jsonb_build_object('quantity',v_qty,'purchase_value',v_amount,'opening_value',v_amount,'purchase_price',v_amount/v_qty,'purchase_date',v_date,'purpose',v_purpose,'acquisition_cost_base',v_amount*fx,'fx_rate',fx,'fx_rate_id',p_changes->'fx_rate_id','fx_rate_date',p_changes->'fx_rate_date','fx_rate_source',p_changes->'fx_rate_source');
  IF a.metadata->>'market_value' IS NULL OR (a.metadata->>'market_value')::numeric=coalesce((a.metadata->>'purchase_value')::numeric,(a.metadata->>'opening_value')::numeric) THEN m:=m||jsonb_build_object('market_value',v_amount,'estimated_value',v_amount);END IF;
  IF a.metadata->>'market_price_source'='ACQUISITION_COST' THEN m:=m||jsonb_build_object('market_price',v_amount/v_qty,'market_price_per_unit',v_amount/v_qty,'market_valuation_date',v_date);END IF;
  PERFORM pg_catalog.set_config('app.asset_opening_edit',a.id::text,true);
  UPDATE public.asset_accounts SET name=v_name,metadata=m,updated_at=clock_timestamp() WHERE id=a.id;
  UPDATE public.transactions SET transaction_date=v_date,quantity=v_qty,unit_price=v_amount/v_qty,gross_value=v_amount,base_value=v_amount*fx,metadata=metadata||m WHERE id=t.id;
  UPDATE public.lots SET acquisition_date=v_date,original_quantity=v_qty,remaining_quantity=v_qty,original_value_base=v_amount*fx,remaining_value_base=v_amount*fx,
   hawl_start_date=CASE WHEN hawl_start_date=t.transaction_date THEN v_date ELSE hawl_start_date END,
   origin_hawl_start_date=CASE WHEN origin_hawl_start_date=t.transaction_date THEN v_date ELSE origin_hawl_start_date END,
   nisab_reached_date=CASE WHEN nisab_reached_date=t.transaction_date THEN v_date ELSE nisab_reached_date END,
   zakatable_pool_entered_date=CASE WHEN zakatable_pool_entered_date=t.transaction_date THEN v_date ELSE zakatable_pool_entered_date END,
   hawl_due_date=CASE WHEN hawl_start_date=t.transaction_date THEN NULL ELSE hawl_due_date END WHERE id=l.id;
 ELSE
  UPDATE public.lots SET remaining_quantity=0,remaining_value_base=0,status='CLOSED',metadata=metadata||jsonb_build_object('opening_archived',true) WHERE id=l.id;
  UPDATE public.transactions SET metadata=metadata||jsonb_build_object('asset_deleted',true,'deleted_at',clock_timestamp(),'deleted_by',auth.uid()) WHERE id=t.id;
  UPDATE public.asset_accounts SET metadata=metadata||jsonb_build_object('archived',true,'archived_at',clock_timestamp(),'archived_by',auth.uid()),updated_at=clock_timestamp() WHERE id=a.id;
 END IF;
 PERFORM pg_catalog.set_config('app.asset_opening_edit',coalesce(previous_context,''),true);
 INSERT INTO public.audit_logs(user_id,entity_type,entity_id,action,old_data,new_data) VALUES(auth.uid(),'asset_account',a.id,CASE WHEN p_action='UPDATE' THEN 'AMEND_OPENING_BALANCE' ELSE 'ARCHIVE_OPENING_BALANCE' END,to_jsonb(a),jsonb_build_object('transaction_id',t.id,'changes',p_changes-'fx_rate_id'));
 SELECT * INTO a FROM public.asset_accounts WHERE id=p_asset_id;
 RETURN jsonb_build_object('asset',to_jsonb(a),'archived',p_action='ARCHIVE','can_edit',p_action='UPDATE','can_archive',p_action='UPDATE','block_reason',NULL);
END $$;
REVOKE ALL ON FUNCTION private.manage_asset_opening(uuid,text,timestamptz,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.manage_asset_opening(uuid,text,timestamptz,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.manage_asset_opening(p_asset_id uuid,p_action text,p_expected_updated_at timestamptz DEFAULT NULL,p_changes jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT private.manage_asset_opening(p_asset_id,p_action,p_expected_updated_at,p_changes); $$;
REVOKE ALL ON FUNCTION public.manage_asset_opening(uuid,text,timestamptz,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.manage_asset_opening(uuid,text,timestamptz,jsonb) TO authenticated;

;

\echo MIGRATION 20261027090804 replay_corporate_zakat_assessment_workflow
-- Immutable source evidence and a single financial obligation per reviewed period.
create table public.corporate_zakat_sources (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id),
 model text not null check(model in('SIMPLE','SAUDI')), assessment_date date not null, period_start date,
 currency text not null, entries jsonb not null, warnings jsonb not null default '[]', created_by uuid not null references auth.users(id), created_at timestamptz not null default now()
);
alter table public.corporate_zakat_sources enable row level security;
revoke all on public.corporate_zakat_sources from public,anon,authenticated;
grant select on public.corporate_zakat_sources to authenticated;
create policy corporate_zakat_sources_read on public.corporate_zakat_sources for select to authenticated using(public.has_organization_permission(organization_id,'zakat.view'));
create index corporate_zakat_sources_org on public.corporate_zakat_sources(organization_id,created_at desc);

create table public.corporate_zakat_finalizations (
 assessment_id uuid primary key references public.manual_zakat_assessments(id), organization_id uuid not null references public.organizations(id),
 period_start date not null, period_end date not null check(period_end>=period_start),
 final_base numeric not null check(final_base>=0), final_rate numeric not null check(final_rate>=0 and final_rate<=1), amount numeric not null check(amount>=0),
 review_reference text not null, financial_event_id uuid unique references public.financial_events(id), obligation_id uuid unique references public.financial_event_obligations(id), flow_id uuid unique references public.liquidity_flows(id) on delete set null,
 prepared_by uuid not null references auth.users(id), created_at timestamptz not null default now(), approved_by uuid references auth.users(id), approved_at timestamptz, cancelled_at timestamptz,
 check((amount=0 and financial_event_id is null and obligation_id is null and flow_id is null) or (amount>0 and financial_event_id is not null and obligation_id is not null))
);
alter table public.corporate_zakat_finalizations enable row level security;
revoke all on public.corporate_zakat_finalizations from public,anon,authenticated;
grant select on public.corporate_zakat_finalizations to authenticated;
create policy corporate_zakat_finalizations_read on public.corporate_zakat_finalizations for select to authenticated using(public.has_organization_permission(organization_id,'zakat.view'));
create index corporate_zakat_finalizations_org on public.corporate_zakat_finalizations(organization_id,period_start,period_end);

create or replace function private.capture_corporate_zakat_sources(p_org uuid,p_model text,p_date date,p_start date default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare cur text; items jsonb:='[]';warnings jsonb:='[]'; rec record; field text;val numeric;qty numeric;cost numeric;mid uuid;future boolean;rowdata public.corporate_zakat_sources%rowtype;
begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED';end if;
 if not public.has_organization_permission(p_org,'zakat.view') or not public.has_organization_permission(p_org,'assets.view') or not public.financial_core_can(p_org,'financial_core.view') or not public.has_organization_permission(p_org,'liquidity.view') then raise exception 'CORPORATE_ZAKAT_ACCESS_DENIED';end if;
 if p_model not in('SIMPLE','SAUDI') or p_date is null or p_date>(now() at time zone 'Asia/Riyadh')::date or p_start>p_date then raise exception 'CORPORATE_ZAKAT_DATE_INVALID';end if;
 select base_currency into cur from public.organizations where id=p_org;
 -- Current account book balance, rolled back by actual dated movements only.
 if p_model='SIMPLE' then
 for rec in select * from public.liquidity_accounts where organization_id=p_org and account_type in('CASH','BANK','WALLET') loop
  if rec.metadata->>'opening_date'>p_date::text then continue;end if;
  if rec.currency<>cur then
   warnings:=warnings||jsonb_build_array('FOREIGN_CASH_REQUIRES_VALUATION');continue;
  end if;
  val:=rec.current_balance_base;
  select val-coalesce(sum(case when s.direction='INFLOW' then s.base_amount else -s.base_amount end),0) into val from public.liquidity_settlements s where s.account_id=rec.id and s.organization_id=p_org and s.status in('POSTED','REVERSED') and s.settlement_date>p_date;
  select val-coalesce(sum(case when f.direction='INFLOW' then f.base_amount else -f.base_amount end),0) into val from public.liquidity_flows f where f.account_id=rec.id and f.organization_id=p_org and f.status='ACTUAL' and f.due_date>p_date and not exists(select 1 from public.financial_event_links l where l.target_record_id=f.id and l.target_module='liquidity_flows');
  if val<0 then warnings:=warnings||jsonb_build_array('NEGATIVE_CASH_REQUIRES_REVIEW');continue;end if;
  items:=items||jsonb_build_array(jsonb_build_object('field','cash','id',rec.id,'name',rec.name,'value',val,'source','LIQUIDITY','date',p_date));
 end loop;
 end if;
 -- Explicit obligations, never event-line sums for receivables or liabilities.
 for rec in select o.*,e.event_date,e.description,e.source_module from public.financial_event_obligations o join public.financial_events e on e.id=o.event_id and e.organization_id=o.organization_id where o.organization_id=p_org and o.adjusts_obligation_id is null and o.obligation_type in('RECEIVABLE','PAYABLE') and e.status='ACTUAL' and e.event_date<=p_date and e.source_module<>'ZAKAT_ASSESSMENT' loop
  val:=rec.settleable_base_amount;
  select val+coalesce(sum(case when a.adjustment_effect='INCREASE' then a.settleable_base_amount else -a.settleable_base_amount end),0) into val from public.financial_event_obligations a join public.financial_events e on e.id=a.event_id where a.adjusts_obligation_id=rec.id and e.status='ACTUAL' and e.event_date<=p_date;
  select val-coalesce(sum(a.base_amount),0) into val from public.financial_event_obligation_allocations a join public.financial_events e on e.id=a.application_event_id where a.obligation_id=rec.id and e.status='ACTUAL' and e.event_date<=p_date;
  if val<=0 then continue;end if;
  field:=case when rec.obligation_type='RECEIVABLE' then 'debtors' when p_model='SIMPLE' then 'due_debts' else 'liabilities' end;
  if p_model='SAUDI' and field='debtors' then continue;end if;
  items:=items||jsonb_build_array(jsonb_build_object('field',field,'id',rec.id,'name',rec.description,'value',val,'source','OBLIGATIONS','date',p_date));
 end loop;
 if p_date<(now() at time zone 'Asia/Riyadh')::date and exists(select 1 from public.financial_events e where e.organization_id=p_org and e.status='REVERSED') then warnings:=warnings||jsonb_build_array('HISTORICAL_REVERSALS_REQUIRE_REVIEW');end if;
 -- Original lot values less allocations provide book values; never use a future quote.
 for rec in select * from public.asset_accounts where organization_id=p_org and ownership_scope='ORGANIZATION' and asset_type not in('CASH','BANK','RECEIVABLE') and coalesce(metadata->>'archived','false')<>'true' loop
  select coalesce(sum(l.remaining_quantity),0),coalesce(sum(l.remaining_value_base),0) into qty,cost from public.lots l where l.asset_account_id=rec.id and l.acquisition_date<=p_date and coalesce(l.metadata->>'recognition_pending','false')<>'true';
  if qty<=0 then continue;end if;
  select exists(select 1 from public.transactions t where t.asset_account_id=rec.id and t.transaction_date>p_date) into future;
  if future then warnings:=warnings||jsonb_build_array('ASSET_HISTORY_REQUIRES_REVIEW');continue;end if;
  field:=null;
  if p_model='SAUDI' then
   if rec.asset_class_code in('PPE','INTANGIBLE') or rec.asset_type='REAL_ESTATE' and coalesce(rec.metadata->>'holding_purpose','')<>'TRADE' then field:='fixed_assets';
   elsif rec.asset_class_code='INVESTMENT' or rec.asset_type='STOCK' or rec.metadata ? 'investment_id' then field:='deductible_investments';end if;
   val:=cost;
  else
   field:=case when rec.asset_class_code='INVENTORY' or rec.asset_type='INVENTORY' or rec.asset_type='REAL_ESTATE' and rec.metadata->>'holding_purpose'='TRADE' then 'inventory' when rec.asset_class_code='INVESTMENT' or rec.asset_type='STOCK' or rec.metadata ? 'investment_id' then 'investments' when rec.is_zakatable then 'other' else null end;
   val:=cost;
   if coalesce(rec.metadata->>'market_valuation_date','9999-12-31')<=p_date::text and coalesce(rec.metadata->>'market_price_currency',rec.currency)=cur and coalesce((rec.metadata->>'market_price_per_unit')::numeric,(rec.metadata->>'market_price')::numeric,0)>0 then val:=qty*coalesce((rec.metadata->>'market_price_per_unit')::numeric,(rec.metadata->>'market_price')::numeric);end if;
  end if;
  if field is not null then items:=items||jsonb_build_array(jsonb_build_object('field',field,'id',rec.id,'name',rec.name,'value',val,'source','ASSET_BOOK_OR_SAVED_VALUE','date',p_date));end if;
 end loop;
 -- Investment balances are sourced once from the dedicated investment ledger.
 for rec in select i.*,sum(case when m.kind='CAPITAL_RECEIPT' then m.amount when m.kind in('CAPITAL_RETURN','LOSS') then -m.amount else 0 end) carrying from public.participation_contracts i join public.participation_movements m on m.contract_id=i.id and m.organization_id=i.organization_id where i.organization_id=p_org and i.direction='OUTGOING' and i.deleted_at is null and m.execution_state='POSTED' and m.event_date<=p_date group by i.id loop
  if rec.currency<>cur then warnings:=warnings||jsonb_build_array('FOREIGN_INVESTMENT_REQUIRES_VALUATION');continue;end if;
  if rec.carrying>0 then items:=items||jsonb_build_array(jsonb_build_object('field',case when p_model='SIMPLE' then 'investments' else 'deductible_investments' end,'id',rec.id,'name',rec.project,'value',rec.carrying,'source','INVESTMENT_LEDGER','date',p_date));end if;
 end loop;
 if p_model='SAUDI' then
  for rec in select l.id,e.event_date,e.description,l.base_amount,c.classification_type from public.financial_event_lines l join public.financial_events e on e.id=l.event_id and e.organization_id=l.organization_id join public.financial_classifications c on c.id=l.classification_id and c.organization_id=l.organization_id where l.organization_id=p_org and e.status='ACTUAL' and e.event_date<=p_date and (c.classification_type='EQUITY' or p_start is not null and e.event_date>=p_start and c.classification_type in('REVENUE','OPEX','ZAKAT')) loop
   field:=case when rec.classification_type='EQUITY' then 'equity' else 'book_profit' end;val:=case when rec.classification_type in('OPEX','ZAKAT') then -rec.base_amount else rec.base_amount end;
   items:=items||jsonb_build_array(jsonb_build_object('field',field,'id',rec.id,'name',rec.description,'value',val,'source','FINANCIAL_LEDGER','date',rec.event_date));
  end loop;
 end if;
 insert into public.corporate_zakat_sources(organization_id,model,assessment_date,period_start,currency,entries,warnings,created_by) values(p_org,p_model,p_date,p_start,cur,items,warnings,auth.uid()) returning * into rowdata;
 return to_jsonb(rowdata);
end $$;
revoke all on function private.capture_corporate_zakat_sources(uuid,text,date,date) from public,anon;
grant execute on function private.capture_corporate_zakat_sources(uuid,text,date,date) to authenticated;
create function public.capture_corporate_zakat_sources(p_org uuid,p_model text,p_date date,p_start date default null) returns jsonb language sql security invoker set search_path='' as $$select private.capture_corporate_zakat_sources($1,$2,$3,$4);$$;
revoke all on function public.capture_corporate_zakat_sources(uuid,text,date,date) from public,anon;
grant execute on function public.capture_corporate_zakat_sources(uuid,text,date,date) to authenticated;

create or replace function private.corporate_zakat_command(p_action text,p_id uuid,p_payload jsonb default '{}')
returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.manual_zakat_assessments%rowtype;f public.corporate_zakat_finalizations%rowtype;e public.financial_events%rowtype;cur text;eid uuid;oid uuid;fid uuid;cid uuid;cat uuid;v numeric;ded numeric;base numeric;rate numeric;due numeric;startd date;reference text;fp jsonb;fields text[];item text;sn public.corporate_zakat_sources%rowtype;
begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED';end if;
 select * into a from public.manual_zakat_assessments where id=p_id;
 if a.id is null or a.organization_id is null or a.model not in('SIMPLE','SAUDI') then raise exception 'CORPORATE_ZAKAT_ASSESSMENT_REQUIRED';end if;
 if not public.has_organization_permission(a.organization_id,'zakat.edit') or not public.financial_core_can(a.organization_id,'financial_core.view') then raise exception 'CORPORATE_ZAKAT_ACCESS_DENIED';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('corporate-zakat:'||a.organization_id::text,0));
 select * into f from public.corporate_zakat_finalizations where assessment_id=a.id for update;
 if p_action='PREPARE' then
  if f.assessment_id is not null then raise exception 'CORPORATE_ZAKAT_ALREADY_PREPARED';end if;
  if not public.financial_core_can(a.organization_id,'financial_core.create') then raise exception 'CORPORATE_ZAKAT_CREATE_DENIED';end if;
  if a.input->>'organization_id' is distinct from a.organization_id::text or a.input->>'assessment_date' is distinct from a.assessment_date::text or a.input->>'independent_source_confirmed' is distinct from 'true' then raise exception 'CORPORATE_ZAKAT_VALUES_INVALID';end if;
  if p_payload->>'review_confirmed' is distinct from 'true' then raise exception 'CORPORATE_ZAKAT_REVIEW_REQUIRED';end if;
  startd:=(p_payload->>'period_start')::date;reference:=btrim(p_payload->>'review_reference');
  if startd is null or startd>a.assessment_date or a.assessment_date>(now() at time zone 'Asia/Riyadh')::date or length(coalesce(reference,'')) not between 10 and 1000 then raise exception 'CORPORATE_ZAKAT_REVIEW_REQUIRED';end if;
  select base_currency into cur from public.organizations where id=a.organization_id;
  if cur<>a.currency then raise exception 'CORPORATE_ZAKAT_BASE_CURRENCY_REQUIRED';end if;
  if exists(select 1 from public.corporate_zakat_finalizations x left join public.financial_events ev on ev.id=x.financial_event_id where x.organization_id=a.organization_id and x.period_start<=a.assessment_date and x.period_end>=startd and x.cancelled_at is null and (x.financial_event_id is null or ev.status not in('CANCELLED','REVERSED'))) then raise exception 'CORPORATE_ZAKAT_PERIOD_ALREADY_EXISTS';end if;
  if nullif(a.input->>'source_snapshot_id','') is not null then
   select * into sn from public.corporate_zakat_sources where id=(a.input->>'source_snapshot_id')::uuid and organization_id=a.organization_id and model=a.model and assessment_date=a.assessment_date and currency=a.currency;
   if sn.id is null then raise exception 'CORPORATE_ZAKAT_SOURCE_MISMATCH';end if;
   if sn.period_start is distinct from nullif(a.input->>'period_start','')::date then raise exception 'CORPORATE_ZAKAT_SOURCE_MISMATCH';end if;
  end if;
  if a.model='SIMPLE' then
   fields:=array['cash','debtors','inventory','investments','other','due_debts'];base:=0;ded:=0;
   foreach item in array fields loop
    if a.input->'values'->>item is null then raise exception 'CORPORATE_ZAKAT_FIELDS_INCOMPLETE';end if;
    v:=(a.input->'values'->>item)::numeric;if v<0 or v>1000000000000 or v::text in('NaN','Infinity','-Infinity') then raise exception 'CORPORATE_ZAKAT_VALUES_INVALID';end if;
    if item='due_debts' then ded:=v;else base:=base+v;end if;
   end loop;
   if a.input->>'debt_policy'='DUE' then base:=base-ded;end if;base:=greatest(base,0);rate:=0.025;
   if a.input->>'hawl_completed' is distinct from 'true' or coalesce((a.input->>'nisab_value')::numeric,0)<=0 or coalesce(a.input->>'nisab_reference','')='' then raise exception 'CORPORATE_ZAKAT_CONDITIONS_REQUIRED';end if;
   if base<(a.input->>'nisab_value')::numeric then base:=0;end if;
   if a.input->>'period_basis'='FINANCIAL' then
    if nullif(a.input->>'period_start','')::date is distinct from startd or nullif(a.input->>'period_end','')::date is distinct from a.assessment_date or (a.input->>'hijri_days')::int not in(354,355) then raise exception 'CORPORATE_ZAKAT_DATE_INVALID';end if;
    rate:=rate*(a.assessment_date-startd+1)/(a.input->>'hijri_days')::numeric;
   end if;
  else
   fields:=array['equity','liabilities','book_profit','adjusted_profit','fixed_assets','deductible_investments','other_deductions'];
   foreach item in array fields loop
    if a.input->'values'->>item is null then raise exception 'CORPORATE_ZAKAT_FIELDS_INCOMPLETE';end if;
    v:=(a.input->'values'->>item)::numeric;if abs(v)>1000000000000 or v::text in('NaN','Infinity','-Infinity') or v<0 and item not in('book_profit','adjusted_profit') then raise exception 'CORPORATE_ZAKAT_VALUES_INVALID';end if;
   end loop;
   base:=(p_payload->>'final_base')::numeric;rate:=(p_payload->>'final_rate')::numeric;
   if base is null or base<0 or base>1000000000000 or rate is null or rate<=0 or rate>0.1 or base::text in('NaN','Infinity','-Infinity') or rate::text in('NaN','Infinity','-Infinity') or p_payload->>'regulatory_confirmed' is distinct from 'true' then raise exception 'CORPORATE_ZAKAT_REGULATORY_REVIEW_REQUIRED';end if;
  end if;
  due:=round(base*rate,2);
  if due>0 then
   insert into public.financial_classifications(organization_id,code,name,classification_type,is_system,created_by) values(a.organization_id,'CORPORATE_ZAKAT_ACCRUAL','استحقاق الزكاة المؤسسية','ZAKAT',true,auth.uid()) on conflict(organization_id,code) do nothing;
   select id into cid from public.financial_classifications where organization_id=a.organization_id and code='CORPORATE_ZAKAT_ACCRUAL' and classification_type='ZAKAT' and active;
   if cid is null then raise exception 'CORPORATE_ZAKAT_CLASSIFICATION_REQUIRED';end if;
   perform pg_catalog.set_config('app.corporate_zakat',a.id::text,true);
   eid:=public.create_financial_event_command(jsonb_build_object('organization_id',a.organization_id,'event_type','EXPENSE','source_module','ZAKAT_ASSESSMENT','source_record_id',a.id,'source_event_key','corporate-zakat:'||a.id,'description','زكاة / '||a.title,'event_date',a.assessment_date,'due_date',a.assessment_date,'base_currency',cur,
    'lines',jsonb_build_array(jsonb_build_object('line_number',1,'description',a.title,'classification_id',cid,'amount',due,'currency',cur,'exchange_rate',1,'base_amount',due,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0)),
    'obligations',jsonb_build_array(jsonb_build_object('obligation_key','corporate-zakat','obligation_type','PAYABLE','settleable_amount',due,'currency',cur,'exchange_rate',1,'base_currency',cur,'settleable_base_amount',due))));
   perform pg_catalog.set_config('app.corporate_zakat','',true);
   select id into oid from public.financial_event_obligations where event_id=eid and obligation_key='corporate-zakat';
   insert into public.liquidity_flow_categories(organization_id,code,name_ar,name_en,flow_group,allowed_direction,accounting_group,treatment_code,is_system) values(a.organization_id,'CORPORATE_ZAKAT_ACCRUAL','استحقاق الزكاة','Zakat liability','TAX','OUTFLOW','ZAKAT','ZAKAT_ACCRUAL',true) on conflict(organization_id,code) do nothing;
   select id into cat from public.liquidity_flow_categories where organization_id=a.organization_id and code='CORPORATE_ZAKAT_ACCRUAL' and accounting_group='ZAKAT' and active;
   if cat is null then raise exception 'CORPORATE_ZAKAT_CLASSIFICATION_REQUIRED';end if;
   insert into public.liquidity_flows(category_id,organization_id,direction,flow_type,title,due_date,amount,currency,base_amount,status,source,source_module,source_record_id,source_event_key,created_by)
    values(cat,a.organization_id,'OUTFLOW','TAX','زكاة / '||a.title,a.assessment_date,due,cur,due,'EXPECTED','ACCOUNTING','ZAKAT_ASSESSMENT',a.id,'corporate-zakat:'||a.id,auth.uid()) returning id into fid;
   insert into public.financial_event_links(event_id,organization_id,link_type,target_module,target_record_id,metadata,created_by) values(eid,a.organization_id,'CASH_FLOW','liquidity_flows',fid,jsonb_build_object('obligation_id',oid,'manual_assessment_id',a.id,'due_date',a.assessment_date),auth.uid());
   perform public.transition_financial_event(eid,'PLANNED','Corporate zakat review');perform public.transition_financial_event(eid,'COMMITTED','Corporate zakat submitted');
  end if;
  insert into public.corporate_zakat_finalizations(assessment_id,organization_id,period_start,period_end,final_base,final_rate,amount,review_reference,financial_event_id,obligation_id,flow_id,prepared_by) values(a.id,a.organization_id,startd,a.assessment_date,base,rate,due,reference,eid,oid,fid,auth.uid()) returning * into f;
 elsif p_action in('APPROVE','POST','CANCEL') then
  if f.assessment_id is null then raise exception 'CORPORATE_ZAKAT_NOT_PREPARED';end if;
  if f.cancelled_at is not null then raise exception 'CORPORATE_ZAKAT_CANCELLED';end if;
  if f.financial_event_id is not null then
   select * into e from public.financial_events where id=f.financial_event_id for update;
   if p_action='APPROVE' and e.status='ACTUAL' then return to_jsonb(f);end if;
   if p_action='APPROVE' then if not public.financial_event_has_valid_approval(e.id) then perform public.approve_financial_event(e.id,'Corporate zakat reviewed: '||f.review_reference);end if;
   elsif p_action='POST' then if e.status<>'ACTUAL' then perform public.transition_financial_event(e.id,'ACTUAL','Corporate zakat liability recognized');end if;
   elsif p_action='CANCEL' then
    if e.status not in('DRAFT','PLANNED','COMMITTED') then raise exception 'CORPORATE_ZAKAT_POSTED_CORRECTION_REQUIRED';end if;
    perform public.transition_financial_event(e.id,'CANCELLED',coalesce(p_payload->>'reason','Corporate zakat review cancelled'));
    delete from public.financial_event_links where event_id=e.id and target_record_id=f.flow_id;
    delete from public.liquidity_flows where id=f.flow_id; -- historical finalization link retained by nullable FK below
   end if;
  else
   if p_action='CANCEL' and f.approved_at is null and public.financial_core_can(a.organization_id,'financial_core.create') then
    update public.corporate_zakat_finalizations set cancelled_at=now() where assessment_id=a.id returning * into f;return to_jsonb(f);
   end if;
   if p_action='APPROVE' and f.approved_at is not null then return to_jsonb(f);end if;
   if p_action<>'APPROVE' or not public.financial_core_can(a.organization_id,'financial_core.approve') or f.prepared_by=auth.uid() and not public.can_self_approve_financial_event(a.organization_id) then raise exception 'CORPORATE_ZAKAT_APPROVE_DENIED';end if;
   update public.corporate_zakat_finalizations set approved_by=auth.uid(),approved_at=now() where assessment_id=a.id and approved_at is null returning * into f;
  end if;
 else raise exception 'CORPORATE_ZAKAT_ACTION_INVALID';end if;
 insert into public.audit_logs(user_id,entity_type,entity_id,action,new_data) values(auth.uid(),'manual_zakat_assessment',a.id,'CORPORATE_ZAKAT_'||p_action,to_jsonb(f));
 return to_jsonb(f);
end $$;
revoke all on function private.corporate_zakat_command(text,uuid,jsonb) from public,anon;
grant execute on function private.corporate_zakat_command(text,uuid,jsonb) to authenticated;
create function public.corporate_zakat_command(p_action text,p_id uuid,p_payload jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select private.corporate_zakat_command($1,$2,$3);$$;
revoke all on function public.corporate_zakat_command(text,uuid,jsonb) from public,anon;
grant execute on function public.corporate_zakat_command(text,uuid,jsonb) to authenticated;

create or replace view public.corporate_zakat_workflow with (security_invoker=true) as
select f.*,case when f.cancelled_at is not null then 'CANCELLED' when f.financial_event_id is null then case when f.approved_at is null then 'COMMITTED' else 'ACTUAL' end else coalesce(e.status,'UNAVAILABLE') end event_status,
case when f.financial_event_id is null then f.approved_at is not null else public.financial_event_has_valid_approval(f.financial_event_id) end approved,
case when e.status='ACTUAL' then coalesce(b.applied_base_amount,0) else 0 end paid,
case when f.cancelled_at is not null or e.status in('CANCELLED','REVERSED') then 0 when e.status='ACTUAL' then coalesce(b.outstanding_base_amount,f.amount) else f.amount end remaining
from public.corporate_zakat_finalizations f left join public.financial_events e on e.id=f.financial_event_id and e.organization_id=f.organization_id
left join public.financial_event_obligation_balances b on b.obligation_id=f.obligation_id and b.organization_id=f.organization_id;
revoke all on public.corporate_zakat_workflow from public,anon;grant select on public.corporate_zakat_workflow to authenticated;
-- Source namespace is reserved for the bounded assessment command.
do $guard$
declare definition text;
begin
 select pg_get_functiondef('public.create_financial_event_command(jsonb)'::regprocedure) into definition;
 if position('CORPORATE_ZAKAT_SOURCE_NAMESPACE_RESERVED' in definition)=0 then
  if position('return private.phase2c_create_financial_event_internal(p_payload)' in definition)=0 then raise exception 'CORPORATE_ZAKAT_CORE_WRAPPER_CHANGED';end if;
  definition:=replace(definition,'return private.phase2c_create_financial_event_internal(p_payload)',
   $patch$if trim(p_payload->>'source_module')='ZAKAT_ASSESSMENT' and coalesce(current_setting('app.corporate_zakat',true),'') is distinct from nullif(p_payload->>'source_record_id','') then raise exception 'CORPORATE_ZAKAT_SOURCE_NAMESPACE_RESERVED';end if;return private.phase2c_create_financial_event_internal(p_payload)$patch$);
  execute definition;
 end if;
end $guard$;

;

\echo MIGRATION 20261027090807 replay_personal_payable_opening_edit
-- Narrow owner-scoped edit path. It never creates a cash movement or rewrites
-- payments, financing sources, party identity or the original create fingerprint.
create or replace function private.edit_personal_payable(p_payload jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 uid uuid:=auth.uid(); d public.personal_payables%rowtype; prior jsonb;
 amt numeric; dt date; due date; descr text; ref text;
begin
 if uid is null then raise exception 'UNAUTHORIZED';end if;
 if jsonb_typeof(p_payload) is distinct from 'object'
 or p_payload->>'action' is distinct from 'UPDATE'
 or not (p_payload ?& array['action','payable_id','description','amount','date','due_date','reference','category','expected'])
 or exists(select 1 from jsonb_object_keys(p_payload) k where k not in('action','payable_id','description','amount','date','due_date','reference','category','expected'))
 then raise exception 'VALIDATION_FAILED';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('personal-payable:'||uid::text,0));
 select * into d from public.personal_payables where id=(p_payload->>'payable_id')::uuid and user_id=uid for update;
 if d.id is null or d.cancelled_at is not null then raise exception 'PERSONAL_PAYABLE_ACCESS_DENIED';end if;
 prior:=jsonb_build_object('amount',d.amount,'date',d.event_date,'description',d.description,'due_date',d.due_date,'reference',d.reference);
 if p_payload->'expected' is distinct from prior then raise exception 'PERSONAL_PAYABLE_EDIT_CONFLICT';end if;
 amt:=(p_payload->>'amount')::numeric;dt:=(p_payload->>'date')::date;due:=nullif(p_payload->>'due_date','')::date;
 descr:=trim(p_payload->>'description');ref:=trim(p_payload->>'reference');
 if amt is null or amt<=0 or amt>1e12 or amt<>round(amt,4) or amt::text in('NaN','Infinity','-Infinity')
 or dt is null or dt>(now() at time zone 'Asia/Riyadh')::date or (due is not null and due<dt)
 or descr is null or length(descr) not between 3 and 500 or ref is null or length(ref)>120
 or p_payload->>'category' is null or p_payload->>'category' not in('P_AP_PERSON','P_AP_LOAN','P_AP_INSTALLMENT','P_AP_ACCRUAL','P_AP_OTHER')
 then raise exception 'VALIDATION_FAILED';end if;
 if (amt is distinct from d.amount or dt is distinct from d.event_date)
 and (exists(select 1 from public.personal_payable_payments where payable_id=d.id)
 or exists(select 1 from public.personal_financings where payable_id=d.id))
 then raise exception 'PERSONAL_PAYABLE_FINANCIAL_FIELDS_LOCKED';end if;
 if due is distinct from d.due_date and exists(select 1 from public.personal_financings where payable_id=d.id) then raise exception 'PERSONAL_FINANCING_USE_SOURCE';end if;
 update public.personal_payables set description=descr,amount=amt,event_date=dt,due_date=due,reference=ref where id=d.id and user_id=uid;
 perform private.assign_debt_category('PERSONAL_PAYABLE',d.id,p_payload->>'category');
 insert into public.audit_logs(user_id,entity_type,entity_id,action,old_data,new_data)
 values(uid,'personal_payable',d.id,'EDIT',prior,p_payload-'expected');
 return jsonb_build_object('id',d.id,'updated',true);
end $$;
revoke all on function private.edit_personal_payable(jsonb) from public,anon;
grant execute on function private.edit_personal_payable(jsonb) to authenticated;
create or replace function public.edit_personal_payable(p_payload jsonb)
returns jsonb language sql security invoker set search_path='' as $$select private.edit_personal_payable(p_payload);$$;
revoke all on function public.edit_personal_payable(jsonb) from public,anon;
grant execute on function public.edit_personal_payable(jsonb) to authenticated;

;

\echo MIGRATION 20261027090811 replay_personal_funding_category
-- Save the selected personal debt category within the existing atomic funding command.
-- Keep legacy clients' defaults and request fingerprints; do not rewrite existing rows.
do $patch$
declare definition text:=pg_get_functiondef('private.personal_financing_command(jsonb)'::regprocedure);
 old_fragment text:=$old$category:=case when side='RECEIVABLE'then case when kind='LOAN'then 'P_AR_LOAN'else 'P_AR_OTHER'end else case when kind='LOAN'then 'P_AP_LOAN'else 'P_AP_OTHER'end end;$old$;
 new_fragment text:=$new$category:=coalesce(nullif(p->>'category',''),case when side='RECEIVABLE'then case when kind='LOAN'then 'P_AR_LOAN'else 'P_AR_OTHER'end else case when kind='LOAN'then 'P_AP_LOAN'else 'P_AP_OTHER'end end);
 if (side='RECEIVABLE' and category not in('P_AR_PERSON','P_AR_LOAN','P_AR_RENT','P_AR_ASSET_SALE','P_AR_OTHER')) or (side='PAYABLE' and category not in('P_AP_PERSON','P_AP_LOAN','P_AP_INSTALLMENT','P_AP_ACCRUAL','P_AP_OTHER')) then raise exception 'DEBT_CATEGORY_SIDE_MISMATCH';end if;$new$;
begin
 if position(old_fragment in definition)=0 then raise exception 'PERSONAL_FINANCING_CATEGORY_PATCH_MISMATCH';end if;
 execute replace(definition,old_fragment,new_fragment);
end $patch$;

;

\echo MIGRATION 20261027090814 replay_personal_contracts_and_participations
-- Personal contract terms are presentation/control over the existing personal ledger.
-- No balance is stored here or added a second time to the financial position.
create table public.personal_contracts(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),request_id uuid not null,
 product text not null check(product in('QARD','FINANCING','PARTICIPATION')),side text not null check(side in('RECEIVABLE','PAYABLE')),
 status text not null default 'DRAFT' check(status in('DRAFT','EXECUTING','POSTED','CANCELLED')),
 revision integer not null default 0,terms jsonb not null,principal numeric(24,4) not null check(principal>0),currency text not null,
 asset_id uuid references public.asset_accounts(id),payable_id uuid references public.personal_payables(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,request_id)
);
create unique index personal_contract_asset_once on public.personal_contracts(asset_id)where asset_id is not null and status<>'CANCELLED';
create unique index personal_contract_payable_once on public.personal_contracts(payable_id)where payable_id is not null and status<>'CANCELLED';
create index personal_contract_owner on public.personal_contracts(user_id,id);
create table public.personal_contract_movements(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),contract_id uuid not null references public.personal_contracts(id),
 request_id uuid not null,kind text not null check(kind in('FUND','SETTLE','CHARGE','PROFIT','LOSS','SETTLE_CHARGE')),
 amount numeric(24,4) not null check(amount>0),operation_date date not null,notes text not null,
 asset_id uuid references public.asset_accounts(id),payable_id uuid references public.personal_payables(id),installment_number integer,
 transaction_ids uuid[] not null default '{}',fingerprint text not null,reversed_at timestamptz,created_at timestamptz not null default clock_timestamp(),unique(user_id,request_id)
);
create index personal_contract_movement_owner on public.personal_contract_movements(user_id,contract_id,id);
create index personal_contract_movement_asset on public.personal_contract_movements(asset_id)where asset_id is not null;
create index personal_contract_movement_payable on public.personal_contract_movements(payable_id)where payable_id is not null;
create unique index personal_contract_charge_once on public.personal_contract_movements(contract_id,installment_number)where kind='CHARGE'and reversed_at is null;
alter table public.personal_contracts enable row level security;
alter table public.personal_contract_movements enable row level security;
revoke all on public.personal_contracts,public.personal_contract_movements from public,anon,authenticated;
grant select on public.personal_contracts,public.personal_contract_movements to authenticated;
create policy personal_contract_owner_read on public.personal_contracts for select to authenticated using(user_id=(select auth.uid()));
create policy personal_contract_movement_owner_read on public.personal_contract_movements for select to authenticated using(user_id=(select auth.uid()));

create function private.personal_contract_balance(p_asset uuid,p_payable uuid)returns numeric language sql security invoker set search_path='' as $$
 select case when p_asset is not null then coalesce((select sum(remaining_value_base)from public.lots where asset_account_id=p_asset and user_id=auth.uid()),0)
 else coalesce((select case when d.cancelled_at is not null then 0 else d.amount-coalesce((select sum(p.amount)from public.personal_payable_payments p where p.payable_id=d.id and p.user_id=auth.uid()and not exists(select 1 from public.transactions t where t.user_id=auth.uid()and t.reversal_of_transaction_id=p.transaction_id)),0)end from public.personal_payables d where d.id=p_payable and d.user_id=auth.uid()),0)end;
$$;
revoke all on function private.personal_contract_balance(uuid,uuid)from public,anon,authenticated;

create function private.personal_contract_asset(p_contract uuid,p_type public.asset_type,p_amount numeric,p_date date,p_label text,p_role text)returns jsonb language plpgsql security invoker set search_path='' as $$
declare c public.personal_contracts%rowtype;a uuid;t uuid;begin
 select * into strict c from public.personal_contracts where id=p_contract and user_id=auth.uid()and status='EXECUTING';
 insert into public.asset_accounts(user_id,asset_type,name,currency,ownership_scope,unit,is_zakatable,metadata)
 values(c.user_id,p_type,p_label,c.currency,'PERSONAL','unit',coalesce((c.terms->>'zakatable')::boolean,true),jsonb_build_object('personal_contract_id',c.id,'contract_role',p_role,'entry_source','PERSONAL_CONTRACT','acquisition_mode','OPENING_BALANCE','purchase_date',p_date,'purchase_value',p_amount,'fx_rate',1,'due_date',c.terms->'schedule'->0->>'due_date'))returning id into a;
 if p_amount>0 then
  insert into public.transactions(user_id,asset_account_id,transaction_type,transaction_date,quantity,currency,gross_value,base_currency,base_value,reference,notes,metadata,created_by)
  values(c.user_id,a,'OPENING_BALANCE',p_date,p_amount,c.currency,p_amount,c.currency,p_amount,c.terms->>'reference',c.terms->>'description',jsonb_build_object('personal_contract_id',c.id,'non_cash',true,'contract_role',p_role),c.user_id)returning id into t;
  insert into public.lots(user_id,asset_account_id,source_transaction_id,acquisition_date,hawl_start_date,origin_hawl_start_date,zakatable_pool_entered_date,original_quantity,remaining_quantity,original_value_base,remaining_value_base,status)
  values(c.user_id,a,t,p_date,p_date,p_date,p_date,p_amount,p_amount,p_amount,p_amount,'ACTIVE');
 end if;return jsonb_build_object('asset_id',a,'transaction_id',t);
end $$;
revoke all on function private.personal_contract_asset(uuid,public.asset_type,numeric,date,text,text)from public,anon,authenticated;

create function private.personal_contract_cash(p_contract uuid,p_bank uuid,p_asset uuid,p_payable uuid,p_amount numeric,p_date date,p_req uuid,p_notes text,p_direction text)returns jsonb language plpgsql security invoker set search_path='' as $$
declare c public.personal_contracts%rowtype;b public.asset_accounts%rowtype;l record;remaining numeric:=p_amount;take numeric;qty numeric:=0;r jsonb;t uuid;ids uuid[]:='{}';src uuid;dst uuid;begin
 select * into strict c from public.personal_contracts where id=p_contract and user_id=auth.uid()and status='EXECUTING';
 perform id from public.asset_accounts where id in(p_bank,p_asset)and user_id=c.user_id order by id for update;
 select * into b from public.asset_accounts where id=p_bank and user_id=c.user_id and organization_id is null and ownership_scope='PERSONAL'and asset_type in('BANK','CASH')and currency=c.currency and coalesce(metadata->>'archived','false')<>'true';
 if b.id is null then raise exception 'PERSONAL_CONTRACT_BANK_INVALID';end if;
 if p_payable is not null then
  r:=private.personal_payable_command(jsonb_build_object('action','PAY','request_id',p_req,'payable_id',p_payable,'account_id',p_bank,'amount',p_amount,'date',p_date,'notes',p_notes));
  ids:=array[(r->>'transaction_id')::uuid];
 elsif p_asset is null and p_direction='INFLOW'then
  insert into public.transactions(user_id,asset_account_id,transaction_type,transaction_date,quantity,currency,gross_value,base_currency,base_value,reference,notes,metadata,created_by)
  values(c.user_id,p_bank,'ADD',p_date,p_amount,c.currency,p_amount,c.currency,p_amount,c.terms->>'reference',p_notes,jsonb_build_object('personal_contract_id',c.id),c.user_id)returning id into t;
  insert into public.lots(user_id,asset_account_id,source_transaction_id,acquisition_date,hawl_start_date,origin_hawl_start_date,zakatable_pool_entered_date,original_quantity,remaining_quantity,original_value_base,remaining_value_base,status)
  values(c.user_id,p_bank,t,p_date,p_date,p_date,p_date,p_amount,p_amount,p_amount,p_amount,'ACTIVE');ids:=array[t];
 else
  src:=case when p_direction='INFLOW'then p_asset else p_bank end;dst:=case when p_direction='INFLOW'then p_bank else p_asset end;
  for l in select * from public.lots where user_id=c.user_id and asset_account_id=src and remaining_quantity>0 and acquisition_date<=p_date order by acquisition_date,created_at,id for update loop
   exit when remaining<=0;if l.remaining_value_base<=0 then raise exception 'CASH_LOT_REVIEW_REQUIRED';end if;
   take:=least(remaining,l.remaining_value_base);qty:=qty+take*l.remaining_quantity/l.remaining_value_base;remaining:=remaining-take;
  end loop;
  if remaining>0 then raise exception 'CASH_INSUFFICIENT_BALANCE';end if;
  if dst is null then t:=public.post_withdrawal(c.user_id,src,p_date,qty,p_amount,c.currency,c.currency,p_amount,p_notes,'FIFO','WITHDRAWAL');ids:=array[t];
  else r:=public.create_internal_transfer(c.user_id,src,dst,p_date,qty,p_amount,c.currency,p_notes);if abs((r->>'transferred_cost_base')::numeric-p_amount)>0.0001 then raise exception 'PERSONAL_CONTRACT_RECONCILIATION_FAILED';end if;ids:=array[(r->>'out_transaction_id')::uuid,(r->>'in_transaction_id')::uuid];end if;
 end if;
 -- PAY returns a protected immutable transaction; its canonical payable link is sufficient.
 if p_payable is null then update public.transactions set reference=c.terms->>'reference',metadata=coalesce(metadata,'{}')||jsonb_build_object('personal_contract_id',c.id)where id=any(ids)and user_id=c.user_id;end if;
 return jsonb_build_object('transaction_ids',to_jsonb(ids));
end $$;
revoke all on function private.personal_contract_cash(uuid,uuid,uuid,uuid,numeric,date,uuid,text,text)from public,anon,authenticated;
alter table public.personal_contract_movements add column reversal_request_id uuid,add column reversal_fingerprint text;
create unique index personal_contract_reversal_once on public.personal_contract_movements(user_id,reversal_request_id)where reversal_request_id is not null;

create function private.personal_contract_command(p jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare uid uuid:=auth.uid();cmd text:=p->>'action';req uuid:=(p->>'request_id')::uuid;c public.personal_contracts%rowtype;m public.personal_contract_movements%rowtype;prior public.personal_contract_movements%rowtype;
 t jsonb:=p->'payload';r jsonb;plan jsonb;item jsonb;ids uuid[]:='{}';aid uuid;pid uuid;tid uuid;cid uuid;mid uuid:=gen_random_uuid();fp text:=md5(p::text);base text;
 principal numeric;amt numeric:=(p->>'amount')::numeric;dt date:=(p->>'date')::date;start_dt date;due date;last_due date;total numeric:=0;balance numeric;freq int;i int;qty numeric;remaining numeric;take numeric;l record;
begin
 if uid is null then raise exception 'UNAUTHORIZED';end if;
 if jsonb_typeof(p)is distinct from 'object'or cmd is null or cmd not in('SAVE','EXECUTE','CANCEL','SETTLE','CHARGE','PROFIT','LOSS','SETTLE_CHARGE','REVERSE')or exists(select 1 from jsonb_object_keys(p)k where k not in('action','id','request_id','expected_revision','payload','date','amount','account_id','number','movement_id','reason'))then raise exception 'VALIDATION_FAILED';end if;
 -- Serialize both directions, including links to a pre-existing personal financing.
 perform pg_advisory_xact_lock(hashtextextended('personal-contract:'||uid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('personal-financing:'||uid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('personal-payable:'||uid::text,0));
 select base_currency into base from public.profiles where id=uid;if base is null then raise exception 'PERSONAL_BASE_CURRENCY_REQUIRED';end if;
 if cmd='SAVE'then
  if req is null or jsonb_typeof(t)is distinct from 'object'or not(t ?& array['product','side','mode','party','reference','description','principal','date','currency','account_id','source_id','schedule','finance','profit_share','zakatable'])or exists(select 1 from jsonb_object_keys(t)k where k not in('product','side','mode','party','reference','description','principal','date','currency','account_id','source_id','schedule','finance','profit_share','zakatable'))then raise exception 'VALIDATION_FAILED';end if;
  principal:=(t->>'principal')::numeric;start_dt:=(t->>'date')::date;
  if coalesce(t->>'product','')not in('QARD','FINANCING','PARTICIPATION')or coalesce(t->>'side','')not in('RECEIVABLE','PAYABLE')or coalesce(t->>'mode','')not in('NEW','OPENING','LINKED')or t->>'currency'is distinct from base or principal is null or principal<=0 or principal>1e12 or principal<>round(principal,4)or principal::text in('NaN','Infinity','-Infinity')or start_dt is null or start_dt>(now()at time zone 'Asia/Riyadh')::date or (t->>'date')!~'^\d{4}-\d{2}-\d{2}$'or length(trim(coalesce(t->>'party','')))not between 1 and 120 or length(trim(coalesce(t->>'reference','')))not between 1 and 120 or length(trim(coalesce(t->>'description','')))not between 3 and 500 or jsonb_typeof(t->'zakatable')is distinct from 'boolean'then raise exception 'VALIDATION_FAILED';end if;
  if t->>'mode'='NEW'and nullif(t->>'account_id','')is null or t->>'mode'='LINKED'and(nullif(t->>'source_id','')is null or t->>'product'='PARTICIPATION')or t->>'mode'<>'LINKED'and nullif(t->>'source_id','')is not null then raise exception 'PERSONAL_CONTRACT_SOURCE_INVALID';end if;
  if jsonb_typeof(t->'schedule')is distinct from 'array'or jsonb_array_length(t->'schedule')not between 1 and 48 then raise exception 'SCHEDULE_INVALID';end if;
  for item in select value from jsonb_array_elements(t->'schedule')loop
   amt:=(item->>'amount')::numeric;due:=(item->>'due_date')::date;
   if jsonb_typeof(item)is distinct from 'object'or exists(select 1 from jsonb_object_keys(item)k where k not in('amount','due_date'))or amt is null or amt<=0 or amt<>round(amt,4)or amt::text in('NaN','Infinity','-Infinity')or due is null or due<start_dt or due<last_due or (item->>'due_date')!~'^\d{4}-\d{2}-\d{2}$'then raise exception 'SCHEDULE_INVALID';end if;
   total:=total+amt;last_due:=due;
  end loop;if total<>principal then raise exception 'SCHEDULE_TOTAL_INVALID';end if;
  if (t->>'profit_share')::numeric is null or (t->>'profit_share')::numeric<0 or (t->>'profit_share')::numeric>100 or (t->>'profit_share')::numeric::text in('NaN','Infinity','-Infinity')then raise exception 'VALIDATION_FAILED';end if;
  if t->>'product'='FINANCING'then
   if jsonb_typeof(t->'finance')is distinct from 'object'or not(t->'finance'?&array['annualRate','method','repayment','frequencyMonths','yearDays'])or exists(select 1 from jsonb_object_keys(t->'finance')k where k not in('annualRate','method','repayment','frequencyMonths','yearDays'))or(t->'finance'->>'annualRate')::numeric<=0 then raise exception 'INVALID_FINANCE_TERMS';end if;
   plan:=public.calculate_financing_schedule((t->'finance')||jsonb_build_object('principal',principal,'startDate',start_dt,'firstDueDate',t->'schedule'->0->>'due_date','count',jsonb_array_length(t->'schedule')));
   for i in 0..jsonb_array_length(plan)-1 loop if(plan->i->>'principal')::numeric<>(t->'schedule'->i->>'amount')::numeric or plan->i->>'due_date'is distinct from t->'schedule'->i->>'due_date'then raise exception 'FINANCE_PLAN_MISMATCH';end if;end loop;
  elsif t->'finance' is distinct from 'null'::jsonb then raise exception 'INVALID_FINANCE_TERMS';end if;
  if p->>'id'is null then
   select * into c from public.personal_contracts where user_id=uid and request_id=req;
   if c.id is not null then if c.terms<>t then raise exception 'PERSONAL_CONTRACT_REQUEST_CONFLICT';end if;return to_jsonb(c);end if;
   insert into public.personal_contracts(user_id,request_id,product,side,terms,principal,currency)values(uid,req,t->>'product',t->>'side',t,principal,base)returning * into c;
  else
   select * into c from public.personal_contracts where id=(p->>'id')::uuid and user_id=uid for update;
   if c.id is null then raise exception 'PERSONAL_CONTRACT_ACCESS_DENIED';end if;
   if c.status<>'DRAFT'or c.revision is distinct from(p->>'expected_revision')::int then raise exception 'PERSONAL_CONTRACT_CHANGED';end if;
   update public.personal_contracts set product=t->>'product',side=t->>'side',terms=t,principal=personal_contract_command.principal,currency=base,revision=revision+1,updated_at=now()where id=c.id returning * into c;
  end if;
  insert into public.audit_logs(user_id,entity_type,entity_id,action,new_data)values(uid,'personal_contract',c.id,'SAVE',p);return to_jsonb(c);
 end if;
 select * into c from public.personal_contracts where id=(p->>'id')::uuid and user_id=uid for update;
 if c.id is null then raise exception 'PERSONAL_CONTRACT_ACCESS_DENIED';end if;
 if length(trim(coalesce(p->>'reason','')))not between 3 and 500 then raise exception 'VALIDATION_FAILED';end if;
 if c.currency<>base then raise exception 'PERSONAL_CONTRACT_BASE_CURRENCY_CHANGED';end if;
 t:=c.terms;start_dt:=(t->>'date')::date;
 if cmd='CANCEL'then
  if c.status='CANCELLED'then return to_jsonb(c);end if;
  if c.status<>'DRAFT'or c.revision is distinct from(p->>'expected_revision')::int then raise exception 'PERSONAL_CONTRACT_CHANGED';end if;
  update public.personal_contracts set status='CANCELLED',revision=revision+1,updated_at=now()where id=c.id returning * into c;
 elsif cmd='EXECUTE'then
  if c.status='POSTED'then return to_jsonb(c);end if;
  if c.status<>'DRAFT'or c.revision is distinct from(p->>'expected_revision')::int then raise exception 'PERSONAL_CONTRACT_CHANGED';end if;
  update public.personal_contracts set status='EXECUTING'where id=c.id;
  if t->>'mode'='LINKED'then
   if c.side='RECEIVABLE'then
    select id into aid from public.asset_accounts where id=(t->>'source_id')::uuid and user_id=uid and ownership_scope='PERSONAL'and organization_id is null and asset_type='RECEIVABLE'and currency=base and coalesce(metadata->>'archived','false')<>'true'for update;
    if aid is null or exists(select 1 from public.transactions where asset_account_id=aid and user_id=uid and transaction_date>start_dt)or exists(select 1 from public.personal_financings where receivable_id=aid and kind='ADVANCE')then raise exception 'PERSONAL_CONTRACT_SOURCE_INVALID';end if;
   else
    select id into pid from public.personal_payables where id=(t->>'source_id')::uuid and user_id=uid and currency=base and cancelled_at is null and event_date<=start_dt for update;
    if pid is null or exists(select 1 from public.personal_payable_payments where payable_id=pid and payment_date>start_dt)or exists(select 1 from public.personal_financings where payable_id=pid and kind='ADVANCE')then raise exception 'PERSONAL_CONTRACT_SOURCE_INVALID';end if;
   end if;
   if private.personal_contract_balance(aid,pid)<>c.principal then raise exception 'PERSONAL_CONTRACT_SOURCE_CHANGED';end if;
  elsif c.side='RECEIVABLE'then
   r:=private.personal_contract_asset(c.id,case when c.product='PARTICIPATION'then 'OTHER'::public.asset_type else 'RECEIVABLE'::public.asset_type end,case when t->>'mode'='OPENING'then c.principal else 0 end,start_dt,t->>'party','PRINCIPAL');aid:=(r->>'asset_id')::uuid;
   if nullif(r->>'transaction_id','')is not null then ids:=array[(r->>'transaction_id')::uuid];end if;
   update public.personal_contracts set asset_id=aid where id=c.id;
   if t->>'mode'='NEW'then r:=private.personal_contract_cash(c.id,(t->>'account_id')::uuid,aid,null,c.principal,start_dt,c.id,t->>'description','OUTFLOW');select coalesce(array_agg(value::uuid),'{}')into ids from jsonb_array_elements_text(r->'transaction_ids');end if;
  else
   r:=private.personal_payable_command(jsonb_build_object('action','CREATE','request_id',c.id,'party',t->>'party','description',t->>'description','amount',c.principal,'date',start_dt,'due_date',t->'schedule'->0->>'due_date','reference',t->>'reference'));pid:=(r->>'id')::uuid;
   update public.personal_contracts set payable_id=pid where id=c.id;
   if t->>'mode'='NEW'then r:=private.personal_contract_cash(c.id,(t->>'account_id')::uuid,null,null,c.principal,start_dt,c.id,t->>'description','INFLOW');select coalesce(array_agg(value::uuid),'{}')into ids from jsonb_array_elements_text(r->'transaction_ids');end if;
  end if;
  update public.personal_contracts set asset_id=aid,payable_id=pid where id=c.id;
  if c.product<>'PARTICIPATION'then perform private.assign_debt_category(case when aid is not null then 'PERSONAL_RECEIVABLE'else 'PERSONAL_PAYABLE'end,coalesce(aid,pid),case when aid is not null then 'P_AR_LOAN'else 'P_AP_LOAN'end);end if;
  insert into public.personal_contract_movements(user_id,contract_id,request_id,kind,amount,operation_date,notes,transaction_ids,fingerprint)values(uid,c.id,c.id,'FUND',c.principal,start_dt,p->>'reason',ids,md5(('EXECUTE:'||c.id)::text));
  update public.personal_contracts set status='POSTED',revision=revision+1,updated_at=now()where id=c.id returning * into c;
 else
  if req is null or dt is null or dt<start_dt or dt>(now()at time zone 'Asia/Riyadh')::date then raise exception 'VALIDATION_FAILED';end if;
  select * into prior from public.personal_contract_movements where user_id=uid and request_id=req;
  if prior.id is not null then if prior.contract_id<>c.id or prior.fingerprint<>fp then raise exception 'PERSONAL_CONTRACT_REQUEST_CONFLICT';end if;return to_jsonb(prior);end if;
  if exists(select 1 from public.personal_contract_movements where user_id=uid and reversal_request_id=req)and cmd<>'REVERSE'then raise exception 'PERSONAL_CONTRACT_REQUEST_CONFLICT';end if;
  if c.status<>'POSTED'then raise exception 'PERSONAL_CONTRACT_NOT_POSTED';end if;
  if exists(select 1 from public.personal_contract_movements where contract_id=c.id and reversed_at is null and operation_date>dt)then raise exception 'PERSONAL_CONTRACT_DATE_ORDER';end if;
  update public.personal_contracts set status='EXECUTING'where id=c.id;
  if cmd='REVERSE'then
   select * into m from public.personal_contract_movements where id=(p->>'movement_id')::uuid and contract_id=c.id and user_id=uid for update;
   if m.id is null then raise exception 'PERSONAL_CONTRACT_ACCESS_DENIED';end if;
   if m.reversed_at is not null then if m.reversal_fingerprint<>fp then raise exception 'PERSONAL_CONTRACT_REQUEST_CONFLICT';end if;update public.personal_contracts set status='POSTED'where id=c.id;return to_jsonb(m);end if;
   if exists(select 1 from public.personal_contract_movements where contract_id=c.id and reversed_at is null and(created_at,id)>(m.created_at,m.id))then raise exception 'PERSONAL_CONTRACT_REVERSE_LATEST_FIRST';end if;
   if m.kind in('CHARGE','PROFIT')and private.personal_contract_balance(m.asset_id,m.payable_id)<>m.amount then raise exception 'PERSONAL_CONTRACT_HAS_SETTLEMENTS';end if;
   if exists(select 1 from public.lots where source_transaction_id=any(m.transaction_ids)and(remaining_quantity<>original_quantity or remaining_value_base<>original_value_base))then raise exception 'SOURCE_LOT_ALREADY_CONSUMED';end if;
   if coalesce(array_length(m.transaction_ids,1),0)>0 then
    for i in reverse array_length(m.transaction_ids,1)..1 loop
     tid:=public.reverse_transaction(uid,m.transaction_ids[i]);
     if exists(select 1 from public.transactions where id=m.transaction_ids[i]and transaction_type in('TRANSFER_IN','ADD','OPENING_BALANCE'))then update public.lots set remaining_quantity=0,remaining_value_base=0,status='CLOSED'where user_id=uid and source_transaction_id=m.transaction_ids[i];end if;
    end loop;
   end if;
   if m.kind='LOSS'and c.payable_id is not null then update public.personal_payables set amount=case when cancel_reason='PERSONAL_CONTRACT_FULL_LOSS'then amount else amount+m.amount end,cancelled_at=null,cancel_reason=null where id=c.payable_id and user_id=uid;end if;
   if m.kind in('CHARGE','PROFIT')and m.payable_id is not null then update public.personal_payables set cancelled_at=now(),cancel_reason=p->>'reason'where id=m.payable_id and user_id=uid;end if;
   if m.kind='FUND'and t->>'mode'<>'LINKED'and c.payable_id is not null then update public.personal_payables set cancelled_at=now(),cancel_reason=p->>'reason'where id=c.payable_id and user_id=uid;end if;
   update public.personal_contract_movements set reversed_at=now(),reversal_request_id=req,reversal_fingerprint=fp where id=m.id returning * into m;
   update public.personal_contracts set status=case when m.kind='FUND'then 'CANCELLED'else 'POSTED'end,revision=revision+1,updated_at=now()where id=c.id returning * into c;
  else
   if cmd='CHARGE'then
    if c.product<>'FINANCING'or(p->>'number')::int is null then raise exception 'INVALID_FINANCE_TERMS';end if;
    plan:=public.calculate_financing_schedule((t->'finance')||jsonb_build_object('principal',c.principal,'startDate',start_dt,'firstDueDate',t->'schedule'->0->>'due_date','count',jsonb_array_length(t->'schedule')));
    item:=plan->((p->>'number')::int-1);due:=(item->>'due_date')::date;amt:=(item->>'finance')::numeric;
    if item is null or due>dt or amt<=0 then raise exception 'FINANCE_PERIOD_NOT_ENDED';end if;
    if exists(select 1 from public.personal_contract_movements where contract_id=c.id and kind='CHARGE'and installment_number=(p->>'number')::int and reversed_at is null)then raise exception 'PERSONAL_CONTRACT_CHARGE_EXISTS';end if;
   elsif cmd='PROFIT'then
    if c.product<>'PARTICIPATION'then raise exception 'PERSONAL_CONTRACT_PRODUCT_INVALID';end if;
    amt:=round(amt*(t->>'profit_share')::numeric/100,4);due:=dt;
   end if;
   if amt is null or amt<=0 or amt>1e12 or amt<>round(amt,4)or amt::text in('NaN','Infinity','-Infinity')then raise exception 'VALIDATION_FAILED';end if;
   if cmd in('CHARGE','PROFIT')then
    if c.side='RECEIVABLE'then r:=private.personal_contract_asset(c.id,'RECEIVABLE',amt,dt,t->>'party',cmd);aid:=(r->>'asset_id')::uuid;ids:=array[(r->>'transaction_id')::uuid];update public.asset_accounts set metadata=metadata||jsonb_build_object('due_date',due)where id=aid;
    else r:=private.personal_payable_command(jsonb_build_object('action','CREATE','request_id',req,'party',t->>'party','description',case when cmd='CHARGE'then 'تكلفة تمويل · 'else 'حصة ربح مستحقة · 'end||(t->>'reference'),'amount',amt,'date',dt,'due_date',due,'reference',t->>'reference'));pid:=(r->>'id')::uuid;end if;
    perform private.assign_debt_category(case when aid is not null then 'PERSONAL_RECEIVABLE'else 'PERSONAL_PAYABLE'end,coalesce(aid,pid),case when aid is not null then 'P_AR_OTHER'else 'P_AP_ACCRUAL'end);
   elsif cmd='LOSS'then
    if c.product<>'PARTICIPATION'or amt>private.personal_contract_balance(c.asset_id,c.payable_id)then raise exception 'PERSONAL_CONTRACT_LOSS_INVALID';end if;
    if c.payable_id is not null then update public.personal_payables set cancelled_at=case when amount=amt then now()else cancelled_at end,cancel_reason=case when amount=amt then 'PERSONAL_CONTRACT_FULL_LOSS'else cancel_reason end,amount=case when amount=amt then amount else amount-amt end where id=c.payable_id and user_id=uid;
    else remaining:=amt;qty:=0;for l in select * from public.lots where asset_account_id=c.asset_id and user_id=uid and remaining_quantity>0 and acquisition_date<=dt order by acquisition_date,created_at,id for update loop exit when remaining<=0;take:=least(remaining,l.remaining_value_base);qty:=qty+take*l.remaining_quantity/l.remaining_value_base;remaining:=remaining-take;end loop;if remaining>0 then raise exception 'CASH_LOT_REVIEW_REQUIRED';end if;tid:=public.post_withdrawal(uid,c.asset_id,dt,qty,amt,base,base,amt,p->>'reason','FIFO','WITHDRAWAL');ids:=array[tid];end if;
   else
    aid:=c.asset_id;pid:=c.payable_id;
    if cmd='SETTLE_CHARGE'then select * into m from public.personal_contract_movements where id=(p->>'movement_id')::uuid and contract_id=c.id and user_id=uid and kind in('CHARGE','PROFIT')and reversed_at is null;if m.id is null then raise exception 'PERSONAL_CONTRACT_ACCESS_DENIED';end if;aid:=m.asset_id;pid:=m.payable_id;end if;
