-- Stable annual source vouchers. No balances, dates or source records are rewritten.
create table private.voucher_sequence_counters(
 scope_key text not null, prefix text not null, issue_year int not null,
 last_value bigint not null check(last_value>0),primary key(scope_key,prefix,issue_year)
);
alter table private.voucher_sequence_counters enable row level security;
create policy voucher_counter_internal on private.voucher_sequence_counters to postgres using(true) with check(true);
revoke all on private.voucher_sequence_counters from public,anon,authenticated;
create table public.voucher_numbers(
 source_table text not null,source_id uuid not null,owner_id uuid,organization_id uuid,
 scope_key text not null,prefix text not null,issue_year int not null,sequence bigint not null check(sequence>0),
 document_number text not null,source_created_at timestamptz not null,
 canonical_table text,canonical_id uuid,
 primary key(source_table,source_id),
 check(organization_id is not null or owner_id is not null),
 check((canonical_table is null)=(canonical_id is null))
);
create unique index voucher_number_unique on public.voucher_numbers(scope_key,prefix,issue_year,sequence) where canonical_id is null;
create index voucher_number_owner on public.voucher_numbers(owner_id) where organization_id is null;
create index voucher_number_org on public.voucher_numbers(organization_id);
create index voucher_number_source on public.voucher_numbers(source_id);
alter table public.voucher_numbers enable row level security;
revoke all on public.voucher_numbers from public,anon,authenticated;
grant select on public.voucher_numbers to authenticated;
create policy voucher_number_read on public.voucher_numbers for select to authenticated using(
 (organization_id is null and owner_id=(select auth.uid())) or
 (organization_id is not null and organization_id in(select m.organization_id from public.organization_members m where m.user_id=(select auth.uid()) and m.status='ACTIVE'))
);
create function private.ensure_voucher_number(p_table text,p jsonb,p_stack text[] default '{}') returns text
language plpgsql security definer set search_path='' as $$
declare sid uuid:=(p->>'id')::uuid;uid uuid:=coalesce(nullif(p->>'user_id','')::uuid,nullif(p->>'created_by','')::uuid);
 org uuid:=nullif(p->>'organization_id','')::uuid;stamp timestamptz;scope text;yr int;prefix text;seq bigint;result text;
 kind text:=coalesce(p->>'kind',p->>'transaction_type',p->>'event_type','');alias_table text;alias_id uuid;target jsonb;parent jsonb;canonical public.voucher_numbers%rowtype;
 key text:=p_table||':'||(p->>'id');official text;mode text;side text;
begin
 if sid is null or p_table<>all(array['transactions','personal_payables','personal_contracts','personal_contract_movements','personal_financings','debt_contracts','financial_events','liquidity_flows','liquidity_settlements','transfers','liquidity_transfers','liquidity_intercompany_transfers','participation_contracts','participation_movements','investment_contracts','investment_operations','zakat_payments','debt_payroll_requests','debt_operation_requests','vat_documents'])then raise exception 'VOUCHER_SOURCE_INVALID';end if;
 select document_number into result from public.voucher_numbers where source_table=p_table and source_id=sid;
 if found then return result;end if;
 if key=any(p_stack) or cardinality(p_stack)>20 then return null;end if;
 p_stack:=array_append(p_stack,key);
 stamp:=nullif(p->>'created_at','')::timestamptz;
 if p_table='transfers' then select t.created_at into stamp from public.transactions t where t.id=nullif(p->>'source_transaction_id','')::uuid;end if;
 stamp:=coalesce(stamp,nullif(p->>'transfer_date','')::date::timestamptz,clock_timestamp());
 if p_table='liquidity_intercompany_transfers' then org:=(p->>'source_organization_id')::uuid;end if;
 if p_table='personal_contracts' then
  mode:=p->'terms'->>'mode';side:=p->>'side';
  prefix:=case when mode='OPENING'then 'OB'when p->>'product'='FINANCING'then 'FN'when p->>'product'='PARTICIPATION'then 'IC'when side='PAYABLE'then 'LR'else 'LG'end;
 elsif p_table='personal_financings' then prefix:=case when kind='ADVANCE'then 'AD'when p->>'side'='PAYABLE'then 'LR'else 'LG'end;
 elsif p_table='personal_contract_movements' then
  select to_jsonb(c)into parent from public.personal_contracts c where c.id=(p->>'contract_id')::uuid;
  prefix:=case when kind in('SETTLE','SETTLE_CHARGE')then case when parent->>'side'='RECEIVABLE'then 'RC'else 'PV'end when kind='CHARGE'then 'FC'when kind='PROFIT'then 'PF'when kind='LOSS'then 'LS'else 'AJ'end;
  if kind='FUND'then alias_table:='personal_contracts';alias_id:=(p->>'contract_id')::uuid;end if;
